VALUES ('055d1e13-cdf3-43b6-8c38-82c29b4c57f7', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 1, '2026-10-26', 'Comece por aqui: a Ética na prova', 'Como usar o ebook, o peso da Ética na 1ª fase, o raio-X da incidência por assunto, as mudanças recentes e as normas cobradas.');--> statement-breakpoint
