INSERT INTO `flashcard_sets` (`id`, `title`, `apostila_id`, `subject_id`, `card_count`)
VALUES ('71f3269a-e480-4df0-b989-e19ceab2112a', 'Ética — Cap. 1: Direitos e prerrogativas do advogado', '0929dd26-140b-49fd-8403-dd4a1bc275ea', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 17);--> statement-breakpoint
INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('07d3395d-d440-45b3-b00d-7848b0b30be1', '71f3269a-e480-4df0-b989-e19ceab2112a', 1, 'Certo ou errado? "Autos sigilosos podem ser vistos sem procuração"', 'Errado. Sigilo exige procuração.', 'medium'),
('72433a70-70f8-4abc-88d3-c148b1fb91a9', '71f3269a-e480-4df0-b989-e19ceab2112a', 2, 'Certo ou errado? "A autoridade pode negar acesso a diligências já documentadas"', 'Errado. Só as em andamento e ainda não documentadas.', 'medium'),
('d3b6220e-aa53-47af-bcd4-4bb3bf6a2d44', '71f3269a-e480-4df0-b989-e19ceab2112a', 3, 'Certo ou errado? "O desagravo depende de pedido do ofendido" ou "o ofendido pode dispensá-lo"', 'Errado.', 'medium'),
('7f11cfe5-535e-469e-b97d-2d41a10ac85b', '71f3269a-e480-4df0-b989-e19ceab2112a', 4, 'Certo ou errado? "Advogado preso por briga de trânsito exige representante da OAB"', 'Errado. Basta comunicar a Seccional.', 'medium'),
('c6eed8c1-a7bc-403a-b481-a1db54d62da0', '71f3269a-e480-4df0-b989-e19ceab2112a', 5, 'Certo ou errado? "Sala de Estado-Maior após a condenação definitiva"', 'Errado. Só antes do trânsito em julgado.', 'medium'),
('b3efea79-77bc-4bc5-aedd-a43d04cc8bb6', '71f3269a-e480-4df0-b989-e19ceab2112a', 6, 'Certo ou errado? "Vaga em garagem só em tribunais federais/superiores"', 'Errado. Vale para os fóruns dos tribunais em geral.', 'medium'),
('8aaf45ea-7805-4f7e-9bae-753c70ffabe8', '71f3269a-e480-4df0-b989-e19ceab2112a', 7, 'Certo ou errado? "Imunidade cobre calúnia/desacato"', 'Errado.', 'medium'),
('997d083e-0739-4457-9a2c-f9818849ad03', '71f3269a-e480-4df0-b989-e19ceab2112a', 8, 'Certo ou errado? "Pode retirar-se após 30 minutos mesmo que a autoridade já tenha comparecido e o ato esteja em andamento"', 'Errado. O direito só existe se a autoridade que preside o ato ainda não compareceu a ele, com comunicação protocolada em juízo (art. 7º, XX). O juiz estar no fórum, ocupado em outra audiência, não afasta o direito.', 'medium'),
('910a6baf-d3ec-4c17-bc03-1afc5304ffbd', '71f3269a-e480-4df0-b989-e19ceab2112a', 9, 'Há hierarquia entre advogado, juiz e promotor? Como ficam os advogados nas audiências?', 'Não há hierarquia. Nas audiências, os advogados das partes ficam no mesmo plano topográfico e equidistantes do juiz (EAOAB, art. 6º).', 'medium'),
('b3748c9a-278e-456e-bb55-57cb6cda58c4', '71f3269a-e480-4df0-b989-e19ceab2112a', 10, 'Autos sigilosos de investigação: o advogado precisa de procuração? O que a autoridade pode limitar?', 'Sim, só com procuração. A autoridade limita apenas diligências em andamento e ainda não documentadas (art. 7º, §§ 10 e 11).', 'medium'),
('75247d95-f00d-4b9e-9cf8-51f591ac6b4a', '71f3269a-e480-4df0-b989-e19ceab2112a', 11, 'Quais os requisitos para a busca no escritório do advogado?', 'Decisão judicial motivada, indícios de crime do próprio advogado, mandado específico e pormenorizado e representante da OAB presente (art. 7º, § 6º).', 'medium'),
('d1cf7737-ffbf-4bbe-8717-3877690e1c86', '71f3269a-e480-4df0-b989-e19ceab2112a', 12, 'O advogado pode fazer colaboração premiada contra cliente ou ex-cliente?', 'Não. A violação gera processo disciplinar e a pena pode chegar à exclusão (art. 7º, § 6º-I).', 'medium'),
('89caa874-56ca-425a-9fc8-e3c2bb52aa6d', '71f3269a-e480-4df0-b989-e19ceab2112a', 13, 'Prisão do advogado: o que se exige quando o motivo é ligado à profissão? E quando não é?', 'Ligado à profissão: só flagrante de crime inafiançável e com representante da OAB. Sem relação com a profissão: basta comunicar a Seccional.', 'medium'),
('160bad8a-f524-49ef-b8e2-9c9774543374', '71f3269a-e480-4df0-b989-e19ceab2112a', 14, 'Até quando o advogado tem direito à sala de Estado-Maior? E se não houver?', 'Só antes do trânsito em julgado. Na falta da sala, prisão domiciliar.', 'medium'),
('f6835d3c-4783-4be0-84e6-5af857214a1b', '71f3269a-e480-4df0-b989-e19ceab2112a', 15, 'Quais direitos têm a advogada gestante e a adotante ou que deu à luz?', 'Gestante: entra sem detector de metais e tem vaga na garagem. Adotante ou que deu à luz, sendo a única patrona: prazos processuais suspensos (art. 7º-A).', 'medium'),
('5c533542-28de-46b4-a1c9-0700d33b533b', '71f3269a-e480-4df0-b989-e19ceab2112a', 16, 'Quem pode provocar o desagravo público? O ofendido pode dispensá-lo?', 'É promovido de ofício ou a pedido de qualquer pessoa. O ofendido não pode dispensá-lo.', 'medium'),
('5b31c682-3178-4c11-abde-6b06b533acfa', '71f3269a-e480-4df0-b989-e19ceab2112a', 17, 'A imunidade profissional do advogado alcança quais crimes?', 'Injúria e difamação — nunca calúnia ou desacato.', 'medium');--> statement-breakpoint
