VALUES ('912a53da-b829-476b-bb5b-9720349cd481', 'Ética — Cap. 2: Honorários advocatícios (questões comentadas do ebook)', '1ed1bee6-5f56-4fa9-9569-dcb1628bf2f6', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('99e93ef2-b0eb-426f-a76b-36a1a06365e4', '912a53da-b829-476b-bb5b-9720349cd481', 1, '(46º Exame de Ordem (XLVI), questão 6) Abelardo é contratado para representar o milionário Everardo em uma causa cível de importante vulto. Ficou combinado que, em caso de êxito, Abelardo fará jus a uma joia de elevadíssimo valor, a título de honorários. Sucede que, depois de ganhar a causa, Everardo sofreu revés na justiça criminal, quando uma decisão judicial determinou o bloqueio de todo o seu patrimônio pela suspeita de crimes financeiros. Nesse caso, à luz do Estatuto da Ordem dos Advogados do Brasil e do Código de Ética e Disciplina, assinale a afirmativa correta.', '{"a":"Abelardo poderá requerer ao Juiz Criminal o desbloqueio de até 20% dos bens de Everardo para o pagamento de seus honorários e dos demais custos com a defesa.","b":"Abelardo poderá, diante do bloqueio, participar dos bens particulares de Everardo, de forma excepcional, considerada a impossibilidade de pagamento por outro meio, ainda que tal forma de pagamento não tenha sido pactuada.","c":"A cláusula de honorários de êxito ou quota litis não é vedada, mas deve necessariamente ser expressa em pecúnia, de modo que, prevendo-se a entrega de uma joia, constata-se a nulidade que determina que Abelardo só fará jus aos honorários de sucumbência, se houver.","d":"A cláusula de honorários de êxito ou quota litis é vedada, de sorte que será necessário proceder ao arbitramento dos honorários de Abelardo, em remuneração compatível com o trabalho e o valor econômico da questão, observado obrigatoriamente o disposto no Art. 85 do Código de Processo Civil."}', 'a', 'Com o bloqueio de todo o patrimônio do cliente por decisão judicial, o art. 24-A do Estatuto garante ao advogado a liberação de até 20% dos bens bloqueados para recebimento de honorários e reembolso de gastos com a defesa (a causa não envolve a Lei de Drogas). A alternativa B é errada porque a participação em bens do cliente exige ajuste escrito (CED, art. 50, § 1º). D erra porque a quota litis não é vedada. C erra ao concluir que o advogado perderia os honorários contratados e ficaria só com a sucumbência: a lei não prevê essa consequência.'),
('fe59b643-4bf6-47f3-9bd5-0f9a6381f93b', '912a53da-b829-476b-bb5b-9720349cd481', 2, '(36º Exame de Ordem (XXXVI), questão 1) Celso, advogado, foi contratado por Maria, servidora pública, para ajuizar ação com pedido de pagamento de determinada gratificação. O contrato celebrado entre eles prevê que Celso somente receberá honorários caso a demanda seja exitosa, em percentual do proveito econômico obtido por Maria. Em tal caso, é correto afirmar que', '{"a":"os honorários contratuais não poderão incidir sobre o valor das parcelas vincendas da gratificação.","b":"os honorários foram pactuados de forma correta, já que, nessa hipótese, deveriam ser necessariamente representados por pecúnia.","c":"os honorários não podem ser superiores às vantagens advindas a favor de Maria, exceto se acrescidos aos honorários de sucumbência.","d":"os honorários contratuais não poderão incidir sobre o valor das parcelas vencidas da gratificação."}', 'b', 'Na cláusula quota litis, o art. 50 do CED exige que os honorários sejam representados por pecúnia — exatamente o que ocorreu (percentual do proveito econômico). Como a causa envolve gratificação (prestações vencidas e vincendas), o § 2º permite que os honorários incidam sobre umas e outras, o que torna A e D erradas. C inverte a regra: somados à sucumbência, os honorários não podem superar as vantagens do cliente.');--> statement-breakpoint
