INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('4e10d154-879d-489e-8c5c-a0e6f58c51b2', 'f9aecff3-2c90-4108-bd65-1c7924098105', 1, 'Certo ou errado? "Sem estipulação, metade no início e metade no fim"', 'Errado. São terços.', 'medium'),
('2404f215-baf2-4e96-aeea-fb7ee6ea77c9', 'f9aecff3-2c90-4108-bd65-1c7924098105', 2, 'Certo ou errado? "Prescrição em 3 anos" ou "contada da data do contrato"', 'Errado.', 'medium'),
('d535ffd0-362f-4934-bc65-ac4b69be9da5', 'f9aecff3-2c90-4108-bd65-1c7924098105', 3, 'Certo ou errado? "Pode protestar duplicata de honorários"', 'Errado. Só cheque ou promissória.', 'medium'),
('87b8b633-14ac-4b9d-beb6-017a8af34bfd', 'f9aecff3-2c90-4108-bd65-1c7924098105', 4, 'Certo ou errado? "Quota litis é proibida"', 'Errado. É permitida, em dinheiro e com limite.', 'medium'),
('1aea3f1b-e127-40e7-8f63-6cc3c2be0692', 'f9aecff3-2c90-4108-bd65-1c7924098105', 5, 'Certo ou errado? "Liberação de até 20% também nos crimes da Lei de Drogas"', 'Errado.', 'medium'),
('f62df15d-1e89-4a88-889e-501d79c443e3', 'f9aecff3-2c90-4108-bd65-1c7924098105', 6, 'Certo ou errado? "Substabelecido com reserva sempre precisa da intervenção do substabelecente"', 'Atenção à exceção do contrato próprio com o cliente.', 'medium'),
('bf1f4b97-6287-457f-80e4-4e9da62a61f6', 'f9aecff3-2c90-4108-bd65-1c7924098105', 7, 'Sem estipulação sobre a forma de pagamento, como são pagos os honorários?', '1/3 no início, 1/3 até a decisão de primeira instância e 1/3 no final (art. 22, § 3º).', 'medium'),
('9a805240-7f6a-4dc0-bf21-409915ec2081', 'f9aecff3-2c90-4108-bd65-1c7924098105', 8, 'Em quanto tempo prescreve a cobrança de honorários? E a prestação de contas contra o advogado?', 'Ambas em 5 anos (arts. 25 e 25-A).', 'medium'),
('808edb50-3822-4c67-9dfe-859d37a58511', 'f9aecff3-2c90-4108-bd65-1c7924098105', 9, 'Bloqueio universal de bens do cliente: quanto o advogado pode liberar para honorários? Há exceção?', 'Até 20% dos bens, salvo nas causas da Lei de Drogas (art. 24-A).', 'medium'),
('c91ebabf-6594-4cce-a9e1-15e8894dd44d', 'f9aecff3-2c90-4108-bd65-1c7924098105', 10, 'Quais os limites da cláusula quota litis?', 'Honorários em dinheiro; somados à sucumbência, não podem superar a vantagem do cliente (CED, art. 50).', 'medium'),
('2205f529-9fb8-4bff-a601-09b175b44f67', 'f9aecff3-2c90-4108-bd65-1c7924098105', 11, 'O advogado pode sacar duplicata para cobrar honorários?', 'Não. Pode emitir fatura e aceitar cartão de crédito (CED, arts. 52 e 53).', 'medium'),
('76fbf7f0-eb91-4a3c-922b-13a08db2d2ce', 'f9aecff3-2c90-4108-bd65-1c7924098105', 12, 'O que o advogado deve fazer antes de cobrar honorários em juízo do próprio cliente?', 'Renunciar antes ao mandato (CED, art. 54).', 'medium');--> statement-breakpoint
