VALUES ('3753c0aa-1b54-4564-89c4-6715589e4889', '8e588aaf-3b80-4d3d-a139-978d9c3badda', 1, 'Leitura: Infrações e sanções disciplinares', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('fe700481-015d-44e6-8ce6-5cd50b100a3c', '3753c0aa-1b54-4564-89c4-6715589e4889', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 3: Infrações e sanções disciplinares', '<table><tbody><tr><td><p><strong>3º</strong></p><p>lugar em incidência</p></td><td><p><strong>38</strong></p><p>questões em 48 provas</p></td><td><p><strong>8,5%</strong></p><p>das questões de Ética</p></td><td><p><strong>6</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>em queda</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Terceiro lugar geral. O segredo é saber <strong>qual sanção cabe a cada infração</strong> do art. 34 — a FGV quase sempre pergunta a pena, o quórum, a prescrição ou a reabilitação.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>EAOAB, arts. 34 a 43 (leia o art. 34 inteiro, com atenção aos incisos XVII a XXX)</li></ul></td></tr></tbody></table>
<h2>As quatro sanções (art. 35)</h2>
<p><strong>Censura, suspensão, exclusão e multa.</strong> Após o trânsito em julgado, constam dos assentamentos do inscrito, <strong>mas a censura não pode ser divulgada</strong> (art. 35, parágrafo único).</p>
<h2>Qual infração leva a qual pena</h2>
<table><thead><tr><th><p><strong>Sanção</strong></p></th><th><p><strong>Quando se aplica</strong></p></th></tr></thead><tbody><tr><td><p><strong>Censura</strong> (art. 36)</p></td><td><p>Incisos <strong>I a XVI e XXIX</strong> do art. 34; violação ao <strong>Código de Ética</strong>; violação ao Estatuto sem pena mais grave prevista</p></td></tr><tr><td><p><strong>Suspensão</strong> (art. 37)</p></td><td><p>Incisos <strong>XVII a XXV e XXX</strong>; <strong>reincidência</strong> em infração disciplinar</p></td></tr><tr><td><p><strong>Exclusão</strong> (art. 38)</p></td><td><p><strong>Três suspensões</strong>; incisos <strong>XXVI a XXVIII</strong> (falsa prova de requisito de inscrição, inidoneidade moral, crime infamante)</p></td></tr><tr><td><p><strong>Multa</strong> (art. 39)</p></td><td><p><strong>Cumulada</strong> com censura ou suspensão, havendo <strong>agravantes</strong>: de 1 a 10 anuidades</p></td></tr></tbody></table>
<p>Regras de ouro:</p>
<ul><li><strong>Censura</strong> pode ser <strong>convertida em advertência</strong>, por ofício reservado e sem registro nos assentamentos, se houver <strong>circunstância atenuante</strong> (art. 36, parágrafo único).</li><li><strong>Suspensão</strong>: impede o exercício profissional em <strong>todo o território nacional</strong>, de <strong>30 dias a 12 meses</strong> (art. 37, § 1º). Na <strong>falta de prestação de contas</strong> (XXI), dura <strong>até a satisfação integral da dívida</strong>, com correção (§ 2º); na <strong>inépcia profissional</strong> (XXIV), até <strong>novas provas de habilitação</strong> (§ 3º).</li><li><strong>Exclusão</strong>: exige manifestação favorável de <strong>2/3 dos membros do Conselho Seccional</strong> (art. 38, parágrafo único). Nova inscrição depende de <strong>provas de reabilitação</strong> (art. 11, § 3º).</li><li><strong>Multa</strong> nunca é aplicada isoladamente.</li><li>Suspenso ou excluído fica <strong>impedido de exercer o mandato</strong> (art. 42).</li></ul>
<h2>Infrações que a FGV mais usa</h2>
<ul><li><strong>Agenciador de causas</strong> com participação nos honorários (III) e <strong>captação de causas</strong> (IV) → censura.</li><li><strong>Advogar contra literal disposição de lei</strong> (VI) → censura; mas <strong>presume-se a boa-fé</strong> quando fundado na inconstitucionalidade, na injustiça da lei ou em julgado anterior.</li><li><strong>Entender-se com a parte adversa</strong> sem autorização do cliente ou ciência do advogado contrário (VIII).</li><li><strong>Abandonar a causa</strong> sem justo motivo ou antes de 10 dias da renúncia (XI).</li><li><strong>Recusar assistência jurídica</strong> quando nomeado por impossibilidade da Defensoria (XII).</li><li><strong>Deturpar</strong> lei, doutrina, julgado ou depoimento para iludir o juiz (XIV) → censura.</li><li><strong>Imputar crime a terceiro</strong> em nome do cliente <strong>sem autorização escrita</strong> dele (XV).</li><li><strong>Ajudar cliente a fraudar a lei</strong> (XVII), <strong>receber valores para aplicação ilícita</strong> (XVIII), <strong>locupletar-se</strong> (XX), <strong>não prestar contas</strong> (XXI), <strong>reter ou extraviar autos</strong> (XXII), <strong>inépcia</strong> (XXIV), <strong>conduta incompatível</strong> (XXV: jogo de azar reiterado, incontinência pública escandalosa, embriaguez ou toxicomania habituais) → suspensão.</li><li><strong>Assédio moral, assédio sexual ou discriminação</strong> (XXX, Lei 14.612/2023) → suspensão.</li><li><strong>Estagiário</strong> que pratica ato além da sua habilitação (XXIX) → censura.</li></ul>
<table><tbody><tr><td><p><strong>ATENÇÃO: MUDOU!</strong></p><p><strong>Anuidade em atraso não gera mais suspensão.</strong> O STF (RE 647.885, Tema 732, e ADI 7.020) declarou inconstitucional suspender o advogado por inadimplência (art. 34, XXIII, c/c art. 37, § 2º). A OAB pode cobrar a dívida (a certidão é título executivo), mas não impedir o exercício profissional por isso.</p></td></tr></tbody></table>
<h2>Atenuantes (art. 40)</h2>
<p>Falta cometida na <strong>defesa de prerrogativa</strong>; <strong>ausência de punição anterior</strong>; <strong>exercício assíduo e proficiente de mandato ou cargo na OAB</strong>; <strong>relevantes serviços</strong> à advocacia ou à causa pública.</p>
<h2>Reabilitação (art. 41)</h2>
<p>Pode ser pedida <strong>1 ano após o cumprimento</strong> da sanção, com provas de bom comportamento. Se a sanção decorreu de <strong>crime</strong>, depende também da <strong>reabilitação criminal</strong>.</p>
<h2>Prescrição (art. 43)</h2>
<ul><li><strong>5 anos</strong> contados da <strong>constatação oficial do fato</strong> (não da prática).</li><li><strong>Prescrição intercorrente</strong>: processo <strong>parado há mais de 3 anos</strong> aguardando despacho ou julgamento é arquivado.</li><li><strong>Interrupção</strong>: pela <strong>instauração</strong> do processo ou <strong>notificação válida</strong> do representado; pela <strong>decisão condenatória recorrível</strong> de órgão da OAB.</li></ul>
<table><tbody><tr><td><p><strong>COMO A FGV COBRA</strong></p><ul><li>Dá a conduta e pede a sanção correta, muitas vezes com um detalhe de quórum ou publicidade.</li><li>Cobra a combinação "censura + atenuante = advertência".</li><li>Usa a prescrição para confundir: "prazo contado do fato" × "da constatação oficial".</li></ul></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"A censura será publicada" → <strong>errado</strong>: não pode ser divulgada.</li><li>"Multa aplicada isoladamente" → <strong>errado</strong>.</li><li>"Exclusão por maioria absoluta" → <strong>errado</strong>: 2/3 do Conselho Seccional.</li><li>"Suspensão de 12 a 30 meses" → <strong>errado</strong>: 30 dias a 12 meses.</li><li>"Suspensão por não pagar anuidade" → <strong>não vale mais</strong> (STF).</li><li>"Reabilitação a qualquer tempo" → <strong>errado</strong>: 1 ano após cumprir a pena.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 3. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
