VALUES ('17d4c668-6f55-4388-9ed5-34b86de7cc56', 'Ética — Cap. 3: Infrações e sanções disciplinares (questões comentadas do ebook)', 'fe700481-015d-44e6-8ce6-5cd50b100a3c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('0ceb8011-ab9d-483a-aaae-27005a01b7cd', '17d4c668-6f55-4388-9ed5-34b86de7cc56', 1, '(46º Exame de Ordem (XLVI), questão 5) Mateus, advogado regularmente inscrito na OAB, contratou Marcos, profissional da área de vendas, para abordar pessoas nas imediações da agência do Instituto Nacional do Seguro Social da sua cidade, visando à captação de causas previdenciárias. Foi acertado que Marcos teria participação nos honorários advocatícios das causas que conseguisse agenciar. Constatados os fatos, e após o devido processo administrativo disciplinar, o Tribunal de Ética e Disciplina do Conselho Seccional competente aplicou a pena de censura a Mateus. Considerando o enunciado e o Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Havendo circunstâncias atenuantes, será possível substituir a sanção de censura pela aplicação isolada de multa.","b":"Transitada em julgado a decisão, a sanção aplicada a Mateus deverá constar dos seus assentamentos, dando-se ampla publicidade nos meios oficiais.","c":"A gravidade da conduta infracional de Mateus não permite a conversão da pena de censura em advertência, ainda que verificada a ausência de punição disciplinar anterior.","d":"A circunstância de Mateus exercer de modo assíduo e proficiente mandato em cargo ou qualquer órgão da OAB, caso comprovada, deverá ser considerada pelo Tribunal na aplicação da sanção disciplinar."}', 'd', 'Valer-se de agenciador com participação nos honorários (art. 34, III) é punido com censura (art. 36, I). A multa só se aplica cumulada com censura ou suspensão (A errada). A censura não pode ser publicada (art. 35, parágrafo único — B errada). Presente atenuante, a censura pode ser convertida em advertência (art. 36, parágrafo único — C errada). E o exercício assíduo e proficiente de mandato na OAB é atenuante expressa (art. 40, III).'),
('dc14d799-3cdc-455e-bf01-e9f8409f23a7', '17d4c668-6f55-4388-9ed5-34b86de7cc56', 2, '(45º Exame de Ordem (XLV), questão 5) O jovem Marcos foi contratado como auxiliar de escritório por renomada banca de advocacia. Autodidata e talentoso, Marcos aproveitava os momentos de folga para estudar os processos judiciais patrocinados pelo escritório e, apesar de nunca ter frequentado o curso de graduação em Direito, tornou-se relativamente conhecedor prático de muitos temas jurídicos. Com esse conhecimento, Marcos resolveu se inscrever no Exame da Ordem dos Advogados do Brasil, apresentando, para tanto, diploma falsificado de bacharel em Direito. Após a aprovação, Marcos se inscreveu como advogado na OAB, novamente fazendo uso do referido documento falso. Seis anos após esses fatos, uma denúncia anônima a respeito do ilícito ensejou a instauração do competente processo administrativo disciplinar. Considerando o enunciado e o Estatuto da Advocacia e da Ordem dos Advogados do Brasil, assinale a afirmativa correta.', '{"a":"A gravidade da conduta atribuída a Marcos atrai a competência do Conselho Federal da Ordem dos Advogados do Brasil para apurar e punir a infração disciplinar.","b":"Para a aplicação da sanção correspondente prevista em lei é necessária a manifestação de dois terços dos membros do Conselho Seccional competente.","c":"A sanção disciplinar prevista para a conduta de Marcos é a de suspensão, que deve perdurar até que seja apresentado documento idôneo, cumulada com a aplicação de multa.","d":"A pretensão à punibilidade da infração disciplinar encontra-se prescrita, uma vez que foi ultrapassado o prazo legal de cinco anos, contado da última data em que Marcos fez uso do documento falso."}', 'b', 'Usar diploma falso para se inscrever é fazer falsa prova de requisito de inscrição (art. 34, XXVI), punida com exclusão (art. 38, II), que exige 2/3 dos membros do Conselho Seccional (art. 38, parágrafo único). A competência é da Seccional (A errada) e a pena não é suspensão (C errada). A prescrição conta da constatação oficial do fato, e não do uso do documento (D errada).');--> statement-breakpoint
