INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('6e4e1a7a-cae4-4aad-9609-f37ff2cbce96', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 1, 'Certo ou errado? "A censura será publicada"', 'Errado. Não pode ser divulgada.', 'medium'),
('c82b5ebd-1433-4b3b-88df-22999619f920', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 2, 'Certo ou errado? "Multa aplicada isoladamente"', 'Errado.', 'medium'),
('61cdb4cf-9b6b-4827-8977-8212a104c986', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 3, 'Certo ou errado? "Exclusão por maioria absoluta"', 'Errado. 2/3 do Conselho Seccional.', 'medium'),
('989152e2-9752-4d08-8317-4e21b811ff48', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 4, 'Certo ou errado? "Suspensão de 12 a 30 meses"', 'Errado. 30 dias a 12 meses.', 'medium'),
('1c727f0d-53dd-4e23-8acd-bece39c698cc', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 5, 'Certo ou errado? "Suspensão por não pagar anuidade"', 'Não vale mais (STF).', 'medium'),
('aba31398-0b74-4b71-9ba7-9e08fcb303a9', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 6, 'Certo ou errado? "Reabilitação a qualquer tempo"', 'Errado. 1 ano após cumprir a pena.', 'medium'),
('4a66e332-8345-4013-935c-7c8c1b53a4b3', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 7, 'A censura é publicada? Pode ser convertida?', 'Não é publicada e pode virar advertência, em ofício reservado, se houver atenuante.', 'medium'),
('8afff53e-1db6-4242-bb0f-df7d763a9999', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 8, 'Qual a duração e a abrangência da suspensão?', 'De 30 dias a 12 meses, em todo o território nacional.', 'medium'),
('a7a16768-7b0c-4807-957b-021f6b18679d', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 9, 'Quando cabe a exclusão e qual o quórum?', 'Três suspensões, falsa prova de requisito de inscrição, inidoneidade moral ou crime infamante; quórum de 2/3 do Conselho Seccional.', 'medium'),
('415f3529-8698-417f-a369-9b357d1a84fb', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 10, 'A multa pode ser aplicada isoladamente?', 'Não. A multa nunca é aplicada sozinha.', 'medium'),
('c7a5e2e9-12af-40d5-9a18-6d3e9e7e1120', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 11, 'Qual o prazo da prescrição disciplinar? E a prescrição intercorrente?', '5 anos da constatação oficial do fato; o processo parado por mais de 3 anos gera prescrição intercorrente (art. 43).', 'medium'),
('553784e6-ab38-4cef-9eba-9bbb2a08595c', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 12, 'Quando o advogado punido pode pedir reabilitação?', '1 ano após cumprir a sanção; se a infração resultou de crime, depende também da reabilitação criminal (art. 41).', 'medium'),
('7cb85675-e2d8-47ae-bb1b-ed106b9bac30', 'ceefdfcf-549e-49b3-b830-59eec45f690d', 13, 'A anuidade em atraso pode gerar suspensão do advogado?', 'Não. O STF declarou inconstitucional a suspensão por anuidade em atraso.', 'medium');--> statement-breakpoint
