INSERT INTO `training_days` (`id`, `training_id`, `day_number`, `date`, `title`, `description`)
VALUES ('93c28dd7-7c1a-41eb-84c2-90c4ea9c6c6b', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 5, '2026-10-30', 'Capítulo 4 — Sociedade de advogados e advogado associado', 'Assunto que cresceu nas provas recentes por causa de duas reformas: a sociedade unipessoal (Lei 13.247/2016) e o advogado associado (Lei 14.365/2022). Nas últimas 12 provas, só perdeu para prerrogativas.');--> statement-breakpoint
