INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('b26a945d-5723-4d12-b53c-97e4525eb3d8', '3f207921-0763-466a-8e9e-70b43a2a19b1', 1, '(46º Exame de Ordem (XLVI), questão 4) Os advogados Eduardo e Diogo são sócios de uma sociedade profissional de advogados, cujos atos constitutivos foram devidamente registrados e aprovados pelo Conselho Seccional da OAB na base territorial em que está localizada a sua sede. No entanto, Eduardo foi contratado por Afonso para representá-lo em uma ação de alimentos movida por sua esposa Dalila, e Diogo foi contratado por Dalila para representá-la na mesma ação. Os advogados desejam saber se podem continuar com essas representações, tendo em vista que são sócios da mesma sociedade de advogados. Sobre o caso narrado, com base no Art. 15 do Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Eduardo e Diogo não podem representar, em juízo, clientes com interesses opostos, por serem sócios da mesma sociedade de advogados.","b":"Eduardo e Diogo podem representar Afonso e Dalila em juízo, desde que firmem compromisso por escrito de que não haverá conflito de interesse entre os dois advogados.","c":"Eduardo e Diogo podem continuar com as respectivas representações de Afonso e Dalila, desde que informem previamente ao Juiz que ambos fazem parte da mesma sociedade.","d":"Eduardo e Diogo podem continuar com as representações, desde que cada um atue de forma independente dentro da sociedade de advogados, contando com corpo auxiliar próprio."}', 'a', 'Regra literal do art. 15, § 6º, do Estatuto: os advogados sócios de uma mesma sociedade profissional não podem representar em juízo clientes de interesses opostos. Nenhuma providência — compromisso escrito, aviso ao juiz ou atuação independente — afasta a vedação.'),
('32b4b62c-1748-4281-9208-1657073c7554', '3f207921-0763-466a-8e9e-70b43a2a19b1', 2, '(45º Exame de Ordem (XLV), questão 8) Pedro é advogado regularmente inscrito no Conselho Seccional da OAB do Estado Alfa e constituiu uma Sociedade Unipessoal de Advocacia registrada e ativa na mesma unidade federativa. Recentemente, ele foi convidado pelo renomado advogado Abraão para integrar uma Sociedade de Advogados, também com sede no Estado Alfa, na qualidade de sócio. Pedro considerou a proposta promissora e cogita aceitá-la, acreditando que pode participar de ambas as sociedades, desde que evite atuar nos mesmos processos ou contra os interesses de clientes de uma delas. Sobre a decisão de Pedro, com base no Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Pedro poderá integrar ambas as sociedades, desde que atue em processos distintos e jamais represente partes com interesses opostos.","b":"Pedro poderá aceitar o convite de Abraão apenas se encerrar formalmente a Sociedade Unipessoal de Advocacia que já possui no Estado Alfa.","c":"Pedro poderá participar das duas sociedades se firmar declaração formal de que manterá independência profissional e não haverá conflito de interesses.","d":"Pedro poderá manter a sua sociedade unipessoal e, ao mesmo tempo, integrar a sociedade de Abraão desde que a nova sociedade registre filial em outra área territorial, ainda que continue atuando no Estado Alfa."}', 'b', 'O art. 15, § 4º, proíbe integrar simultaneamente uma sociedade de advogados e uma sociedade unipessoal com sede ou filial na mesma área territorial do mesmo Conselho Seccional. Como as duas estão no Estado Alfa, Pedro só pode aceitar o convite se encerrar a unipessoal. Atuar em processos distintos ou declarar independência não resolve (A e C); abrir filial fora não muda o fato de ambas terem sede em Alfa (D).');--> statement-breakpoint
