INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`)
SELECT UUID(), '049e306a-2d4a-489c-b395-1841d7633e78', ROW_NUMBER() OVER (ORDER BY e.`exam_number` DESC, eq.`number`),
  CONCAT('(', e.`exam_number`, 'º Exame de Ordem, questão ', eq.`number`, ') ', eq.`statement`),
  eq.`alternatives`, LOWER(eq.`correct_answer`), NULL
FROM `exam_questions` eq
JOIN `exams` e ON e.`id` = eq.`exam_id`
JOIN `ebook_topics` et ON et.`id` = eq.`ebook_topic_id`
WHERE et.`subject_id` = (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1) AND et.`order` = 4
  AND LOWER(eq.`correct_answer`) IN ('a', 'b', 'c', 'd')
  AND (e.`exam_number`, eq.`number`) NOT IN ((46, 4), (45, 8));--> statement-breakpoint
