INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('8c8cdb45-9b46-43d4-90e5-1ab4a634c687', '74dcd9dc-baec-4b35-b106-12b650ef1949', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 5: Relações com o cliente', '<table><tbody><tr><td><p><strong>5º</strong></p><p>lugar em incidência</p></td><td><p><strong>31</strong></p><p>questões em 48 provas</p></td><td><p><strong>7,0%</strong></p><p>das questões de Ética</p></td><td><p><strong>3</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>em queda</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Tema quase todo do <strong>Código de Ética (arts. 9º a 26)</strong>, cobrado com casos de renúncia, revogação, conflito entre clientes e procuração de quem já tem advogado.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>CED, arts. 9º a 26</li><li>EAOAB, art. 5º, § 3º (renúncia)</li><li>Regulamento Geral, art. 6º</li></ul></td></tr></tbody></table>
<h2>Confiança e independência</h2>
<ul><li>O advogado deve informar o cliente, de forma clara e inequívoca, sobre os <strong>riscos</strong> da pretensão (art. 9º).</li><li>A relação se baseia na <strong>confiança recíproca</strong>. Se ela faltar, o advogado deve <strong>externar ao cliente sua impressão</strong> e, se a dúvida persistir, <strong>substabelecer ou renunciar</strong> (art. 10).</li><li>Como patrono, o advogado <strong>imprime à causa a orientação que lhe pareça mais adequada</strong>, <strong>sem se subordinar</strong> às intenções contrárias do cliente, mas procurando <strong>esclarecê-lo</strong> sobre a estratégia (art. 11).</li></ul>
<h2>Fim do mandato</h2>
<ul><li>Concluída ou desistida a causa, o advogado <strong>devolve bens, valores e documentos</strong> e <strong>presta contas pormenorizadas</strong> (art. 12).</li><li>Concluída a causa ou arquivado o processo, <strong>presume-se cumprido e extinto o mandato</strong> (art. 13).</li><li>O mandato <strong>não se extingue pelo decurso do tempo</strong>, salvo se o instrumento fixar prazo (art. 18).</li><li><strong>Revogação</strong> pelo cliente: não o desobriga dos honorários contratados, e o advogado mantém a sucumbência <strong>proporcional</strong> (art. 17).</li></ul>
<h2>Renúncia</h2>
<ul><li>O advogado deve <strong>notificar o cliente</strong>, preferencialmente por <strong>carta com aviso de recebimento</strong>, e depois comunicar o juízo (RG, art. 6º).</li><li>Continua representando o cliente <strong>durante os 10 dias seguintes à notificação</strong>, salvo se for <strong>substituído antes</strong> (EAOAB, art. 5º, § 3º).</li><li>A renúncia <strong>omite o motivo</strong> (CED, art. 16).</li><li>Diante de <strong>dificuldades insuperáveis</strong> ou <strong>inércia do cliente</strong>, é recomendável renunciar, e não abandonar a causa (art. 15).</li></ul>
<h2>Procuração de quem já tem advogado (art. 14)</h2>
<p>O advogado <strong>não deve aceitar</strong> procuração de quem já tem patrono constituído <strong>sem prévio conhecimento deste</strong>, <strong>salvo</strong> por motivo plenamente justificável ou para <strong>medidas judiciais urgentes e inadiáveis</strong>.</p>
<h2>Conflitos de interesse</h2>
<ul><li>Surgindo conflito entre constituintes e não conseguindo harmonizá-los, o advogado <strong>opta por um dos mandatos</strong> e <strong>renuncia aos demais</strong>, resguardado o sigilo (art. 20).</li><li>Ao atuar <strong>contra ex-cliente ou ex-empregador</strong>, deve resguardar o <strong>sigilo</strong> (art. 21).</li><li>Deve se abster de patrocinar causa contra a validade de <strong>ato jurídico que ajudou a formar</strong> (art. 22).</li></ul>
<h2>Outras regras</h2>
<ul><li>É <strong>direito e dever</strong> assumir a <strong>defesa criminal</strong>, sem considerar a própria opinião sobre a culpa do acusado (art. 23).</li><li>O advogado <strong>não é obrigado</strong> a aceitar que o cliente imponha <strong>outros advogados</strong> para atuar com ele (art. 24).</li><li>É vedado atuar no mesmo processo, ao mesmo tempo, como <strong>patrono e preposto</strong> do cliente ou empregador (art. 25).</li><li><strong>Substabelecimento com reserva</strong> é ato pessoal do advogado; <strong>sem reserva</strong> exige <strong>prévio e inequívoco conhecimento do cliente</strong> (art. 26).</li></ul>
<table><tbody><tr><td><p><strong>COMO A FGV COBRA</strong></p><ul><li>"Advogado recebe procuração de cliente que já tem patrono": a resposta quase sempre gira em torno da exceção da <strong>urgência</strong>.</li><li>Prazos e forma da renúncia (10 dias, carta com AR, omissão do motivo).</li><li>Mandato "antigo": o tempo, sozinho, não extingue.</li></ul></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"O advogado deve seguir a orientação do cliente sobre a estratégia" → <strong>errado</strong>.</li><li>"Renúncia deve declarar o motivo" → <strong>errado</strong>.</li><li>"Mandato se extingue após X anos" → <strong>errado</strong>, salvo prazo no instrumento.</li><li>"Substabelecimento com reserva exige ciência do cliente" → <strong>errado</strong>: essa exigência é do <strong>sem</strong> reserva.</li><li>"Em conflito entre clientes, deve renunciar a todos" → <strong>errado</strong>: opta por um.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 5. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('4457a564-fad8-46eb-9ab8-5f885854de19', 'Ética — Cap. 5: Relações com o cliente (questões comentadas do ebook)', '8c8cdb45-9b46-43d4-90e5-1ab4a634c687', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('b70f6203-920c-45c2-bad9-744a766ea6a9', '4457a564-fad8-46eb-9ab8-5f885854de19', 1, '(40º Exame de Ordem (XL), questão 2) Sebastião, advogado, celebrou contrato de mandato com o cliente Amir, para representá-lo extrajudicialmente, tendo realizado diligências em prol da resolução do imbróglio. Desde a celebração do mandato, passaram-se mais de 20 (vinte) anos, mas as atividades para as quais Amir contratou Sebastião, por sua própria natureza, se protraíram no tempo, sendo ainda necessárias a Amir. Sobre a hipótese apresentada, assinale a afirmativa correta.', '{"a":"O mandato extinguiu-se pelo decurso do tempo, salvo se previsto prazo diverso no respectivo instrumento.","b":"O mandato extinguiu-se pelo decurso do tempo, sendo vedada a previsão de prazo diverso no respectivo instrumento.","c":"O mandato não se extinguiu pelo decurso do tempo, salvo se foi consignado prazo no respectivo instrumento.","d":"O mandato não se extinguiu pelo decurso do tempo, sendo vedada a estipulação de prazo no respectivo instrumento."}', 'c', 'O art. 18 do CED dispõe que o mandato judicial ou extrajudicial não se extingue pelo decurso do tempo, salvo se o contrário for consignado no instrumento. Vinte anos, sozinhos, não extinguem o mandato de Sebastião. A e B invertem a regra; D erra ao proibir a estipulação de prazo.'),
('b4ab21a7-fc1d-4800-86d2-8dae241cc0f4', '4457a564-fad8-46eb-9ab8-5f885854de19', 2, '(41º Exame de Ordem (XLI), questão 4) Ana Júlia, recentemente aprovada no Exame da Ordem dos Advogados do Brasil, aspira exercer sua nova atividade profissional de maneira comprometida com os deveres éticos e valores inerentes à elevada função pública da profissão. Nesse sentido, assinale a afirmativa que corretamente descreve a hipótese de cumprimento de dever ético por Ana Júlia.', '{"a":"Ana Júlia deverá, sempre que possível, estimular a conciliação e a mediação entre os litigantes, entendendo-se diretamente com a parte adversa, cujo eventual patrono constituído, na hipótese de haver a solução do conflito, deverá ser ulteriormente comunicado.","b":"Nos pleitos administrativos ou judiciais em que ingressar, Ana Júlia deverá atuar com destemor e independência, especialmente perante aquelas autoridades com as quais tenha vínculos negociais ou familiares.","c":"Ana Júlia deverá pugnar pela solução dos problemas da cidadania e pela efetivação dos direitos individuais, coletivos e difusos, dever que pode ser cumprido, por exemplo, com a adoção de política permanente de contratação de honorários advocatícios em valores abaixo da tabela da OAB.","d":"No exercício do seu mandato, Ana Júlia deverá atuar como patrona da parte e, portanto, imprimir à causa orientação que lhe pareça mais adequada, procurando esclarecer a estratégia traçada ao cliente, mas sem se subordinar às suas intenções contrárias."}', 'd', 'O art. 11 do CED diz que o advogado, como patrono, imprime à causa a orientação que lhe pareça mais adequada, sem se subordinar a intenções contrárias do cliente, mas procurando esclarecê-lo. A erra porque é vedado entender-se com a parte adversa que tenha patrono sem o assentimento dele (art. 2º, parágrafo único, VIII, d). B erra porque o advogado deve se abster de atuar perante autoridades com quem tenha vínculo negocial ou familiar. C erra porque contratar honorários aviltantes viola o CED.');--> statement-breakpoint
