INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('2e6d21e9-5045-425c-9d1e-966690d9809f', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 1, 'Certo ou errado? "O advogado deve seguir a orientação do cliente sobre a estratégia"', 'Errado.', 'medium'),
('305876d1-2850-460d-bc43-b9f61d3d4231', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 2, 'Certo ou errado? "Renúncia deve declarar o motivo"', 'Errado.', 'medium'),
('97c2050c-bd05-49f4-a3a7-c3c0d97e2412', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 3, 'Certo ou errado? "Mandato se extingue após X anos"', 'Errado. , salvo prazo no instrumento.', 'medium'),
('9a6288bc-94f9-48ae-a4d3-6df841adde0b', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 4, 'Certo ou errado? "Substabelecimento com reserva exige ciência do cliente"', 'Errado. Essa exigência é do sem reserva.', 'medium'),
('fddda12d-52b8-4ea1-bce6-1db3166c19ff', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 5, 'Certo ou errado? "Em conflito entre clientes, deve renunciar a todos"', 'Errado. Opta por um.', 'medium'),
('0dfe4d3a-d36c-4325-9d7c-fd114e322d1e', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 6, 'O mandato se extingue pelo decurso do tempo?', 'Não, salvo se o instrumento fixar prazo (CED, art. 18).', 'medium'),
('d6a7c724-6a8c-4bf7-8301-2400cbf4ec8b', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 7, 'Como funciona a renúncia ao mandato?', 'Omite o motivo; notifica-se o cliente, preferencialmente por carta com AR, e o advogado continua representando por 10 dias, salvo substituição antes.', 'medium'),
('70a7b356-9174-4650-9b8c-3365502e8afe', '72b3aa1d-0d61-4ba3-a74d-bad859b9edcb', 8, 'O advogado pode aceitar procuração de quem já tem advogado constituído?', 'Só com prévio conhecimento do colega, salvo motivo plenamente justificável ou medidas urgentes e inadiáveis (CED, art. 14).', 'medium');--> statement-breakpoint
