INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`)
SELECT UUID(), 'eaae71d1-fac8-4eb3-bb0e-946a1c9f0509', ROW_NUMBER() OVER (ORDER BY e.`exam_number` DESC, eq.`number`),
  CONCAT('(', e.`exam_number`, 'º Exame de Ordem, questão ', eq.`number`, ') ', eq.`statement`),
  eq.`alternatives`, LOWER(eq.`correct_answer`), NULL
FROM `exam_questions` eq
JOIN `exams` e ON e.`id` = eq.`exam_id`
JOIN `ebook_topics` et ON et.`id` = eq.`ebook_topic_id`
WHERE et.`subject_id` = (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1) AND et.`order` = 5
  AND LOWER(eq.`correct_answer`) IN ('a', 'b', 'c', 'd')
  AND (e.`exam_number`, eq.`number`) NOT IN ((40, 2), (41, 4));--> statement-breakpoint
INSERT INTO `training_topics` (`id`, `training_day_id`, `order`, `title`, `type`, `subject_id`, `content`, `estimated_minutes`)
VALUES ('08d59079-f991-4a15-9cca-050c4dc6eb61', 'a6bec414-1f5e-4bbc-a3b6-8e6bb38cd46a', 4, 'Questões de provas anteriores da OAB', 'exercise', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '{"exerciseSetId":"eaae71d1-fac8-4eb3-bb0e-946a1c9f0509"}', 30);--> statement-breakpoint
INSERT INTO `training_days` (`id`, `training_id`, `day_number`, `date`, `title`, `description`)
VALUES ('3ac3f52d-c0c1-4c39-88df-bd6c11e800de', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 7, '2026-11-03', 'Capítulo 6 — Publicidade profissional', 'Um dos temas com mais "casos do cotidiano": cartão de visita, redes sociais, outdoor, coluna em jornal. A regra-mãe é simples: publicidade informativa, discreta e sóbria, sem captação de clientela nem mercantilização.');--> statement-breakpoint
INSERT INTO `training_topics` (`id`, `training_day_id`, `order`, `title`, `type`, `subject_id`, `content`, `estimated_minutes`)
VALUES ('f68e8cc3-6c85-45e2-8b55-e0c17a49cbe4', '3ac3f52d-c0c1-4c39-88df-bd6c11e800de', 1, 'Leitura: Publicidade profissional', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('42ae494f-808c-46af-949b-e02f82e07db3', 'f68e8cc3-6c85-45e2-8b55-e0c17a49cbe4', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 6: Publicidade profissional', '<table><tbody><tr><td><p><strong>6º</strong></p><p>lugar em incidência</p></td><td><p><strong>30</strong></p><p>questões em 48 provas</p></td><td><p><strong>6,7%</strong></p><p>das questões de Ética</p></td><td><p><strong>8</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>estável</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Um dos temas com mais "casos do cotidiano": cartão de visita, redes sociais, outdoor, coluna em jornal. A regra-mãe é simples: publicidade <strong>informativa, discreta e sóbria</strong>, sem <strong>captação de clientela</strong> nem <strong>mercantilização</strong>.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>CED, arts. 39 a 47-A</li><li>EAOAB, arts. 1º, § 3º, 14, parágrafo único, e 34, IV e XIII</li><li>Provimento 205/2021 do Conselho Federal (marketing jurídico)</li></ul></td></tr></tbody></table>
<h2>Princípios (CED, art. 39)</h2>
<p>Caráter <strong>meramente informativo</strong>, <strong>discrição e sobriedade</strong>, sem configurar <strong>captação de clientela</strong> ou <strong>mercantilização</strong> da profissão.</p>
<h2>Meios vedados (CED, art. 40)</h2>
<ul><li><strong>Rádio, cinema e televisão</strong> (veiculação de anúncios).</li><li><strong>Outdoors, painéis luminosos</strong> ou formas assemelhadas.</li><li><strong>Inscrições em muros, paredes, veículos, elevadores</strong> ou qualquer espaço público.</li><li><strong>Divulgação da advocacia junto com outra atividade</strong> ou indicação de vínculo entre elas — regra também do <strong>EAOAB, art. 1º, § 3º</strong>.</li><li><strong>Dados de contato</strong> (endereço, telefone) em colunas, artigos, programas de rádio/TV ou matérias na internet — <strong>o e-mail pode</strong>.</li><li><strong>Mala direta, panfletos</strong> e formas assemelhadas com intuito de captação.</li><li><strong>Exceção:</strong> para <strong>identificar o escritório</strong>, são permitidos <strong>placas, painéis luminosos e inscrições na fachada</strong> (parágrafo único).</li></ul>
<h2>Imprensa e meios de comunicação (CED, arts. 41 a 43)</h2>
<p>É vedado ao advogado:</p>
<ul><li><strong>responder com habitualidade</strong> a consultas jurídicas nos meios de comunicação;</li><li><strong>debater causa sob o patrocínio de outro advogado</strong>;</li><li>abordar tema de modo a comprometer a dignidade da profissão;</li><li>divulgar <strong>listas de clientes e demandas</strong>;</li><li><strong>insinuar-se</strong> para reportagens e declarações públicas.</li></ul>
<p>Participação em programas e entrevistas deve ter objetivo <strong>ilustrativo, educacional e instrutivo</strong>, sem autopromoção nem incitação a litigar. Publicar <strong>habitualmente e sem necessidade</strong> alegações de causas pendentes também é infração (EAOAB, art. 34, XIII).</p>
<h2>Cartão de visita e anúncio (CED, art. 44)</h2>
<ul><li><strong>Obrigatório:</strong> nome (ou nome social) e <strong>número de inscrição</strong> na OAB.</li><li><strong>Permitido:</strong> títulos acadêmicos, distinções honoríficas relacionadas à vida profissional, instituições jurídicas de que faça parte, <strong>especialidades</strong> a que se dedicar, endereço, e-mail, <strong>site</strong>, <strong>QR code</strong>, <strong>logotipo</strong>, <strong>fotografia do escritório</strong>, horário de atendimento e idiomas (art. 44, § 1º).</li><li><strong>Proibido:</strong> <strong>fotografia pessoal</strong> ou de terceiros e menção a <strong>emprego, cargo ou função</strong> ocupados, atuais ou passados, <strong>salvo o de professor universitário</strong>.</li></ul>
<h2>Formas admitidas (CED, arts. 45 e 46)</h2>
<ul><li><strong>Patrocínio de eventos ou publicações científicas ou culturais</strong>.</li><li><strong>Boletins</strong> físicos ou eletrônicos sobre matéria cultural, <strong>restritos a clientes e interessados do meio jurídico</strong>.</li><li>Publicidade pela <strong>internet</strong> é permitida, com as mesmas diretrizes.</li></ul>
<h2>Provimento 205/2021 — marketing jurídico</h2>
<ul><li>Permite <strong>marketing de conteúdo</strong> e <strong>impulsionamento</strong> de publicações jurídicas informativas, inclusive em redes sociais.</li><li>Veda <strong>ostentação</strong>, <strong>promessa de resultado</strong>, menção a <strong>clientes e casos</strong>, oferta de serviços com foco em <strong>captação</strong> e divulgação de <strong>preços</strong> como chamariz.</li><li>Ainda não foi cobrado diretamente na prova, mas é a base atual do tema e tende a aparecer.</li></ul>
<h2>Termo de ajustamento de conduta (CED, art. 47-A)</h2>
<p>É admitido <strong>TAC</strong> no âmbito dos <strong>Conselhos Seccionais e do Conselho Federal</strong> para fazer cessar <strong>publicidade irregular</strong> de <strong>advogados e estagiários</strong> (Res. 04/2020). Caiu em duas provas seguidas.</p>
<table><tbody><tr><td><p><strong>COMO A FGV COBRA</strong></p><ul><li>Situações concretas: cartão com foto, advogado que também é corretor, contador ou médico, anúncio em outdoor, coluna de jornal com telefone.</li><li>A resposta certa quase sempre repete a vedação literal do art. 40 ou do art. 44, § 2º.</li><li>Nas provas mais recentes: <strong>divulgação conjunta com outra atividade</strong> (três vezes nas últimas seis provas).</li></ul></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Divulgação conjunta é permitida se as atividades tiverem afinidade ou forem da mesma pessoa" → <strong>errado</strong>.</li><li>"Placa luminosa na fachada é proibida" → <strong>errado</strong>: para identificar o escritório, pode.</li><li>"Pode indicar telefone em coluna de jornal" → <strong>errado</strong>; e-mail pode.</li><li>"Cartão pode mencionar que foi juiz ou promotor" → <strong>errado</strong>; só professor universitário.</li><li>"Fotografia do escritório no cartão é vedada" → <strong>errado</strong>: foto <strong>do escritório</strong> pode; foto <strong>pessoal</strong> não.</li><li>"TAC só para advogado, nunca para estagiário" → <strong>errado</strong>.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 6. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('de8825ad-c73c-465e-b9a2-22a4e740cd5e', 'Ética — Cap. 6: Publicidade profissional (questões comentadas do ebook)', '42ae494f-808c-46af-949b-e02f82e07db3', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('f3e643cb-55a8-40bc-b4ef-049bc28d8c63', 'de8825ad-c73c-465e-b9a2-22a4e740cd5e', 1, '(46º Exame de Ordem (XLVI), questão 7) Frederico, advogado, após alcançar grande sucesso na advocacia, decidiu se dedicar também à construção civil, passando a atuar simultaneamente nas duas áreas. Diante da afinidade temática entre o Direito Imobiliário e o setor de construção civil, Frederico teve a ideia de unir ambas as atividades em um único escritório, oferecendo aos clientes consultoria jurídica e serviços de incorporação imobiliária. Para divulgar o seu novo empreendimento, contratou um escritório de marketing, que produziu uma campanha publicitária conjunta, ressaltando seus trabalhos como advogado e como empreendedor da construção civil. Sobre o fato narrado, com base no Estatuto da OAB, assinale a afirmativa correta.', '{"a":"É possível a divulgação conjunta, desde que respeitados o decoro e a dignidade da advocacia, cabendo ao Tribunal de Ética e Disciplina da OAB avaliar a adequação da publicidade.","b":"É permitida a divulgação conjunta apenas quando a outra atividade também for regulamentada por entidade de classe, hipótese em que a OAB poderá celebrar o convênio para a publicidade cruzada.","c":"É vedada a divulgação conjunta de advocacia com outra atividade, ainda que exercida pela mesma pessoa e que haja afinidade entre os ramos, como ocorre entre a advocacia imobiliária e a construção civil.","d":"Em regra, não é possível divulgar a advocacia em conjunto com outra atividade, mas nesse caso seria permitido, pois as atividades são exercidas por uma mesma pessoa e possuem afinidade temática, inexistindo conflito ético."}', 'c', 'O Estatuto (art. 1º, § 3º) e o CED (art. 40, IV) vedam a divulgação da advocacia em conjunto com outra atividade. A vedação vale mesmo quando as atividades são exercidas pela mesma pessoa e têm afinidade temática, como direito imobiliário e construção civil. Não há exceção por decoro (A), por regulamentação da outra atividade (B) ou por afinidade (D).'),
('1abffc2d-f6c3-421e-baf9-730133cb9798', 'de8825ad-c73c-465e-b9a2-22a4e740cd5e', 2, '(36º Exame de Ordem (XXXVI), questão 3) A advogada Carolina e a estagiária de Direito Beatriz, que com ela atua, com o intuito de promover sua atuação profissional, valeram-se, ambas, de meios de publicidade vedados no Código de Ética e Disciplina da OAB. Após a verificação da irregularidade, indagaram sobre a possibilidade de celebração de termo de ajustamento de conduta tendo, como objeto, a adequação da publicidade. Considerando o caso narrado, assinale a afirmativa correta.', '{"a":"É admitida a celebração do termo de ajustamento de conduta apenas no âmbito do Conselho Federal da OAB, para fazer cessar a publicidade praticada pela advogada Carolina e pela estagiária Beatriz.","b":"É admitida a celebração do termo de ajustamento de conduta, no âmbito do Conselho Federal da OAB ou dos Conselhos Seccionais, para fazer cessar a publicidade praticada pela advogada Carolina, mas é vedado que o termo de ajustamento de conduta abranja a estagiária Beatriz.","c":"É vedada pelo Código de Ética e Disciplina da OAB a possibilidade de celebração de termo de ajustamento de conduta no caso narrado, uma vez que se trata de infração ética.","d":"É admitida a celebração do termo de ajustamento de conduta no âmbito do Conselho Federal da OAB ou dos Conselhos Seccionais, para fazer cessar a publicidade praticada pela advogada Carolina e também pela estagiária Beatriz."}', 'd', 'O art. 47-A do CED admite a celebração de termo de ajustamento de conduta no âmbito dos Conselhos Seccionais e do Conselho Federal para fazer cessar a publicidade irregular praticada por advogados e estagiários. Logo, o TAC pode abranger Carolina e Beatriz. A restringe o TAC ao Conselho Federal, B exclui a estagiária e C nega a possibilidade.');--> statement-breakpoint
