INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('3b4f8c07-366c-4784-a16c-b98832a84fbe', '96e80987-927d-4250-b0f6-07befd855bee', 1, 'Certo ou errado? "Divulgação conjunta é permitida se as atividades tiverem afinidade ou forem da mesma pessoa"', 'Errado.', 'medium'),
('0bad9b6e-9d6d-4699-bb05-b688f7b67663', '96e80987-927d-4250-b0f6-07befd855bee', 2, 'Certo ou errado? "Placa luminosa na fachada é proibida"', 'Errado. Para identificar o escritório, pode.', 'medium'),
('e746a4a5-bf10-4ab8-b999-33e5497422ce', '96e80987-927d-4250-b0f6-07befd855bee', 3, 'Certo ou errado? "Pode indicar telefone em coluna de jornal"', 'Errado. E-mail pode.', 'medium'),
('d5cdd7b8-6297-482d-94d2-4302c4aa4026', '96e80987-927d-4250-b0f6-07befd855bee', 4, 'Certo ou errado? "Cartão pode mencionar que foi juiz ou promotor"', 'Errado. Só professor universitário.', 'medium'),
('3efa7f83-2f2c-4f7c-b3f2-9743b687ae33', '96e80987-927d-4250-b0f6-07befd855bee', 5, 'Certo ou errado? "Fotografia do escritório no cartão é vedada"', 'Errado. Foto do escritório pode; foto pessoal não.', 'medium'),
('34138a92-282f-4bdb-8f1e-4442abe9aef2', '96e80987-927d-4250-b0f6-07befd855bee', 6, 'Certo ou errado? "TAC só para advogado, nunca para estagiário"', 'Errado.', 'medium'),
('4fb544aa-cbe1-4296-acd9-8e7f291b653c', '96e80987-927d-4250-b0f6-07befd855bee', 7, 'A advocacia pode ser divulgada em conjunto com outra atividade?', 'Não. A divulgação conjunta é sempre vedada (EAOAB, art. 1º, § 3º; CED, art. 40, IV).', 'medium'),
('612e11e3-3c4d-4a64-b67d-10aa1bd998b2', '96e80987-927d-4250-b0f6-07befd855bee', 8, 'O que pode e o que não pode constar no cartão de visita do advogado?', 'Foto do escritório pode; foto pessoal não; cargo ocupado não, salvo o de professor universitário.', 'medium');--> statement-breakpoint
