VALUES ('aaaf3f28-63db-4953-97a7-c8bc0324caf6', '3ac3f52d-c0c1-4c39-88df-bd6c11e800de', 4, 'Questões de provas anteriores da OAB', 'exercise', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '{"exerciseSetId":"71877288-4159-49ce-bedb-97fae88b35f9"}', 30);--> statement-breakpoint
INSERT INTO `training_days` (`id`, `training_id`, `day_number`, `date`, `title`, `description`)
VALUES ('83663853-03df-421e-8c58-e1c07ce37ac3', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 8, '2026-11-04', 'Capítulo 7 — Atividade de advocacia', 'Arts. 1º a 5º do Estatuto: o que é privativo de advogado, o que é nulo e como funciona o mandato. Nas provas recentes, o destaque é a consultoria sem mandato nem contrato (art. 5º, § 4º).');--> statement-breakpoint
