VALUES ('754aeb5a-db12-49e3-a28d-81570f1a6523', 'Ética — Cap. 7: Atividade de advocacia (questões comentadas do ebook)', '54008bfe-e985-4555-a6a4-de639328aa78', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('d2b6f7a0-0f46-4e6a-83ef-6956c90487b7', '754aeb5a-db12-49e3-a28d-81570f1a6523', 1, '(41º Exame de Ordem (XLI), questão 6) A advogada Marina prestou consultoria na área de Direito Tributário para uma sociedade empresária, analisando um tema importante para as funções da referida pessoa jurídica. Sobre a atividade da advogada, de acordo com o Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"A mencionada consultoria deve ser prestada exclusivamente de modo escrito e pressupõe formalização de contrato de honorários.","b":"Se a pessoa jurídica e a advogada assim acordarem, independentemente de mandato ou mesmo da formalização do contrato de honorários, é possível a prestação da consultoria por escrito ou verbalmente.","c":"Caso a consultoria seja prestada verbalmente, a concordância com essa forma deve ser expressa por ambas as partes em contrato escrito de prestação de serviços advocatícios.","d":"A consultoria prestada por Marina pode ser realizada de modo escrito ou verbalmente e, assim, o contrato de prestação de serviços advocatícios pode ser verbal ou escrito, mas é necessária a outorga de mandato."}', 'b', 'Desde a Lei 14.365/2022, o art. 5º, § 4º, do Estatuto prevê que a consultoria e a assessoria jurídicas podem ser exercidas de modo verbal ou por escrito, a critério do advogado e do cliente, e independem de outorga de mandato ou de formalização por contrato de honorários. As demais alternativas criam exigências que a lei não faz.'),
('146d0c52-de79-4dd3-8c52-9ba5571631bc', '754aeb5a-db12-49e3-a28d-81570f1a6523', 2, '(45º Exame de Ordem (XLV), questão 2) Helena concluiu seu mestrado em Administração Pública e acumulou significativo conhecimento jurídico, mas não possui formação em Direito nem inscrição nos quadros da OAB. Apesar disso, ela passou a oferecer consultoria jurídica e a atuar em audiências representando clientes. André, por sua vez, era advogado regularmente inscrito na OAB, porém foi suspenso do exercício profissional por prática de infração disciplinar. Mesmo suspenso, ele continuou a realizar atos privativos da advocacia, tais como peticionar e participar de audiências. Com base nessas situações hipotéticas, assinale a afirmativa correta.', '{"a":"Os atos praticados por André, após a sua suspensão da OAB, são nulos, pois ele está impedido de exercer a advocacia enquanto durar a suspensão.","b":"Os atos privativos da advocacia praticados por Helena, que não possui inscrição na OAB, são válidos, desde que seus clientes a autorizem expressamente, ratificando os atos por ela praticados.","c":"Os atos praticados por Helena são válidos, desde que restritos à consultoria extrajudicial e relacionados à administração pública, uma vez que ela não representa clientes em processos judiciais.","d":"Tanto os atos praticados por Helena quanto os atos praticados por André são anuláveis, porém sujeitos à convalidação, pois a atuação em audiências e a prática de consultoria jurídica, embora preferencialmente exercidas por advogados, podem, excepcionalmente, ser exercidas por pessoa com conhecimento jurídico."}', 'a', 'São nulos os atos privativos praticados por pessoa não inscrita (art. 4º, caput) e também os praticados por advogado suspenso (art. 4º, parágrafo único). Os atos de André, após a suspensão, são nulos. Os de Helena também seriam — por isso B, C e D, que falam em validade ou mera anulabilidade, estão erradas.');--> statement-breakpoint
