INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('4deea025-2291-4694-934e-827d3e4763e4', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 1, 'Certo ou errado? "Atos de não inscrito são anuláveis e podem ser ratificados pelo cliente"', 'Errado. São nulos.', 'medium'),
('166cc4c1-8649-405d-8b0d-b481a3a7174d', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 2, 'Certo ou errado? "Habeas corpus é privativo de advogado"', 'Errado.', 'medium'),
('424de1fa-39bc-4a0f-bf80-3de55467135f', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 3, 'Certo ou errado? "Consultoria exige contrato escrito ou procuração"', 'Errado.', 'medium'),
('eaac53ad-5179-4139-87eb-26caa0a45a50', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 4, 'Certo ou errado? "Procuração em 15 dias, improrrogáveis"', 'Errado. Prorrogáveis por igual período.', 'medium'),
('aa509857-6c69-4218-a576-11a7bbd90416', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 5, 'Certo ou errado? "Mandado de segurança pode ser impetrado por qualquer pessoa"', 'Errado. É privativo.', 'medium'),
('5aa8c671-159a-4e49-a251-229a6a25a2d8', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 6, 'Qual a consequência dos atos privativos praticados por não inscrito ou por advogado suspenso? O habeas corpus é privativo?', 'São nulos. O habeas corpus não é privativo de advogado.', 'medium'),
('fca28e9c-a952-467b-8c68-83a045e74bda', 'fb23d054-c5db-4f03-8b92-d37645851ffc', 7, 'A consultoria jurídica exige mandato ou contrato?', 'Não. Pode ser verbal, sem mandato e sem contrato (art. 5º, § 4º).', 'medium');--> statement-breakpoint
