INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('f72f0f80-d3d9-45d4-95d0-edfbcd71cb46', '37a41d9c-2a34-4b58-9930-fb9a5e2f4e82', 1, '(41º Exame de Ordem (XLI), questão 8) Pedro Estrela, brasileiro, natural de Recife/PE, foi preso em flagrante por participar de esquema criminoso envolvendo pirâmides financeiras e por se apresentar como advogado, mesmo sem qualquer formação jurídica. Tendo obtido liberdade provisória, fugiu para o Equador, onde obteve graduação no curso de Direito, em faculdade local. Muitos anos depois, após ter extinta a punibilidade pelas infrações penais praticadas, decide voltar ao Brasil com a pretensão de exercer a advocacia. Quando da mudança para o Brasil, trouxe sua esposa equatoriana, Soraya, que já exercia a profissão de advogada no Equador. Considerando o enunciado acima, e a respeito da inscrição na Ordem dos Advogados do Brasil, assinale a afirmativa correta.', '{"a":"Pedro Estrela, desde que atendidos os demais requisitos para a inscrição como advogado, poderá exercer a advocacia no Brasil, independentemente de revalidação do seu diploma, diante do fato de ser brasileiro nato.","b":"Soraya não poderá exercer a profissão de advogada no Brasil, ainda que cumpra os demais requisitos para inscrição na Ordem, porque títulos de graduação obtidos em instituições estrangeiras não são aceitos para comprovação da aptidão por estrangeiros.","c":"O título de graduação obtido por Pedro em instituição estrangeira poderá ser aceito no Brasil, desde que devidamente revalidado, o que não lhe garantirá a inscrição na OAB, diante da necessidade de aprovação no Exame de Ordem, além do preenchimento dos demais requisitos legais, em especial a comprovação de idoneidade moral para a função.","d":"Pedro e Soraya poderão exercer livremente a função de advogado no Brasil, desde que sejam aprovados no Exame de Ordem, porque a aprovação nesse certame convalida os diplomas obtidos no exterior."}', 'c', 'O art. 8º, § 2º, do Estatuto exige de quem se graduou em instituição estrangeira — brasileiro ou estrangeiro — a revalidação do diploma, além dos demais requisitos: aprovação no Exame de Ordem e idoneidade moral, entre outros. Ser brasileiro nato não dispensa a revalidação (A); estrangeiro pode se inscrever se cumprir os requisitos (B); o Exame de Ordem não convalida diploma (D).'),
('dd07befb-aa02-468f-a76f-5518c21b4e51', '37a41d9c-2a34-4b58-9930-fb9a5e2f4e82', 2, '(38º Exame de Ordem (XXXVIII), questão 7) O advogado Alex encontra-se licenciado junto à OAB. Assinale a opção que, corretamente, apresenta uma causa para o licenciamento de Alex.', '{"a":"O requerimento de licenciamento, independentemente de motivação, formulado por Alex.","b":"O fato de Alex passar a sofrer de doença física incurável.","c":"O exercício por Alex, de forma definitiva, de atividade incompatível com a advocacia.","d":"O fato de Alex passar a sofrer de doença mental curável."}', 'd', 'O art. 12 do Estatuto prevê licença quando o advogado: (I) requerer, por motivo justificado; (II) passar a exercer, temporariamente, atividade incompatível; (III) sofrer doença mental curável. A erra ao dispensar a motivação; B fala em doença física, que não está na lei; C descreve hipótese de cancelamento (incompatibilidade definitiva).');--> statement-breakpoint
