INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('a6c60830-244a-4466-9f93-3b9af8b74eda', '8638e6fe-16db-4f1c-8b20-19dc820ce269', 1, '(40º Exame de Ordem (XL), questão 5) Formalizou-se, no Tribunal Regional Eleitoral do Estado Alfa, a vacância de um dos cargos de juiz eleitoral, reservado constitucionalmente à classe de advogados. De igual modo, no Tribunal Regional Federal da Enésima Região, sediado na capital do mesmo Estado Alfa, com jurisdição nos Estados Alfa, Beta e Gama, foi também formalizada a vacância de um cargo de juiz federal do Tribunal Regional Federal, destinado à advocacia nos termos da Constituição Federal (quinto constitucional). Nesse hipotético cenário, que demandará a produção de duas listas de membros da advocacia para o futuro preenchimento dos cargos, assinale a afirmativa que descreve corretamente as competências dos órgãos da OAB.', '{"a":"A lista para o preenchimento do cargo no TRE do Estado Alfa ficará sob a incumbência do Conselho Seccional da OAB do respectivo Estado, competindo ao Conselho Federal da OAB elaborar a lista para o preenchimento do cargo no TRF da Enésima Região.","b":"A lista para o preenchimento do cargo no TRE do Estado Alfa ficará sob a incumbência do Conselho Seccional da OAB do respectivo Estado, competindo aos Conselhos Seccionais da OAB dos Estados Alfa, Beta e Gama a elaboração conjunta da lista para o preenchimento do cargo no TRF da Enésima Região.","c":"Uma vez que tanto a Justiça Eleitoral quanto a Justiça Federal pertencem ao Poder Judiciário da União, competirá ao Conselho Federal da OAB a elaboração das duas listas.","d":"Uma vez que tanto o TRE do Estado Alfa quanto a sede do TRF da Enésima Região estão situados no Estado Alfa, competirá ao Conselho Seccional da OAB desse Estado a elaboração das duas listas."}', 'a', 'Pelo art. 58, XIV, compete ao Conselho Seccional elaborar as listas para os tribunais no âmbito de sua competência — caso do TRE do próprio Estado. Já o art. 54, XIII, dá ao Conselho Federal as listas para tribunais de âmbito nacional ou interestadual — caso do TRF com jurisdição em três Estados.'),
('0aea26e8-52ff-4d71-ba1b-b0fc8d06a05d', '8638e6fe-16db-4f1c-8b20-19dc820ce269', 2, '(35º Exame de Ordem (XXXV), questão 6) O advogado Cauã Silva foi presidente de certo Conselho Seccional da OAB, tendo seu mandato se encerrado há mais de uma década. Desde então, embora tenha permanecido como aguerrido defensor das prerrogativas e dos direitos dos advogados, Cauã não mais concorreu a nenhum cargo na OAB. Considerando a situação hipotética narrada, assinale a afirmativa correta.', '{"a":"Cauã, quando cessado seu mandato, deixou de integrar o Conselho Seccional da OAB.","b":"Cauã permanece como membro honorário do Conselho Seccional da OAB, mas não tem direito de voto ou de voz nas sessões.","c":"Cauã é ainda membro honorário do Conselho Seccional da OAB e o será de forma vitalícia, tendo, contudo, apenas direito de voz nas sessões.","d":"Cauã permanece como membro honorário do Conselho Seccional da OAB, a quem são conferidos os direitos a voz e voto nas sessões do Conselho."}', 'c', 'O art. 56, § 1º, do Estatuto estabelece que os ex-presidentes do Conselho Seccional são membros honorários vitalícios, somente com direito a voz em suas sessões. Cauã continua integrando o Conselho nessa condição, sem voto.');--> statement-breakpoint
