INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('c292002b-adb7-4056-bc10-f4380aa7187a', '67539671-c4b3-43d6-b82f-7a7a6054952e', 1, 'Certo ou errado? "Competente é a Seccional da inscrição do advogado"', 'Errado. (para punir); vale o local da infração. Para a suspensão preventiva, porém, é o TED da inscrição principal.', 'medium'),
('8f195ffb-992a-4a9d-8617-c9e39f3dbff6', '67539671-c4b3-43d6-b82f-7a7a6054952e', 2, 'Certo ou errado? "Suspensão preventiva sem ouvir o advogado"', 'Errado.', 'medium'),
('d91ff5e0-262f-4643-87ac-503f62adbbc4', '67539671-c4b3-43d6-b82f-7a7a6054952e', 3, 'Certo ou errado? "Processo disciplinar é público"', 'Errado. É sigiloso até o fim.', 'medium'),
('fb46e479-26c1-4c2b-b36c-2f69def93ade', '67539671-c4b3-43d6-b82f-7a7a6054952e', 4, 'Certo ou errado? "Denúncia anônima instaura processo"', 'Errado.', 'medium'),
('1a426ed8-06ee-44aa-baa2-70d1e6b11695', '67539671-c4b3-43d6-b82f-7a7a6054952e', 5, 'Certo ou errado? "TAC para qualquer infração"', 'Errado. Só puníveis com censura e sem repercussão negativa.', 'medium'),
('e2063d0f-a0a4-4cdc-a96f-c56bb487bb9c', '67539671-c4b3-43d6-b82f-7a7a6054952e', 6, 'Quem tem competência para punir o advogado? E para a suspensão preventiva?', 'Pune a Seccional do local da infração. A suspensão preventiva é do TED da inscrição principal, com oitiva prévia, por até 90 dias.', 'medium'),
('ebadcbec-a2a3-44cc-81d0-5f37d1422184', '67539671-c4b3-43d6-b82f-7a7a6054952e', 7, 'Denúncia anônima instaura processo disciplinar? O processo é público?', 'Não instaura. O processo disciplinar é sigiloso.', 'medium');--> statement-breakpoint
