INSERT INTO `training_days` (`id`, `training_id`, `day_number`, `date`, `title`, `description`)
VALUES ('ad6b3d27-82d1-42ad-90b6-d099efb936e1', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 12, '2026-11-10', 'Capítulo 11 — Incompatibilidades e impedimentos', 'Incompatibilidade = proibição total de advogar; impedimento = proibição parcial (art. 27). Decorar a lista do art. 28 e as duas hipóteses do art. 30 resolve quase todas as questões.');--> statement-breakpoint
