VALUES ('e68ddaae-e0ee-45c9-9994-39c2bc69b0d7', 'ad6b3d27-82d1-42ad-90b6-d099efb936e1', 1, 'Leitura: Incompatibilidades e impedimentos', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('68db3ac0-2246-4059-8472-43832b3b98f3', 'e68ddaae-e0ee-45c9-9994-39c2bc69b0d7', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 11: Incompatibilidades e impedimentos', '<table><tbody><tr><td><p><strong>11º</strong></p><p>lugar em incidência</p></td><td><p><strong>20</strong></p><p>questões em 48 provas</p></td><td><p><strong>4,5%</strong></p><p>das questões de Ética</p></td><td><p><strong>6</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>em alta</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p><strong>Incompatibilidade = proibição total</strong> de advogar; <strong>impedimento = proibição parcial</strong> (art. 27). Decorar a lista do art. 28 e as duas hipóteses do art. 30 resolve quase todas as questões.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>EAOAB, arts. 27 a 30</li></ul></td></tr></tbody></table>
<h2>Incompatibilidade (art. 28) — proibição total, mesmo em causa própria</h2>
<ul><li><strong>I</strong> — <strong>chefes do Poder Executivo</strong> e <strong>membros da Mesa do Poder Legislativo</strong>, e seus substitutos legais.</li><li><strong>II</strong> — membros do <strong>Poder Judiciário</strong>, do <strong>Ministério Público</strong>, dos <strong>tribunais e conselhos de contas</strong>, dos juizados especiais, da justiça de paz, e todos que exerçam <strong>função de julgamento</strong> em órgãos de deliberação coletiva da Administração.</li><li><strong>III</strong> — ocupantes de <strong>cargos ou funções de direção</strong> na Administração direta ou indireta, fundações, empresas controladas ou concessionárias de serviço público.</li><li><strong>IV</strong> — servidores <strong>vinculados ao Poder Judiciário</strong> e quem exerce <strong>serviços notariais e de registro</strong>.</li><li><strong>V</strong> — cargos ou funções ligados à <strong>atividade policial</strong> de qualquer natureza.</li><li><strong>VI</strong> — <strong>militares</strong> na ativa.</li><li><strong>VII</strong> — quem tem competência de <strong>lançamento, arrecadação ou fiscalização de tributos</strong>.</li><li><strong>VIII</strong> — funções de <strong>direção e gerência em instituições financeiras</strong>, inclusive privadas.</li></ul>
<p>Regras complementares:</p>
<ul><li>A incompatibilidade <strong>permanece mesmo com afastamento temporário</strong> do cargo (§ 1º).</li><li><strong>Não</strong> se incluem no inciso III quem <strong>não tem poder de decisão relevante</strong> e a <strong>administração acadêmica</strong> ligada ao magistério jurídico (§ 2º).</li><li><strong>§§ 3º e 4º (Lei 14.365/2022):</strong> permitiam a policiais e militares advogar em causa própria, com inscrição especial. O STF declarou os dois parágrafos <strong>inconstitucionais</strong> (ADI 7.227, 2023). Hoje a incompatibilidade dos incisos V e VI vale <strong>inclusive em causa própria</strong>.</li></ul>
<h2>Legitimação exclusiva (art. 29)</h2>
<p><strong>Procuradores-Gerais, Advogados-Gerais, Defensores-Gerais e dirigentes de órgãos jurídicos</strong> da Administração direta, indireta e fundacional são <strong>exclusivamente legitimados</strong> para a advocacia <strong>vinculada à função</strong>, durante a investidura. Na prática, não podem advogar fora do cargo.</p>
<h2>Impedimento (art. 30) — proibição parcial</h2>
<ul><li><strong>I</strong> — <strong>servidores</strong> da Administração direta, indireta e fundacional: impedidos de advogar <strong>contra a Fazenda Pública que os remunera</strong> ou à qual se vincule a entidade empregadora.</li><li><strong>II</strong> — <strong>membros do Poder Legislativo</strong> (que não integram a Mesa): impedidos de advogar <strong>contra ou a favor</strong> de pessoas jurídicas de direito público, empresas públicas, sociedades de economia mista, fundações públicas, entidades paraestatais e concessionárias ou permissionárias de serviço público.</li><li><strong>Docentes de cursos jurídicos</strong> <strong>não</strong> sofrem o impedimento do inciso I (parágrafo único).</li></ul>
<table><tbody><tr><td><p><strong>ATENÇÃO: MUDOU!</strong></p><p>A Lei 14.365/2022 incluiu no art. 28 os §§ 3º e 4º, para que policiais e militares pudessem advogar em causa própria. O STF os declarou <strong>inconstitucionais</strong> (ADI 7.227, 2023). Continua valendo a regra: policial e militar da ativa <strong>não advogam nem em causa própria</strong>. O site do Planalto ainda exibe os parágrafos.</p></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>COMO A FGV COBRA</strong></p><ul><li>Lista de cargos para identificar qual é incompatível e qual é impedido.</li><li>Procurador-Geral que quer continuar com as causas particulares.</li><li>Vereador × vereador da Mesa; servidor professor de Direito.</li></ul></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Incompatível pode advogar em causa própria" → <strong>errado</strong>: a incompatibilidade vale mesmo em causa própria. A exceção criada em 2022 para policiais e militares foi derrubada pelo STF (ADI 7.227).</li><li>"Magistrado licenciado pode advogar" → <strong>errado</strong>: a incompatibilidade permanece.</li><li>"Vereador é incompatível" → <strong>errado</strong>: é <strong>impedido</strong>; só o <strong>membro da Mesa</strong> é incompatível.</li><li>"Procurador-Geral pode advogar contra particulares" → <strong>errado</strong>: art. 29.</li><li>"Professor de Direito servidor é impedido contra a Fazenda" → <strong>errado</strong>.</li><li>"Tabelião pode advogar em causa própria" → <strong>errado</strong>.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 11. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('5c94bf57-bfb5-408b-b2e7-2dcf1f47df01', 'Ética — Cap. 11: Incompatibilidades e impedimentos (questões comentadas do ebook)', '68db3ac0-2246-4059-8472-43832b3b98f3', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('77e6ba0c-20e2-4422-b4f7-5df7430d79c5', '5c94bf57-bfb5-408b-b2e7-2dcf1f47df01', 1, '(46º Exame de Ordem (XLVI), questão 2) Danilo, procurador de carreira, foi nomeado Procurador-Geral de sua instituição. Antes de assumir a Procuradoria-Geral do Estado, ele patrocinava várias causas trabalhistas contra empresas privadas e causas tributárias. Agora, Danilo está em dúvida se poderá continuar advogando nessas ações. Sobre a hipótese apresentada, com base nas disposições do Estatuto da OAB sobre incompatibilidades e impedimentos, assinale a afirmativa correta.', '{"a":"Danilo está impedido de atuar em causas trabalhistas e tributárias contra a Fazenda Pública que o remunera, mas pode continuar patrocinando as causas contra empresas privadas.","b":"Danilo poderá continuar patrocinando suas causas trabalhistas e tributárias, pois o cargo de Procurador-Geral do Estado não gera incompatibilidade ou impedimento para advogar em questões privadas.","c":"Danilo poderá continuar patrocinando as causas tributárias, mas não as trabalhistas, pois apenas as causas tributárias contra a Fazenda Pública estão abrangidas pelo impedimento previsto no Estatuto da OAB.","d":"Danilo não poderá continuar patrocinando suas causas trabalhistas e tributárias, pois o cargo de Procurador-Geral do Estado obsta o exercício da advocacia desvinculado da função que exerce, durante o período da investidura."}', 'd', 'O art. 29 do Estatuto torna os Procuradores-Gerais exclusivamente legitimados para a advocacia vinculada à função que exercem, durante o período da investidura. Danilo não pode continuar com as causas particulares, trabalhistas ou tributárias. A trata a situação como mero impedimento; B e C permitem atuação privada.'),
('67801483-20a3-4a02-8d33-05b96c9eb6be', '5c94bf57-bfb5-408b-b2e7-2dcf1f47df01', 2, '(45º Exame de Ordem (XLV), questão 3) Tarcísio, advogado trabalhista com mais de 20 anos de experiência, prestou concurso público para a Outorga de Delegações de Serventias Notariais e Registrais e, após aprovação, assumiu um Tabelionato de Notas e Ofício de Registro Civil em uma comarca do mesmo Estado. Ele deseja saber se poderá continuar exercendo a advocacia em causa própria e, além disso, pretende patrocinar uma ação contra a empresa pública estadual responsável pelo fornecimento de água. Sobre incompatibilidades e impedimentos, com base nas disposições do Estatuto da OAB, assinale a afirmativa correta.', '{"a":"Tarcísio poderá exercer a advocacia apenas em causa própria, conforme prevê o Estatuto da OAB, mas estará impedido de advogar contra a empresa pública estadual de fornecimento de água.","b":"Tarcísio poderá advogar livremente, inclusive contra a empresa pública estadual de fornecimento de água, uma vez que o exercício da atividade notarial não gera impedimento para o exercício da advocacia.","c":"Tarcísio está em situação de incompatibilidade total com o exercício da advocacia, sendo vedada a atuação em qualquer causa, inclusive em causa própria, em razão de seu cargo como titular de serventia notarial e registral.","d":"Tarcísio poderá continuar exercendo a advocacia, desde que em causas particulares que não envolvam empresas públicas ou concessionárias de serviço público, estando livre de impedimentos em ações de interesse pessoal."}', 'c', 'Quem exerce serviços notariais e de registro está em situação de incompatibilidade (art. 28, IV), que é proibição total do exercício da advocacia, mesmo em causa própria. As alternativas que liberam a causa própria (A) ou certas causas (B e D) estão erradas.');--> statement-breakpoint
