VALUES ('caa7af12-d440-42b9-a89d-cde81c416cf2', 'Ética — Cap. 11: Incompatibilidades e impedimentos', '68db3ac0-2246-4059-8472-43832b3b98f3', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 7);--> statement-breakpoint
INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('dcb7c572-74d0-4fd4-beaf-7cd80d98e924', 'caa7af12-d440-42b9-a89d-cde81c416cf2', 1, 'Certo ou errado? "Incompatível pode advogar em causa própria"', 'Errado. A incompatibilidade vale mesmo em causa própria. A exceção criada em 2022 para policiais e militares foi derrubada pelo STF (ADI 7.227).', 'medium'),
('6ad17337-b0b2-4159-a0ad-a57955557316', 'caa7af12-d440-42b9-a89d-cde81c416cf2', 2, 'Certo ou errado? "Magistrado licenciado pode advogar"', 'Errado. A incompatibilidade permanece.', 'medium'),
('3d25f452-e79e-460b-b985-659a2e5dcffb', 'caa7af12-d440-42b9-a89d-cde81c416cf2', 3, 'Certo ou errado? "Vereador é incompatível"', 'Errado. É impedido; só o membro da Mesa é incompatível.', 'medium'),
('2165ef51-810f-4dba-a422-fb72d3281ad8', 'caa7af12-d440-42b9-a89d-cde81c416cf2', 4, 'Certo ou errado? "Procurador-Geral pode advogar contra particulares"', 'Errado. Art. 29.', 'medium'),
('53c971ca-3f5d-4a18-8aa5-28ecb8290315', 'caa7af12-d440-42b9-a89d-cde81c416cf2', 5, 'Certo ou errado? "Professor de Direito servidor é impedido contra a Fazenda"', 'Errado.', 'medium'),
