INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('e1199924-a5b8-4c16-83e9-877bebd0f397', '202181e4-f197-4d04-b3f3-27d5294859ee', 1, '(46º Exame de Ordem (XLVI), questão 3) Alfredo é graduado em Direito pela Universidade Beta, mas não foi aprovado no Exame da Ordem dos Advogados do Brasil (OAB). Durante a graduação, Alfredo não teve a oportunidade de estagiar em um escritório de advocacia. Recentemente, após já estar formado, surgiu a oportunidade de estagiar em um escritório credenciado pelo Conselho Seccional da OAB. Ele deseja saber se pode participar do estágio profissional de advocacia mesmo após a conclusão de seu curso e se seria possível inscrever-se no quadro de estagiários da OAB. Sobre a hipótese, com base no disposto no Art. 9º do Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Alfredo não pode participar de estágio de advocacia, pois o estágio só é permitido para estudantes de Direito que ainda estejam cursando os últimos anos do curso jurídico.","b":"Alfredo pode se inscrever no quadro de estagiários da OAB, mas somente se concluir o estágio profissional em uma instituição de ensino superior, e não em escritório credenciado pelo Conselho Seccional da OAB.","c":"Alfredo pode participar do estágio profissional de advocacia e inscrever-se como estagiário da OAB, mesmo após a conclusão do curso, desde que o estágio seja realizado em escritório credenciado pela OAB.","d":"Alfredo pode participar do estágio profissional, mas não poderá inscrever-se no quadro de estagiários da OAB, pois já concluiu a graduação em Direito e apenas alunos ainda cursando o ensino jurídico podem obter essa inscrição."}', 'c', 'O art. 9º, § 4º, do Estatuto permite que o estágio profissional seja cumprido por bacharel em Direito que queira se inscrever na Ordem, e o § 1º admite estágio em escritórios credenciados pela OAB. Alfredo pode estagiar e se inscrever como estagiário.'),
('42375320-1628-4945-8c54-82eb01a5d73e', '202181e4-f197-4d04-b3f3-27d5294859ee', 2, '(35º Exame de Ordem (XXXV), questão 5) João é estagiário de Direito. É vedado a João praticar isoladamente – isto é, sem atuar em conjunto com o advogado ou o defensor público que o supervisiona – o seguinte ato:', '{"a":"assinar petições de juntada de documentos a processos judiciais.","b":"obter junto aos escrivães e chefes de secretarias certidões de peças de processos em curso.","c":"comparecer à prática de atos extrajudiciais, sem autorização ou substabelecimento do advogado.","d":"retirar e devolver autos em cartório, assinando a respectiva carga."}', 'c', 'O RG (art. 29, § 1º) permite ao estagiário, isoladamente: retirar e devolver autos assinando a carga (D), obter certidões (B) e assinar petições de juntada de documentos (A). Já o comparecimento a atos extrajudiciais só pode ocorrer isoladamente com autorização ou substabelecimento do advogado (§ 2º).');--> statement-breakpoint
