VALUES ('0d8c03d9-dab6-49aa-96d7-426e177fd770', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 14, '2026-11-12', 'Capítulo 13 — Sigilo profissional', 'Tema curto e muito lógico. O sigilo é de ordem pública: não depende do cliente, e o advogado pode recusar-se a depor mesmo com autorização dele.');--> statement-breakpoint
