VALUES ('372c8187-2a5c-4005-940a-62bc953e90b0', '0d8c03d9-dab6-49aa-96d7-426e177fd770', 1, 'Leitura: Sigilo profissional', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('d9c51695-a210-446a-bd36-e90ba30c5423', '372c8187-2a5c-4005-940a-62bc953e90b0', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 13: Sigilo profissional', '<table><tbody><tr><td><p><strong>13º</strong></p><p>lugar em incidência</p></td><td><p><strong>14</strong></p><p>questões em 48 provas</p></td><td><p><strong>3,1%</strong></p><p>das questões de Ética</p></td><td><p><strong>2</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>em queda</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Tema curto e muito lógico. O sigilo é <strong>de ordem pública</strong>: não depende do cliente, e o advogado <strong>pode recusar-se a depor mesmo com autorização</strong> dele.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>CED, arts. 35 a 38</li><li>EAOAB, arts. 7º, XIX, e 34, VII</li></ul></td></tr></tbody></table>
<h2>Regras</h2>
<ul><li>O advogado deve guardar sigilo dos fatos que conheça <strong>no exercício da profissão</strong>, inclusive os que soube em razão de <strong>funções desempenhadas na OAB</strong> (CED, art. 35).</li><li>O sigilo é <strong>de ordem pública</strong> e <strong>independe de pedido de reserva</strong> do cliente (art. 36).</li><li>Presumem-se <strong>confidenciais</strong> as comunicações de qualquer natureza entre advogado e cliente.</li><li>O advogado que atua como <strong>mediador, conciliador ou árbitro</strong> também se submete ao sigilo.</li><li><strong>Exceções — justa causa</strong> (art. 37): circunstâncias excepcionais, <strong>como</strong> <strong>grave ameaça ao direito à vida e à honra</strong> ou <strong>defesa própria</strong> (rol exemplificativo).</li><li>O advogado <strong>não é obrigado a depor</strong>, em processo judicial, administrativo ou arbitral, sobre fatos cobertos pelo sigilo (art. 38).</li><li>É direito do advogado <strong>recusar-se a depor como testemunha</strong> em processo no qual funcionou ou deva funcionar, ou sobre fato relacionado a <strong>pessoa de quem seja ou foi advogado</strong>, <strong>mesmo quando autorizado ou solicitado pelo constituinte</strong> (EAOAB, art. 7º, XIX).</li><li>Violar o sigilo sem justa causa é infração (art. 34, VII), punida com censura.</li><li>Ao advogar <strong>contra ex-cliente ou ex-empregador</strong>, o advogado deve resguardar o sigilo (CED, art. 21).</li><li><strong>Fato que não tem relação com a atuação profissional</strong> (ex.: presenciou um acidente na rua) não é coberto pelo sigilo: o advogado deve depor como qualquer testemunha.</li></ul>
<table><tbody><tr><td><p><strong>COMO A FGV COBRA</strong></p><ul><li>Ex-advogado intimado como testemunha contra o ex-cliente, com ou sem autorização.</li><li>Sigilo de fatos conhecidos em função na OAB.</li><li>Hipóteses de quebra: vida, honra, defesa própria.</li></ul></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Com autorização do cliente, é obrigado a depor" → <strong>errado</strong>.</li><li>"Encerrado o contrato, acaba o sigilo" → <strong>errado</strong>.</li><li>"Em crimes graves, o juiz pode obrigá-lo a depor sobre fatos sigilosos" → <strong>errado</strong>.</li><li>"Fatos conhecidos como conselheiro da OAB não são sigilosos" → <strong>errado</strong>.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 13. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
