VALUES ('6a6d1e58-ffb2-4b02-87bb-8fb57030d9f0', 'Ética — Cap. 13: Sigilo profissional (questões comentadas do ebook)', 'd9c51695-a210-446a-bd36-e90ba30c5423', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('6e5fcdcf-f563-4ad2-b154-4d512add92cc', '6a6d1e58-ffb2-4b02-87bb-8fb57030d9f0', 1, '(45º Exame de Ordem (XLV), questão 6) Durante muitos anos, João representou Pedro, na condição de seu advogado, em diversas causas. Recentemente, após encerrados todos os vínculos contratuais existentes entre si, Pedro passou a ser investigado pelo suposto cometimento de ilícitos tributários. Sobre esse contexto, de acordo com o Estatuto da Ordem e com o Código de Ética e Disciplina da Ordem dos Advogados do Brasil, assinale a afirmativa correta.', '{"a":"João não poderá ser obrigado a depor como testemunha no curso de eventual processo judicial em face de Pedro, ainda que este expressamente o autorize ou solicite o depoimento do ex-advogado.","b":"João não poderá ser obrigado a depor como testemunha no curso de eventual processo judicial em face de Pedro, exceto se este expressamente o autorizar, ou no caso de solicitação do próprio ex-constituinte.","c":"João poderá ser obrigado a depor sobre fatos que constituam sigilo profissional caso seu depoimento seja considerado imprescindível para a instrução em processos criminais que apurem a prática de crimes dolosos contra a vida.","d":"Considerando que a investigação se iniciou após a extinção da relação profissional existente entre João e Pedro, não há qualquer prerrogativa em favor de João que o escuse da obrigação de depor como testemunha no curso de processo judicial sobre fato relacionado com pessoa de quem já foi advogado."}', 'a', 'O art. 7º, XIX, do Estatuto assegura ao advogado o direito de recusar-se a depor como testemunha sobre fato relacionado com pessoa de quem seja ou foi advogado, mesmo quando autorizado ou solicitado pelo constituinte; o art. 38 do CED reforça. O fim do vínculo não elimina a prerrogativa (D), e não há exceção para crimes dolosos contra a vida (C).'),
('bf952d62-70de-4f9b-8ad6-0066b81966da', '6a6d1e58-ffb2-4b02-87bb-8fb57030d9f0', 2, '(42º Exame de Ordem (XLII), questão 4) A advogada Nina exerce função na diretoria do Conselho Federal da OAB. Em virtude exclusivamente das funções desempenhadas na OAB, Nina toma conhecimento de certos fatos envolvendo seus colegas advogados João e Maria. Nina acaba de receber uma intimação para depor como testemunha em audiência de instrução e julgamento, referente a uma ação indenizatória, de cunho meramente patrimonial, sem envolver grave ameaça ao direito à vida e à honra, ajuizada por Maria em face de João, cujo objeto tem relação com mencionados fatos de que tomou conhecimento no exercício da citada função no Conselho Federal da OAB Considerando a situação hipotética, assinale a afirmativa correta.', '{"a":"Nina não deve depor sobre os fatos que soube, diante do sigilo profissional.","b":"Nina não poderá alegar sigilo profissional em razão da natureza das funções exercidas no Conselho Federal da OAB.","c":"Nina deverá relatar os fatos sobre os quais tomou conhecimento, pois se trata de ação indenizatória, de cunho meramente patrimonial.","d":"Nina tem o dever legal de permanecer em silêncio sobre os fatos indagados, salvo em circunstâncias excepcionais, tais como a defesa judicial de familiares e amigos íntimos."}', 'a', 'O sigilo profissional abrange os fatos que o advogado conheceu em razão de funções desempenhadas na OAB (CED, art. 35, parágrafo único), e ele não é obrigado a depor sobre fatos sigilosos (art. 38). A causa é meramente patrimonial e não envolve grave ameaça à vida ou à honra, então não há justa causa para quebrar o sigilo.');--> statement-breakpoint
