('3a31d657-0c47-485c-8725-5df268f436fc', '9d02f9c5-856a-42a0-a685-124b7595a025', 1, 'Certo ou errado? "Com autorização do cliente, é obrigado a depor"', 'Errado.', 'medium'),
('3cd0149a-7c70-4068-9ee9-28999d1cfdbf', '9d02f9c5-856a-42a0-a685-124b7595a025', 2, 'Certo ou errado? "Encerrado o contrato, acaba o sigilo"', 'Errado.', 'medium'),
('8c49935b-c38f-48cc-bf15-e06019bcdde5', '9d02f9c5-856a-42a0-a685-124b7595a025', 3, 'Certo ou errado? "Em crimes graves, o juiz pode obrigá-lo a depor sobre fatos sigilosos"', 'Errado.', 'medium'),
('b9dda244-0a5f-408e-ae9d-f0415e9051d6', '9d02f9c5-856a-42a0-a685-124b7595a025', 4, 'Certo ou errado? "Fatos conhecidos como conselheiro da OAB não são sigilosos"', 'Errado.', 'medium'),
('26214eef-5617-4dfb-a9f1-67a1a642e0e6', '9d02f9c5-856a-42a0-a685-124b7595a025', 5, 'O advogado pode recusar-se a depor sobre fato sigiloso mesmo autorizado pelo cliente?', 'Sim. O sigilo é de ordem pública: pode recusar-se a depor mesmo autorizado ou solicitado pelo cliente.', 'medium');--> statement-breakpoint
