VALUES ('a9417851-9861-4a88-9bd1-0974e9a696ad', 'Ética — Cap. 14: Deveres éticos e princípios fundamentais (questões comentadas do ebook)', 'eb12ff9d-993f-4eb4-8ba1-ccfd7b3abaef', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('22070081-774f-4247-ac3a-9069b358df65', 'a9417851-9861-4a88-9bd1-0974e9a696ad', 1, '(41º Exame de Ordem (XLI), questão 3) O empresário João Pedro, movido pelo sentimento de vingança, contrata o advogado Beraldo para propor ação de cobrança contra seu ex-sócio Marcos, apresentando frágeis documentos que comprovariam uma suposta dívida. A ação foi proposta e, concedida medida cautelar pelo juiz da causa, gerou diversos danos a Marcos, a partir da indisponibilidade de seus bens e do bloqueio de todos os seus ativos bancários initio litis. Ao final, porém, o pedido foi julgado totalmente improcedente, sendo expressamente reconhecida a lide temerária. Acerca da responsabilidade do advogado nessa hipotética situação, assinale a afirmativa correta.', '{"a":"Beraldo poderá ser responsabilizado subsidiariamente pelos prejuízos causados, caso demonstrada culpa ou dolo no exercício da profissão, o que deverá ser apurado nos próprios autos.","b":"Beraldo e João Pedro poderão ser responsabilizados solidariamente pelos prejuízos causados, desde que demonstrada a coligação entre ambos para lesar Marcos, o que deverá ser apurado em ação própria.","c":"Beraldo não poderá ser responsabilizado pelos prejuízos causados, pois o Estatuto da Advocacia e da OAB não prevê consequência jurídica para a hipótese de lide temerária.","d":"Beraldo poderá ser responsabilizado solidariamente pelos prejuízos causados, desde que seja demonstrada a coligação com João Pedro para lesar Marcos, o que deverá ser apurado nos próprios autos."}', 'b', 'O art. 32, parágrafo único, do Estatuto estabelece que, em caso de lide temerária, o advogado é solidariamente responsável com o cliente desde que coligado com ele para lesar a parte contrária, o que é apurado em ação própria. A fala em responsabilidade subsidiária; C nega a consequência prevista em lei; D manda apurar nos próprios autos.'),
('f0d10e53-70de-4e8d-b801-b4a6cb5b4280', 'a9417851-9861-4a88-9bd1-0974e9a696ad', 2, '(QUESTÃO INÉDITA NO ESTILO FGV) Carla é advogada empregada do departamento jurídico da sociedade empresária Beta. Anos atrás, a pedido da própria empresa, emitiu parecer concluindo pela ilegalidade de determinada cláusula contratual. Agora, a empresa pede que Carla ajuíze ação defendendo exatamente a validade dessa cláusula. Carla consulta você sobre a possibilidade de recusar o patrocínio. Assinale a afirmativa correta.', '{"a":"Carla não pode recusar o patrocínio, pois o advogado empregado deve seguir as orientações do empregador em todas as causas da empresa.","b":"Carla pode recusar o patrocínio, pois é legítima a recusa de causa que contrarie orientação que ela tenha manifestado anteriormente.","c":"Carla só pode recusar o patrocínio se renunciar ao emprego, já que a relação empregatícia retira a independência do advogado.","d":"Carla pode recusar o patrocínio apenas se a ação envolver direito que também lhe seja aplicável."}', 'b', 'O CED, art. 4º, parágrafo único, torna legítima a recusa de causa ou manifestação que contrarie orientação que o advogado tenha manifestado anteriormente — e também, em outra hipótese, a de direito que lhe seja aplicável. A relação de emprego não retira a independência (EAOAB, art. 18). D erra ao limitar a recusa a uma só das hipóteses.');--> statement-breakpoint
