INSERT INTO `training_topics` (`id`, `training_day_id`, `order`, `title`, `type`, `subject_id`, `content`, `estimated_minutes`)
VALUES ('525ba480-4d8d-43fe-afca-157e4bc7b7b9', 'efce0438-6d7c-4cb2-83b8-6d85402edb40', 1, 'Leitura: Eleições e mandatos na OAB', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('a9c89332-0a96-481b-a50f-84ba5fe7a8ca', '525ba480-4d8d-43fe-afca-157e4bc7b7b9', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 15: Eleições e mandatos na OAB', '<table><tbody><tr><td><p><strong>15º</strong></p><p>lugar em incidência</p></td><td><p><strong>10</strong></p><p>questões em 48 provas</p></td><td><p><strong>2,2%</strong></p><p>das questões de Ética</p></td><td><p><strong>2</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>estável</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Tema de números. Quem memoriza os prazos de exercício profissional e as hipóteses de extinção do mandato acerta.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>EAOAB, arts. 63 a 67</li><li>Regulamento Geral, arts. 128 a 137 (em especial o art. 131)</li></ul></td></tr></tbody></table>
<h2>Eleição (arts. 63 e 64)</h2>
<ul><li>Realizada na <strong>segunda quinzena de novembro</strong> do último ano do mandato, por <strong>cédula única e votação direta</strong>.</li><li><strong>Comparecimento obrigatório</strong> para todos os advogados inscritos.</li><li>Vence a <strong>chapa</strong> com a maioria dos votos válidos. A chapa do Conselho Seccional inclui o conselho, a diretoria, a <strong>delegação ao Conselho Federal</strong> e a diretoria da <strong>Caixa de Assistência</strong>.</li><li>Desde 2021, as chapas devem observar <strong>paridade de gênero (50%)</strong> e <strong>cota racial (30%)</strong>, conforme regras do Conselho Federal.</li></ul>
<h2>Condições de elegibilidade (art. 63, § 2º)</h2>
<ul><li>Situação <strong>regular</strong> perante a OAB.</li><li><strong>Não ocupar cargo exonerável ad nutum</strong>.</li><li><strong>Não ter sido condenado</strong> por infração disciplinar, <strong>salvo reabilitação</strong>.</li><li>Exercício efetivo da profissão há <strong>mais de 3 anos</strong> para <strong>Conselheiro Seccional e das Subseções</strong>, e há <strong>mais de 5 anos</strong> para os <strong>demais cargos</strong> (Lei 13.875/2019).</li></ul>
<h2>Mandato (arts. 65 e 66)</h2>
<ul><li>Duração de <strong>3 anos</strong>, a partir de <strong>1º de janeiro</strong> do ano seguinte à eleição; no Conselho Federal, a partir de <strong>1º de fevereiro</strong>.</li><li><strong>Extinção automática</strong> antes do fim quando: houver <strong>cancelamento ou licença</strong> da inscrição; o titular sofrer <strong>condenação disciplinar</strong> (qualquer sanção); faltar <strong>sem justificativa a 3 reuniões ordinárias consecutivas</strong>, sem poder ser reconduzido no mesmo mandato.</li><li>Extinto o mandato sem suplente, o <strong>Conselho Seccional escolhe o substituto</strong>.</li></ul>
<h2>Diretoria do Conselho Federal (art. 67)</h2>
<p>Eleita pelos conselheiros federais em <strong>31 de janeiro</strong> do ano seguinte à eleição, por voto secreto, para mandato de 3 anos; toma posse no dia seguinte.</p>
<table><tbody><tr><td><p><strong>COMO A FGV COBRA</strong></p><ul><li>Candidato com poucos anos de inscrição ou com condenação disciplinar.</li><li>Conselheiro que assume cargo incompatível ou sofre condenação: o mandato se extingue?</li></ul></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"5 anos para Conselheiro Seccional" → <strong>errado</strong> desde 2019: <strong>3 anos</strong>.</li><li>"Condenado nunca mais pode se candidatar" → <strong>errado</strong>: com reabilitação, pode.</li><li>"Só a suspensão extingue o mandato" → <strong>errado</strong>: qualquer condenação disciplinar.</li><li>"Voto facultativo" → <strong>errado</strong>.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 15. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
