VALUES ('510504de-f6d5-48d5-921b-47057331c447', 'Ética — Cap. 15: Eleições e mandatos na OAB (questões comentadas do ebook)', 'a9c89332-0a96-481b-a50f-84ba5fe7a8ca', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('e6e05272-fd46-46fc-96dd-8ae2e1dcd6e9', '510504de-f6d5-48d5-921b-47057331c447', 1, '(42º Exame de Ordem (XLII), questão 6) José Fabiano, advogado recém-inscrito na OAB, com dois anos e seis meses de exercício da profissão, decidiu se candidatar para o cargo de Conselheiro Seccional da Ordem. Durante o procedimento de verificação da regularidade de sua candidatura, observou-se que ele havia sido condenado pela prática da infração disciplinar de abandonar a causa sem justo motivo ou antes de decorridos dez dias da comunicação da renúncia, tendo-lhe sido imposta sanção de censura, sem que tenha ocorrido, até o momento da eleição, sua reabilitação. Com base nessa situação hipotética e considerando as eleições da OAB, assinale a afirmativa correta.', '{"a":"José Fabiano somente poderá participar da eleição caso não haja outros candidatos dispostos a concorrer para o cargo, hipótese na qual as condições de elegibilidade são flexibilizadas para que a posição não fique vaga.","b":"José Fabiano não poderá participar da eleição corrente, porque ainda não completou o prazo de três anos de efetivo exercício profissional da advocacia e por ter sido apenado com sanção disciplinar, sem que tenha sucedido reabilitação.","c":"José Fabiano poderá participar da eleição e concorrer ao cargo de Conselheiro Seccional da OAB, porque exerce a profissão de advogado há mais de um ano e foi condenado por infração disciplinar leve, para a qual está prevista apenas a pena de censura.","d":"José Fabiano não poderá participar da eleição corrente e de futuras, porque, uma vez apenado com sanção disciplinar, o advogado não mais poderá recuperar sua condição de elegibilidade, estando impedido, indefinidamente, de se candidatar a cargos na OAB."}', 'b', 'O art. 63, § 2º, exige para Conselheiro Seccional exercício efetivo da profissão há mais de 3 anos e ausência de condenação disciplinar, salvo reabilitação. José tem 2 anos e 6 meses de exercício e uma censura sem reabilitação: está inelegível. Não há flexibilização por falta de candidatos (A); a censura também conta (C); e a reabilitação devolve a elegibilidade (D).'),
('415b3670-a76b-49a7-9d92-e0db269a3feb', '510504de-f6d5-48d5-921b-47057331c447', 2, '(QUESTÃO INÉDITA NO ESTILO FGV) Mariana, conselheira seccional eleita, foi nomeada para cargo de direção em autarquia estadual, com poder de decisão relevante sobre interesses de terceiros. Sobre o mandato de Mariana no Conselho Seccional, assinale a afirmativa correta.', '{"a":"O mandato fica suspenso enquanto Mariana exercer o cargo, retomando-se quando ela deixar a autarquia.","b":"O mandato se extingue automaticamente, pois o exercício de atividade incompatível gera o licenciamento ou o cancelamento da inscrição.","c":"O mandato só se extingue se Mariana faltar a três reuniões ordinárias consecutivas sem justificativa.","d":"O mandato continua válido, pois a incompatibilidade atinge apenas o exercício da advocacia, e não os cargos na OAB."}', 'b', 'Cargo de direção na Administração indireta com poder de decisão relevante é incompatível com a advocacia (EAOAB, art. 28, III), o que leva ao licenciamento (se temporário) ou ao cancelamento (se definitivo) da inscrição. O art. 66, I, prevê a extinção automática do mandato em qualquer hipótese de cancelamento ou licenciamento.');--> statement-breakpoint
