INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('ba521e13-84e6-4f5c-83f4-746f0183c3f4', 'b1b058e4-091d-463a-842a-85390717bea2', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 16: Advogado empregado', '<table><tbody><tr><td><p><strong>16º</strong></p><p>lugar em incidência</p></td><td><p><strong>8</strong></p><p>questões em 48 provas</p></td><td><p><strong>1,8%</strong></p><p>das questões de Ética</p></td><td><p><strong>3</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>em alta</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Pouca incidência, mas com uma <strong>mudança recente</strong> que a FGV já cobrou: a jornada passou de 4 para 8 horas diárias.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>EAOAB, arts. 18 a 21</li><li>Regulamento Geral, arts. 11 a 14</li></ul></td></tr></tbody></table>
<h2>Regras</h2>
<ul><li>A relação de emprego <strong>não retira a isenção técnica nem reduz a independência</strong> profissional (art. 18).</li><li>O empregado <strong>não é obrigado</strong> a prestar serviços de <strong>interesse pessoal dos empregadores</strong>, fora da relação de emprego (§ 1º).</li><li>Regimes de trabalho, a critério do empregador: <strong>presencial</strong>, <strong>não presencial (teletrabalho)</strong> ou <strong>misto</strong>; podem ser alterados por acordo individual (§§ 2º e 3º).</li><li><strong>Salário mínimo profissional</strong>: fixado em <strong>sentença normativa</strong>, salvo acordo ou convenção coletiva (art. 19).</li><li><strong>Jornada</strong> (art. 20, redação de 2022): quando presta serviço para empresas, <strong>até 8 horas contínuas por dia e 40 horas por semana</strong>.</li><li>Horas extras: adicional <strong>não inferior a 100%</strong>, <strong>mesmo havendo contrato escrito</strong> (§ 2º).</li><li>Trabalho noturno (<strong>das 20h às 5h</strong>): adicional de <strong>25%</strong> (§ 3º).</li><li><strong>Honorários de sucumbência</strong> nas causas do empregador <strong>pertencem ao advogado empregado</strong> (art. 21). Se o empregador for <strong>sociedade de advogados</strong>, são <strong>partilhados conforme acordo</strong> (parágrafo único). Não integram o salário nem servem de base para encargos trabalhistas ou previdenciários (RG, art. 14). Pelo STF (ADI 1.194), a regra admite estipulação em contrário entre as partes; na prova, sem ajuste, prevalece a letra do art. 21.</li></ul>
<table><tbody><tr><td><p><strong>ATENÇÃO: MUDOU!</strong></p><p>Antes da Lei 14.365/2022, a jornada era de <strong>4 horas diárias e 20 semanais</strong>. Questões antigas com esse gabarito estão superadas.</p></td></tr></tbody></table>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Hora extra com adicional de 50%, se o contrato prever" → <strong>errado</strong>: mínimo de 100%, mesmo com contrato.</li><li>"Jornada de 10 horas em 4 dias, somando 40 semanais" → <strong>errado</strong>: o limite diário de 8 horas também vale.</li><li>"Sucumbência pertence ao empregador" → <strong>errado</strong>.</li><li>"Noturno das 22h às 5h, com 20%" → <strong>errado</strong>: 20h às 5h, 25%.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 16. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('66db1bd2-7c4f-4180-aca4-8566920be4fe', 'Ética — Cap. 16: Advogado empregado (questões comentadas do ebook)', 'ba521e13-84e6-4f5c-83f4-746f0183c3f4', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('00816964-1729-4999-a492-2731f70ea1c3', '66db1bd2-7c4f-4180-aca4-8566920be4fe', 1, '(45º Exame de Ordem (XLV), questão 4) A advogada Jéssica foi contratada pela sociedade empresária de telefonia Alfa para trabalhar 10 horas contínuas por dia, de segunda a quinta-feira, totalizando 40 horas semanais. Além disso, o contrato escrito firmado entre Jéssica e a sociedade empresária prevê que, em situações excepcionais, ela deverá trabalhar horas extras, sendo remunerada com um adicional de 50% sobre o valor da hora normal. Jéssica questiona a validade dessas condições contratuais, especialmente em relação à duração da jornada de trabalho e à remuneração das horas extras. Com base no Art. 20 do Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"O contrato de Jéssica é válido, pois a jornada semanal não ultrapassa 40 horas, e as horas extras podem ser remuneradas com um adicional de 50% conforme estipulado no contrato.","b":"A sociedade empresária está correta ao fixar 10 horas de trabalho por dia, desde que Jéssica cumpra apenas quatro dias de trabalho por semana, sem a necessidade de pagamento de horas extras.","c":"O contrato de Jéssica é inválido, pois a jornada diária não pode exceder 8 horas contínuas, e as horas extras devem ser remuneradas com um adicional de 100%, conforme previsto no Estatuto da OAB, independentemente do contrato firmado.","d":"A sociedade empresária está agindo corretamente, pois Jéssica pode trabalhar até 10 horas por dia desde que sua jornada semanal não ultrapasse 40 horas, mas a remuneração das horas extras deveria ser de 100% sobre o valor da hora normal, independentemente do contrato escrito."}', 'c', 'O art. 20 do Estatuto limita a jornada do advogado empregado que presta serviço para empresas a 8 horas contínuas diárias e 40 semanais, e o § 2º fixa adicional não inferior a 100% para as horas extras, mesmo havendo contrato escrito. O contrato de Jéssica viola as duas regras.'),
('f6b4e771-5041-48e9-a381-ac71515cde90', '66db1bd2-7c4f-4180-aca4-8566920be4fe', 2, '(41º Exame de Ordem (XLI), questão 5) Gilson, advogado recém inscrito nos quadros da Ordem dos Advogados do Brasil, estava em dúvida entre constituir sociedade unipessoal de advocacia, o que, em seu entender, lhe traria maior autonomia e liberdade, ou aceitar a proposta recebida da sociedade empresária XYZ, para atuar como advogado empregado em regime de dedicação exclusiva. Após estudar a legislação correlata, Gilson aceitou a proposta de emprego da sociedade empresária XYZ. Acerca desse vínculo contratual, de acordo com o texto legal do Estatuto da Advocacia, assinale a afirmativa correta.', '{"a":"Nas causas em que Gilson atuar como advogado empregado da empresa XYZ, ou de pessoa por esta representada, os honorários de sucumbência lhe pertencerão.","b":"Gilson estará eticamente obrigado a prestar serviços profissionais de interesse pessoal dos diretores da sociedade empresária XYZ.","c":"A jornada de trabalho de Gilson não poderá exceder a duração diária de 4 (quatro) horas contínuas e a de 20 (vinte) horas semanais.","d":"Em virtude da dedicação exclusiva, Gilson não poderá ser remunerado pelas horas trabalhadas excedentes à jornada normal prevista na legislação."}', 'a', 'Pelo art. 21 do Estatuto, nas causas em que for parte o empregador, ou pessoa por ele representada, os honorários de sucumbência são devidos aos advogados empregados. B contraria o art. 18, § 1º; C traz a jornada antiga (4h/20h); D nega o pagamento de horas extras, que é devido.');--> statement-breakpoint
