VALUES ('3ca87b9b-f314-4ff0-b91d-df3f40722402', '6349df30-12f2-46cc-8c34-2e36d7a3ee41', 2, 'Questões comentadas do ebook', 'exercise', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '{"exerciseSetId":"66db1bd2-7c4f-4180-aca4-8566920be4fe"}', 20);--> statement-breakpoint
