VALUES ('293e4e2e-949b-4e61-b7eb-b17b3a1e9233', '18905b72-79c7-4fa7-8b54-92f5929f4e3d', 1, 'Leitura: Recursos e prazos nos processos da OAB', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('cfb233ea-3791-4226-abc4-61c2d50a4d27', '293e4e2e-949b-4e61-b7eb-b17b3a1e9233', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 17: Recursos e prazos nos processos da OAB', '<table><tbody><tr><td><p><strong>17º</strong></p><p>lugar em incidência</p></td><td><p><strong>8</strong></p><p>questões em 48 provas</p></td><td><p><strong>1,8%</strong></p><p>das questões de Ética</p></td><td><p><strong>2</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>estável</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Três perguntas resolvem o tema: <strong>quem julga o recurso</strong>, <strong>tem efeito suspensivo?</strong> e <strong>como se contam os prazos</strong>.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>EAOAB, arts. 69, 75, 76 e 77</li><li>Regulamento Geral, arts. 137-D a 144-B</li></ul></td></tr></tbody></table>
<h2>Prazos (art. 69)</h2>
<ul><li><strong>15 dias</strong> para qualquer manifestação e para recursos.</li><li>Notificação pessoal ou por ofício reservado: o prazo começa no <strong>primeiro dia útil após a juntada do aviso de recebimento</strong> (§ 1º, 2022).</li><li>Publicação no <strong>Diário Eletrônico da OAB</strong>: o prazo começa no primeiro dia útil seguinte à publicação, que se considera feita no primeiro dia útil após a disponibilização (§ 2º).</li><li>Notificações por <strong>AR</strong> enviadas ao <strong>endereço residencial ou profissional cadastrado</strong> presumem-se recebidas (RG, art. 137-D).</li></ul>
<h2>Para onde vai o recurso</h2>
<ul><li><strong>Ao Conselho Seccional</strong> (art. 76): contra decisões do <strong>seu Presidente</strong>, do <strong>TED</strong>, da <strong>diretoria da Subseção</strong> ou da <strong>Caixa de Assistência</strong>.</li><li><strong>Ao Conselho Federal</strong> (art. 75): contra decisões <strong>definitivas</strong> do Conselho Seccional <strong>não unânimes</strong>; ou, se unânimes, quando <strong>contrariarem o Estatuto, decisão do Conselho Federal ou de outro Conselho Seccional</strong>, o Regulamento Geral, o CED ou os Provimentos. O <strong>Presidente do Conselho Seccional</strong> também pode recorrer.</li></ul>
<h2>Efeito suspensivo (art. 77)</h2>
<p><strong>Todos os recursos têm efeito suspensivo, exceto</strong> os que tratarem de:</p>
<ul><li><strong>eleições</strong>;</li><li><strong>suspensão preventiva</strong> decidida pelo TED;</li><li><strong>cancelamento de inscrição obtida com falsa prova</strong>.</li></ul>
<h2>Não surpresa (RG, art. 144-B)</h2>
<p>Nenhuma decisão, em qualquer grau, pode se basear em fundamento sobre o qual as partes não tiveram oportunidade de se manifestar, <strong>salvo medidas de urgência</strong>.</p>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Recurso contra decisão da Subseção vai ao Conselho Federal" → <strong>errado</strong>: vai ao Conselho Seccional.</li><li>"Decisão unânime da Seccional nunca é recorrível" → <strong>errado</strong>: cabe recurso se a decisão unânime contrariar o Estatuto, decisão do Conselho Federal ou de outro Conselho Seccional, o Regulamento Geral, o CED ou os Provimentos (art. 75).</li><li>"Recurso contra suspensão preventiva tem efeito suspensivo" → <strong>errado</strong>.</li><li>"Prazo de 10 dias" → <strong>errado</strong>: 15.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 17. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
