VALUES ('b723cff5-96fe-40a6-8afc-b3aaba3d9b0a', 'Ética — Cap. 17: Recursos e prazos nos processos da OAB (questões comentadas do ebook)', 'cfb233ea-3791-4226-abc4-61c2d50a4d27', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('0c198ac4-0623-4b6d-b964-738d6237c53a', 'b723cff5-96fe-40a6-8afc-b3aaba3d9b0a', 1, '(36º Exame de Ordem (XXXVI), questão 6) A diretoria de certa subseção da OAB emitiu decisão no âmbito de suas atribuições. Irresignados, os interessados desejavam manejar recurso em face de tal decisão. Sobre a hipótese, assinale a afirmativa correta.', '{"a":"A competência privativa para julgar, em grau de recurso, questão decidida pela diretoria da subseção é do Conselho Federal da OAB.","b":"A competência privativa para julgar, em grau de recurso, questão decidida pela diretoria da subseção é do Presidente do Conselho Seccional respectivo da OAB.","c":"A competência privativa para julgar, em grau de recurso, questão decidida pela diretoria da subseção é do Conselho Seccional respectivo da OAB.","d":"A decisão proferida pela diretoria da subseção é irrecorrível."}', 'c', 'O art. 76 do Estatuto prevê recurso ao Conselho Seccional contra as decisões da diretoria da Subseção, e o art. 58, III, confirma que compete privativamente ao Conselho Seccional julgar esses recursos.'),
('22948207-958b-4953-8f32-cc4337f7e734', 'b723cff5-96fe-40a6-8afc-b3aaba3d9b0a', 2, '(37º Exame de Ordem (XXXVII), questão 1) Foi instaurado processo disciplinar em face do advogado Nino, tendo em vista possível prática de infração disciplinar. No que se refere às notificações de Nino no mencionado feito, assinale a afirmativa correta.', '{"a":"A notificação inicial de Nino para apresentação de defesa prévia deverá ser feita pessoalmente, de forma preferencial, admitindo-se a notificação por correspondência com aviso de recebimento apenas em hipóteses excepcionais, previstas no Regulamento Geral do Estatuto da Advocacia e da OAB.","b":"Na hipótese de a notificação inicial para apresentação de defesa prévia ser realizada por edital, deve constar do edital apenas o nome completo de Nino, o seu número de inscrição e a menção de que a notificação destina-se à apresentação da defesa prévia no feito disciplinar no prazo legal.","c":"As notificações realizadas no referido processo disicplinar que forem feitas através de edital, com exceção da notificação inicial, deverão indicar o nome completo de Nino e o do advogado constituído para sua defesa, salvo na hipótese de atuação em causa própria.","d":"Há presunção de recebimento das notificações enviadas por correspondência com aviso de recebimento ao endereço residencial ou ao endereço profissional que constam no cadastro de Nino junto ao Conselho Seccional."}', 'd', 'O Regulamento Geral (art. 137-D) estabelece a presunção de recebimento das notificações enviadas por correspondência com aviso de recebimento ao endereço residencial ou profissional constante do cadastro do advogado na Seccional. As demais alternativas alteram a forma preferencial da notificação ou o conteúdo exigido do edital.');--> statement-breakpoint
