INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('78c2a9cf-f1d6-496e-b9a3-b7fc910ae309', 'a675db1b-9273-4c47-9fd7-295f5eb9284d', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 18: Advocacia pro bono', '<table><tbody><tr><td><p><strong>18º</strong></p><p>lugar em incidência</p></td><td><p><strong>3</strong></p><p>questões em 48 provas</p></td><td><p><strong>0,7%</strong></p><p>das questões de Ética</p></td><td><p><strong>1</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>estável</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Criada pelo CED de 2015, caiu três vezes — sempre cobrando o <strong>conceito</strong> e a <strong>proibição de uso para publicidade</strong>.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>CED, art. 30</li></ul></td></tr></tbody></table>
<h2>Regras (CED, art. 30)</h2>
<ul><li><strong>Conceito</strong>: prestação <strong>gratuita, eventual e voluntária</strong> de serviços jurídicos em favor de <strong>instituições sociais sem fins econômicos</strong> e de <strong>seus assistidos</strong>, quando os beneficiários não puderem pagar um profissional (§ 1º).</li><li>Também pode beneficiar <strong>pessoas naturais</strong> que não possam contratar advogado sem prejuízo do próprio sustento (§ 2º).</li><li><strong>Não pode</strong> ser usada para fins <strong>político-partidários ou eleitorais</strong>, nem beneficiar instituições com esses objetivos, nem servir de <strong>instrumento de publicidade para captação de clientela</strong> (§ 3º).</li><li>Pro bono <strong>não afasta incompatibilidade</strong>: o policial civil, por exemplo, continua proibido de advogar, mesmo de graça.</li></ul>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Pro bono habitual ou permanente" → <strong>errado</strong>: é <strong>eventual</strong>.</li><li>"Pode cobrar preço simbólico" → <strong>errado</strong>: é <strong>gratuita</strong>.</li><li>"Pode ser usada para divulgar o escritório" → <strong>errado</strong>.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 18. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('c77abb98-8245-4ee2-9b3c-c89adde607a0', 'Ética — Cap. 18: Advocacia pro bono (questões comentadas do ebook)', '78c2a9cf-f1d6-496e-b9a3-b7fc910ae309', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('5336c612-86c0-4d93-975e-83646151314c', 'c77abb98-8245-4ee2-9b3c-c89adde607a0', 1, '(38º Exame de Ordem (XXXVIII), questão 3) O advogado Luís Santos, regularmente inscrito na OAB, está em início de carreira. Luís presta serviços jurídicos a determinada instituição social sem fins econômicos, consistentes em patrocinar seus interesses em demanda judicial em curso. Sobre a atuação de Luís, assinale a afirmativa correta.', '{"a":"Não poderá ser considerada advocacia pro bono a atuação gratuita de Luís como advogado das pessoas naturais, hipossuficientes econômicas, beneficiárias da instituição social.","b":"É ilícito que Luís preste gratuitamente tais serviços jurídicos, se o objetivo é valer-se de sua atuação como instrumento de publicidade da sua atividade profissional.","c":"A atuação gratuita de Luís, ainda que não seja eventual, na defesa em Juízo da mencionada instituição social, pode ser considerada advocacia pro bono.","d":"É admitida a prestação por Luís, sob a forma de advocacia pro bono voluntária, de serviços jurídicos para uma instituição social cobrando preços simbólicos, haja vista a ausência de fins econômicos."}', 'b', 'O art. 30, § 3º, do CED proíbe que a advocacia pro bono seja utilizada como instrumento de publicidade para captação de clientela. A e C erram no conceito: os assistidos da instituição podem ser atendidos (A), e a atividade deve ser eventual (C). D erra porque pro bono é gratuito.'),
('26a5faff-c6b3-4814-8987-02c6b4febb58', 'c77abb98-8245-4ee2-9b3c-c89adde607a0', 2, '(QUESTÃO INÉDITA NO ESTILO FGV) O advogado Rui, pré-candidato a vereador, pretende oferecer atendimento jurídico gratuito semanal à associação de moradores de seu bairro, entidade sem fins econômicos, divulgando a iniciativa em suas redes sociais. Sobre a situação, assinale a afirmativa correta.', '{"a":"A conduta é permitida, pois a associação não tem fins econômicos e os serviços seriam gratuitos.","b":"A conduta é vedada, pois a advocacia pro bono não pode ser utilizada para fins político-partidários ou eleitorais.","c":"A conduta é permitida, desde que Rui não cobre honorários de sucumbência nas causas patrocinadas.","d":"A conduta é vedada apenas porque a advocacia pro bono só pode beneficiar pessoas naturais."}', 'b', 'O CED, art. 30, § 3º, veda o uso da advocacia pro bono para fins político-partidários ou eleitorais e como instrumento de publicidade. Além disso, o atendimento semanal contraria o caráter eventual do § 1º. D erra porque instituições sociais sem fins econômicos podem ser beneficiadas.');--> statement-breakpoint
