VALUES ('49f3dd15-9a7a-43e9-b2ef-6326610fea62', 'Ética — Cap. 19: Advocacia pública (questões comentadas do ebook)', '13c434b1-cfb8-4687-a391-2f73085d225c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('6cbab9f9-4129-4f5b-a4b8-ab4f90f9539e', '49f3dd15-9a7a-43e9-b2ef-6326610fea62', 1, '(QUESTÃO INÉDITA NO ESTILO FGV) Lúcia foi aprovada em concurso e tomou posse como procuradora do Município Alfa. Sobre sua situação perante a OAB, assinale a afirmativa correta.', '{"a":"Lúcia não precisa manter inscrição na OAB, pois sua atuação decorre do cargo público.","b":"Lúcia exerce advocacia, sujeita-se ao Estatuto da OAB e ao regime próprio do cargo, e deve manter inscrição na OAB.","c":"Lúcia fica sujeita apenas ao regime próprio do cargo, e não ao Código de Ética e Disciplina da OAB.","d":"Lúcia não poderá se candidatar a cargos nos órgãos da OAB enquanto exercer a função pública."}', 'b', 'Pelo EAOAB, art. 3º, § 1º, os integrantes das procuradorias municipais exercem atividade de advocacia e se sujeitam ao Estatuto, além do regime próprio; por isso devem estar inscritos. O STF confirmou essa obrigatoriedade no Tema 936 (2026). O RG (art. 9º, parágrafo único) diz que são elegíveis e podem integrar qualquer órgão da OAB. C erra porque o CED também os obriga (art. 8º); o STF apenas atribuiu à corregedoria do órgão o poder disciplinar sobre a atuação funcional.'),
('e234b4d6-2aa5-44db-882a-d8411569b55a', '49f3dd15-9a7a-43e9-b2ef-6326610fea62', 2, '(QUESTÃO INÉDITA NO ESTILO FGV) Pedro é defensor público estadual e nunca foi inscrito na OAB. Uma parte contrária alega nulidade dos atos por ele praticados em juízo, por ausência de inscrição. À luz da jurisprudência do Supremo Tribunal Federal, assinale a afirmativa correta.', '{"a":"Os atos são nulos, pois o Estatuto da OAB exige a inscrição de todos os integrantes da Defensoria Pública.","b":"Os atos são anuláveis e podem ser ratificados por advogado inscrito.","c":"Os atos são válidos, pois a capacidade postulatória do defensor público decorre de sua nomeação e posse no cargo.","d":"Os atos são válidos apenas se praticados em favor de pessoas hipossuficientes na Justiça do Trabalho."}', 'c', 'No julgamento da ADI 4.636, o STF deu interpretação conforme ao art. 3º, § 1º, do Estatuto para afastar a exigência de inscrição na OAB para os defensores públicos, cuja capacidade postulatória decorre da nomeação e posse no cargo.');--> statement-breakpoint
