VALUES ('e45ac447-6407-4d7d-b5a6-9c7809024c22', 'Ética — Cap. 19: Advocacia pública', '13c434b1-cfb8-4687-a391-2f73085d225c', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 5);--> statement-breakpoint
INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('b09c49dc-7082-4454-97ac-0070703e5d92', 'e45ac447-6407-4d7d-b5a6-9c7809024c22', 1, 'Quem exerce advocacia pública e se sujeita ao Estatuto (art. 3º, § 1º)?', 'Os integrantes da AGU, da Procuradoria da Fazenda Nacional e das Procuradorias e Consultorias Jurídicas dos Estados, DF, Municípios e respectivas entidades da Administração indireta e fundacional.', 'medium'),
('397d3f30-864a-40d7-bed1-19e5d26dc75d', 'e45ac447-6407-4d7d-b5a6-9c7809024c22', 2, 'O advogado público precisa de inscrição na OAB? Pode integrar órgãos da Ordem?', 'Sim, a inscrição é obrigatória (STF, Tema 936). É elegível e pode integrar qualquer órgão da OAB (RG, art. 9º).', 'medium'),
('c645d7b2-0f90-4595-9e47-6cc89d1df11c', 'e45ac447-6407-4d7d-b5a6-9c7809024c22', 3, 'Quem julga disciplinarmente o advogado público pela sua atuação funcional?', 'A corregedoria do próprio órgão, e não o TED da OAB (STF, RE 609.517, Tema 936, 2026).', 'medium'),
('e68c8b3e-6154-4af7-8a57-dd8b53196e80', 'e45ac447-6407-4d7d-b5a6-9c7809024c22', 4, 'O defensor público precisa de inscrição na OAB?', 'Não. Pelo STF (ADI 4.636), sua capacidade postulatória decorre da nomeação e posse no cargo.', 'medium'),
('b886866a-5288-4ca3-aac1-b1f598426e5a', 'e45ac447-6407-4d7d-b5a6-9c7809024c22', 5, 'Advogados públicos podem receber honorários de sucumbência?', 'Sim, são constitucionais, respeitado o teto remuneratório (STF, ADI 6.053).', 'medium');--> statement-breakpoint
