VALUES ('22ca3160-8416-4147-9f68-11897c8e921b', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 21, '2026-11-23', 'Capítulo 20 — Exercício de cargos e funções na OAB', 'Capítulo novo do CED de 2015 (arts. 31 a 34). Caiu duas vezes — sempre sobre o que o advogado que ocupa cargo na Ordem não pode fazer.');--> statement-breakpoint
