INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('df6064d5-4de0-46fa-a167-5f6045811fbb', '42ed589f-09e8-403f-9428-9711accf2ce2', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Cap. 20: Exercício de cargos e funções na OAB', '<table><tbody><tr><td><p><strong>20º</strong></p><p>lugar em incidência</p></td><td><p><strong>2</strong></p><p>questões em 48 provas</p></td><td><p><strong>0,4%</strong></p><p>das questões de Ética</p></td><td><p><strong>1</strong></p><p>nas 12 provas mais recentes</p></td><td><p><strong>estável</strong></p><p>tendência recente</p></td></tr></tbody></table>
<p>Capítulo novo do CED de 2015 (arts. 31 a 34). Caiu duas vezes — sempre sobre o que o advogado que ocupa cargo na Ordem <strong>não pode fazer</strong>.</p>
<table><tbody><tr><td><p><strong>LEITURA OBRIGATÓRIA — LEIA A LEI SECA ANTES DE SEGUIR</strong></p><ul><li>CED, arts. 31 a 34</li></ul></td></tr></tbody></table>
<h2>Regras</h2>
<ul><li>O advogado que ocupa cargo ou função na OAB deve manter conduta compatível com o CED e <strong>plena lealdade aos interesses, direitos e prerrogativas da classe</strong> (art. 31).</li><li>É vedado firmar <strong>contratos onerosos</strong> de prestação de serviços ou fornecimento de produtos com instituições da OAB, com quem exerce cargo ou função em órgão da OAB ou representa a classe perante outras instituições, órgãos ou comissões. Também é vedado <strong>adquirir bens imóveis ou móveis infungíveis</strong> dos órgãos da OAB ou <strong>aliená-los</strong> a eles (art. 32). Contrato <strong>gratuito</strong> é permitido.</li><li><strong>Salvo em causa própria ou quando dirigentes de Seccionais, nessa qualidade, como legitimados a recorrer nos processos em trâmite perante os órgãos da OAB</strong>, não pode <strong>atuar em processos que tramitem perante a OAB</strong> nem oferecer pareceres para instruí-los, enquanto exercer cargo ou tiver assento nos Conselhos (art. 33).</li></ul>
<table><tbody><tr><td><p><strong>PEGADINHAS DA FGV</strong></p><ul><li>"Integrante de comissão pode vender imóvel à Seccional por preço de mercado" → <strong>errado</strong>.</li><li>"Conselheiro pode defender colega em processo disciplinar" → <strong>errado</strong>, salvo causa própria.</li><li>"Contrato gratuito também é vedado" → <strong>errado</strong>.</li></ul></td></tr></tbody></table><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), capítulo 20. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('2fd7f45e-cb98-4eba-8475-cc3467d24f00', 'Ética — Cap. 20: Exercício de cargos e funções na OAB (questões comentadas do ebook)', 'df6064d5-4de0-46fa-a167-5f6045811fbb', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 2);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('075a625f-512e-415e-b461-3acc0e75f7d4', '2fd7f45e-cb98-4eba-8475-cc3467d24f00', 1, '(37º Exame de Ordem (XXXVII), questão 8) A advogada Maria integra a Comissão de Defesa do Consumidor de certa Seccional da OAB, promovendo debates e a qualificação profissional de colegas sobre temas específicos de Direito do Consumidor. Sobre a atuação de Maria, enquanto integrar a comissão, assinale a afirmativa correta.', '{"a":"Maria poderá firmar contrato gratuito de prestação de serviços com entidades da OAB.","b":"Maria é impedida de adquirir bens móveis fungíveis de entidades da OAB.","c":"Maria poderá alienar bens móveis infungíveis para entidades da OAB.","d":"Maria poderá adquirir bens imóveis de entidades da OAB."}', 'a', 'O art. 32 do CED veda contratos onerosos com instituições da OAB, bem como adquirir bens imóveis ou móveis infungíveis de seus órgãos ou aliená-los a eles. Contrato gratuito de prestação de serviços é permitido.'),
('471f0cc5-cca1-41bc-9169-619ba3fe5748', '2fd7f45e-cb98-4eba-8475-cc3467d24f00', 2, '(QUESTÃO INÉDITA NO ESTILO FGV) Ricardo é conselheiro seccional da OAB. Um colega, representado disciplinarmente, pede que Ricardo assuma sua defesa no processo que tramita no Tribunal de Ética e Disciplina da mesma Seccional. Assinale a afirmativa correta.', '{"a":"Ricardo pode aceitar, desde que se declare impedido de votar no julgamento.","b":"Ricardo pode aceitar, pois o processo tramita no TED, órgão distinto do Conselho Seccional.","c":"Ricardo não pode aceitar, pois, salvo em causa própria, quem tem assento nos Conselhos da OAB não pode atuar em processos que tramitem perante a entidade.","d":"Ricardo pode aceitar, desde que atue gratuitamente."}', 'c', 'O CED, art. 33, proíbe o advogado que exerce cargo ou tem assento nos Conselhos da OAB de atuar em processos que tramitem perante a entidade — incluindo os disciplinares no TED — ressalvada a atuação em causa própria.');--> statement-breakpoint
