VALUES ('31c35361-978b-4791-98fb-58459d395796', '22ca3160-8416-4147-9f68-11897c8e921b', 2, 'Questões comentadas do ebook', 'exercise', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '{"exerciseSetId":"2fd7f45e-cb98-4eba-8475-cc3467d24f00"}', 20);--> statement-breakpoint
