VALUES ('def2a7aa-c92e-4546-a38c-e6bea4aefd5a', '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 22, '2026-11-24', 'Revisão de véspera', 'Temas que ainda não caíram, as 40 frases que valem pontos e uma revisão com todas as questões comentadas do ebook.');--> statement-breakpoint
INSERT INTO `training_topics` (`id`, `training_day_id`, `order`, `title`, `type`, `subject_id`, `content`, `estimated_minutes`)
VALUES ('99b5698d-ce28-4155-b861-884ef5b19780', 'def2a7aa-c92e-4546-a38c-e6bea4aefd5a', 1, 'Leitura: Temas que ainda não caíram', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('68f1e99d-6665-46aa-8f63-ace8cda4efc0', '99b5698d-ce28-4155-b861-884ef5b19780', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Temas que ainda não caíram', '<p>Dois blocos da legislação nunca apareceram em questão nas 48 provas analisadas. Leia uma vez, sem gastar muito tempo.</p>
<h2>Relações com colegas, agentes políticos, autoridades e terceiros (CED, arts. 27 a 29)</h2>
<ul><li>O advogado deve tratar colegas, autoridades, servidores e terceiros com <strong>urbanidade e respeito</strong>, usando linguagem escorreita e polida, e exigir o mesmo tratamento.</li><li>Deve evitar críticas pessoais e manter <strong>consideração e respeito recíprocos</strong> com magistrados, membros do Ministério Público e demais agentes.</li><li>Quem se vale do trabalho de colegas deve dispensar-lhes <strong>tratamento condigno</strong>, sem torná-los subalternos nem aviltar sua remuneração.</li></ul>
<h2>Exame de Ordem e disposições gerais</h2>
<ul><li>O Exame de Ordem é regulamentado por <strong>Provimento do Conselho Federal</strong> (EAOAB, art. 8º, § 1º) e realizado pelos <strong>Conselhos Seccionais</strong> (art. 58, VI).</li><li>O Conselho Federal edita o Regulamento Geral por deliberação de <strong>2/3 das delegações</strong> (art. 78).</li><li>Aos servidores da OAB aplica-se o <strong>regime trabalhista</strong> (art. 79).</li><li>Conferências <strong>trienais</strong> do Conselho Federal e das Seccionais, em ano não eleitoral (art. 80).</li></ul><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), temas que ainda não caíram. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `training_topics` (`id`, `training_day_id`, `order`, `title`, `type`, `subject_id`, `content`, `estimated_minutes`)
VALUES ('f386ba2e-6a46-4518-a407-aca2e1d2f9a8', 'def2a7aa-c92e-4546-a38c-e6bea4aefd5a', 2, 'Leitura: Revisão de véspera — 40 frases que valem pontos', 'apostila', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), NULL, 15);--> statement-breakpoint
INSERT INTO `apostilas` (`id`, `training_topic_id`, `subject_id`, `title`, `content_html`, `pdf_url`, `generated_by`)
VALUES ('27eae725-07a2-41be-8c21-e0a3f16bb302', 'f386ba2e-6a46-4518-a407-aca2e1d2f9a8', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 'Ética — Revisão de véspera — 40 frases que valem pontos', '<ul><li>Não há hierarquia entre advogado, juiz e promotor; nas audiências, os advogados das partes ficam no mesmo plano e equidistantes do juiz.</li><li>Autos sigilosos de investigação: só com procuração; a autoridade limita apenas diligências em andamento e não documentadas.</li><li>Busca no escritório: decisão motivada, indícios de crime do advogado, mandado específico e representante da OAB presente.</li><li>Advogado não pode fazer colaboração premiada contra cliente ou ex-cliente; a pena disciplinar pode chegar à exclusão.</li><li>Prisão por motivo profissional: só flagrante de crime inafiançável e com representante da OAB; sem relação com a profissão, basta comunicar a Seccional.</li><li>Sala de Estado-Maior só antes do trânsito em julgado; na falta, prisão domiciliar.</li><li>Gestante: sem detector de metais e com vaga na garagem; adotante ou que deu à luz, única patrona: prazos suspensos.</li><li>Desagravo: de ofício ou a pedido de qualquer pessoa; o ofendido não pode dispensá-lo.</li><li>Imunidade: injúria e difamação, nunca calúnia ou desacato.</li><li>Honorários sem estipulação: 1/3, 1/3, 1/3.</li><li>Cobrança de honorários prescreve em 5 anos; prestação de contas também.</li><li>Bloqueio universal: até 20% dos bens para honorários, salvo Lei de Drogas.</li><li>Quota litis em dinheiro; somada à sucumbência, não pode superar a vantagem do cliente.</li><li>Não pode sacar duplicata de honorários; pode emitir fatura e aceitar cartão.</li><li>Para cobrar honorários em juízo, renuncie antes ao mandato.</li><li>Censura não é publicada e pode virar advertência se houver atenuante.</li><li>Suspensão: 30 dias a 12 meses, em todo o território nacional.</li><li>Exclusão: três suspensões ou falsa prova, inidoneidade e crime infamante; quórum de 2/3.</li><li>Multa nunca é aplicada sozinha.</li><li>Prescrição disciplinar: 5 anos da constatação oficial; 3 anos parado gera prescrição intercorrente.</li><li>Reabilitação: 1 ano após cumprir a sanção; se houve crime, precisa da reabilitação criminal.</li><li>Anuidade em atraso não gera suspensão (STF).</li><li>Sociedade de advogados: registro só na Seccional da sede.</li><li>Sócios da mesma sociedade não atuam em lados opostos.</li><li>Não pode ter duas sociedades (ou sociedade + unipessoal) na mesma Seccional.</li><li>Sócio responde subsidiária e ilimitadamente.</li><li>Mandato não acaba pelo decurso do tempo.</li><li>Renúncia: 10 dias, sem declarar o motivo, preferencialmente por carta com AR.</li><li>Procuração de quem já tem advogado: só com ciência dele, salvo urgência.</li><li>Divulgação da advocacia com outra atividade é sempre vedada.</li><li>Cartão de visita: foto do escritório sim; foto pessoal e cargo (salvo professor) não.</li><li>Atos de não inscrito ou de suspenso são nulos; habeas corpus não é privativo.</li><li>Consultoria pode ser verbal, sem mandato e sem contrato.</li><li>Doença mental curável gera licença; incurável gera cancelamento.</li><li>Carteira da OAB vale como identidade civil.</li><li>Quem pune é a Seccional do local da infração; a suspensão preventiva é do TED da inscrição principal, com oitiva prévia e 90 dias.</li><li>Denúncia anônima não instaura processo disciplinar; o processo é sigiloso.</li><li>Incompatibilidade é total e vale mesmo em causa própria; impedimento é parcial.</li><li>Estagiário, sozinho: carga de autos, certidões e petição de juntada.</li><li>Sigilo é de ordem pública: o advogado pode recusar-se a depor mesmo autorizado pelo cliente.</li></ul><p><em>Fonte: Ebook Ética — Descomplicando OAB (Edição 2026), revisão de véspera. <a href="/materiais/ebook-etica-descomplicando-oab.docx">Baixar o ebook completo</a>.</em></p>', '/materiais/ebook-etica-descomplicando-oab.docx', 'ebook');--> statement-breakpoint
INSERT INTO `flashcard_sets` (`id`, `title`, `apostila_id`, `subject_id`, `card_count`)
VALUES ('651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 'Ética — as 40 frases da véspera', '68f1e99d-6665-46aa-8f63-ace8cda4efc0', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 40);--> statement-breakpoint
INSERT INTO `flashcard_set_cards` (`id`, `set_id`, `order`, `front`, `back`, `difficulty`) VALUES
('a7548887-e18f-444c-8ea6-e3a8bfd3dc0e', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 1, 'Há hierarquia entre advogado, juiz e promotor? Como ficam os advogados nas audiências?', 'Não há hierarquia. Nas audiências, os advogados das partes ficam no mesmo plano topográfico e equidistantes do juiz (EAOAB, art. 6º).', 'medium'),
('3ef677e5-2e41-4862-a50c-b81962891b01', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 2, 'Autos sigilosos de investigação: o advogado precisa de procuração? O que a autoridade pode limitar?', 'Sim, só com procuração. A autoridade limita apenas diligências em andamento e ainda não documentadas (art. 7º, §§ 10 e 11).', 'medium'),
('892fed47-f1d3-4ba7-8dab-a09538682dd6', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 3, 'Quais os requisitos para a busca no escritório do advogado?', 'Decisão judicial motivada, indícios de crime do próprio advogado, mandado específico e pormenorizado e representante da OAB presente (art. 7º, § 6º).', 'medium'),
('e0095aab-1c6c-4065-97a4-fde4311202a0', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 4, 'O advogado pode fazer colaboração premiada contra cliente ou ex-cliente?', 'Não. A violação gera processo disciplinar e a pena pode chegar à exclusão (art. 7º, § 6º-I).', 'medium'),
('10dbfd0d-780b-4965-9e51-00211960d63f', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 5, 'Prisão do advogado: o que se exige quando o motivo é ligado à profissão? E quando não é?', 'Ligado à profissão: só flagrante de crime inafiançável e com representante da OAB. Sem relação com a profissão: basta comunicar a Seccional.', 'medium'),
('58759836-4a62-4acd-af78-90c928353b79', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 6, 'Até quando o advogado tem direito à sala de Estado-Maior? E se não houver?', 'Só antes do trânsito em julgado. Na falta da sala, prisão domiciliar.', 'medium'),
('26336da0-6d25-40d6-86a4-171c4f5589e6', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 7, 'Quais direitos têm a advogada gestante e a adotante ou que deu à luz?', 'Gestante: entra sem detector de metais e tem vaga na garagem. Adotante ou que deu à luz, sendo a única patrona: prazos processuais suspensos (art. 7º-A).', 'medium'),
('6890d3bd-866e-4795-be45-4441d2d3b9d9', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 8, 'Quem pode provocar o desagravo público? O ofendido pode dispensá-lo?', 'É promovido de ofício ou a pedido de qualquer pessoa. O ofendido não pode dispensá-lo.', 'medium'),
('72cd77ca-5534-4cf9-9c29-33704d20a5cf', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 9, 'A imunidade profissional do advogado alcança quais crimes?', 'Injúria e difamação — nunca calúnia ou desacato.', 'medium'),
('e26e3bcb-5eab-46a6-89de-03e59a25a1c6', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 10, 'Sem estipulação sobre a forma de pagamento, como são pagos os honorários?', '1/3 no início, 1/3 até a decisão de primeira instância e 1/3 no final (art. 22, § 3º).', 'medium'),
('4a0b685c-7dde-47cc-87ea-80bfa7108aab', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 11, 'Em quanto tempo prescreve a cobrança de honorários? E a prestação de contas contra o advogado?', 'Ambas em 5 anos (arts. 25 e 25-A).', 'medium'),
('62f6f19e-0f55-4755-81cf-dd606f2c1313', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 12, 'Bloqueio universal de bens do cliente: quanto o advogado pode liberar para honorários? Há exceção?', 'Até 20% dos bens, salvo nas causas da Lei de Drogas (art. 24-A).', 'medium'),
('ae876e6e-97fe-42e5-9766-1486661c0ef3', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 13, 'Quais os limites da cláusula quota litis?', 'Honorários em dinheiro; somados à sucumbência, não podem superar a vantagem do cliente (CED, art. 50).', 'medium'),
('b8b107bb-a858-4357-996a-ca0f91cbac17', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 14, 'O advogado pode sacar duplicata para cobrar honorários?', 'Não. Pode emitir fatura e aceitar cartão de crédito (CED, arts. 52 e 53).', 'medium'),
('4a7ba2ca-b72a-4ee9-8b4f-9022917135b9', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 15, 'O que o advogado deve fazer antes de cobrar honorários em juízo do próprio cliente?', 'Renunciar antes ao mandato (CED, art. 54).', 'medium'),
('49b185c9-9a6d-4bbe-a381-3de82a6041ff', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 16, 'A censura é publicada? Pode ser convertida?', 'Não é publicada e pode virar advertência, em ofício reservado, se houver atenuante.', 'medium'),
('849814f7-97c6-4c1a-992b-df807be8d9df', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 17, 'Qual a duração e a abrangência da suspensão?', 'De 30 dias a 12 meses, em todo o território nacional.', 'medium'),
('7cf71801-baca-4f5b-93a8-e032c3e0a934', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 18, 'Quando cabe a exclusão e qual o quórum?', 'Três suspensões, falsa prova de requisito de inscrição, inidoneidade moral ou crime infamante; quórum de 2/3 do Conselho Seccional.', 'medium'),
('98322aa4-05d2-48b3-9ee9-11ad8d0a731f', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 19, 'A multa pode ser aplicada isoladamente?', 'Não. A multa nunca é aplicada sozinha.', 'medium'),
('25b26001-c3d9-42ea-b427-5490a55295cb', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 20, 'Qual o prazo da prescrição disciplinar? E a prescrição intercorrente?', '5 anos da constatação oficial do fato; o processo parado por mais de 3 anos gera prescrição intercorrente (art. 43).', 'medium'),
('91da4986-0c86-4486-8310-2279befe99be', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 21, 'Quando o advogado punido pode pedir reabilitação?', '1 ano após cumprir a sanção; se a infração resultou de crime, depende também da reabilitação criminal (art. 41).', 'medium'),
('60bc0ebf-8186-40a7-b2b7-fe73043a44ac', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 22, 'A anuidade em atraso pode gerar suspensão do advogado?', 'Não. O STF declarou inconstitucional a suspensão por anuidade em atraso.', 'medium'),
('80c0b41d-5698-4d04-a04b-f5af015cfc5b', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 23, 'Onde se registra a sociedade de advogados?', 'Só no Conselho Seccional da OAB da sede — nunca na Junta Comercial.', 'medium'),
('fe8c0db4-74ae-4f55-b7b6-a1a6ca173625', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 24, 'Sócios da mesma sociedade podem atuar em lados opostos da mesma causa?', 'Não (art. 15, § 6º).', 'medium'),
('f50652a3-1161-43ba-b7d6-540fbac9d0ae', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 25, 'O advogado pode integrar duas sociedades (ou sociedade + unipessoal) na mesma Seccional?', 'Não (art. 15, § 4º).', 'medium'),
('588c2739-ad0b-4b72-b8c1-ec99495aa40c', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 26, 'Como o sócio responde pelos danos causados aos clientes?', 'De forma subsidiária e ilimitada (art. 17).', 'medium'),
('ec304e20-a782-47d5-a95c-cb4fd32fd7d9', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 27, 'O mandato se extingue pelo decurso do tempo?', 'Não, salvo se o instrumento fixar prazo (CED, art. 18).', 'medium'),
('c52d3de3-f142-490a-9f19-613736733ac4', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 28, 'Como funciona a renúncia ao mandato?', 'Omite o motivo; notifica-se o cliente, preferencialmente por carta com AR, e o advogado continua representando por 10 dias, salvo substituição antes.', 'medium'),
('bb360347-6ee4-45e8-a861-28027c685863', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 29, 'O advogado pode aceitar procuração de quem já tem advogado constituído?', 'Só com prévio conhecimento do colega, salvo motivo plenamente justificável ou medidas urgentes e inadiáveis (CED, art. 14).', 'medium'),
('3d16d826-5f16-4449-b538-b843be7c9dba', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 30, 'A advocacia pode ser divulgada em conjunto com outra atividade?', 'Não. A divulgação conjunta é sempre vedada (EAOAB, art. 1º, § 3º; CED, art. 40, IV).', 'medium'),
('afd68612-e3dd-48d5-bfed-4223dd2aebce', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 31, 'O que pode e o que não pode constar no cartão de visita do advogado?', 'Foto do escritório pode; foto pessoal não; cargo ocupado não, salvo o de professor universitário.', 'medium'),
('eb096c61-18b9-458c-ba25-c36a32285f30', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 32, 'Qual a consequência dos atos privativos praticados por não inscrito ou por advogado suspenso? O habeas corpus é privativo?', 'São nulos. O habeas corpus não é privativo de advogado.', 'medium'),
('20da0951-0a27-4039-b9ad-0bcbf15cfb76', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 33, 'A consultoria jurídica exige mandato ou contrato?', 'Não. Pode ser verbal, sem mandato e sem contrato (art. 5º, § 4º).', 'medium'),
('cb993985-c682-4180-889d-8f2e5aac0fda', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 34, 'Doença mental: quando gera licença e quando gera cancelamento da inscrição?', 'Curável gera licença; incurável gera cancelamento.', 'medium'),
('5a35cb8b-2f88-4dd2-b656-2eaf9a9580b4', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 35, 'A carteira da OAB vale como identidade?', 'Sim, vale como documento de identidade civil.', 'medium'),
('0615051b-4ff1-461d-91f5-c76350ea974d', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 36, 'Quem tem competência para punir o advogado? E para a suspensão preventiva?', 'Pune a Seccional do local da infração. A suspensão preventiva é do TED da inscrição principal, com oitiva prévia, por até 90 dias.', 'medium'),
('d998d567-8a10-45e7-bf5e-5ce3ad3f9599', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 37, 'Denúncia anônima instaura processo disciplinar? O processo é público?', 'Não instaura. O processo disciplinar é sigiloso.', 'medium'),
('ade568a4-8cd5-4997-b4ed-091586564a75', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 38, 'Qual a diferença entre incompatibilidade e impedimento?', 'Incompatibilidade é proibição total e vale mesmo em causa própria; impedimento é proibição parcial.', 'medium'),
('870b57c8-ccf0-4742-b2db-a42e319cb4e8', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 39, 'Que atos o estagiário pode praticar sozinho?', 'Retirar e devolver autos (carga), obter certidões e assinar petição de juntada de documentos (RG, art. 29, § 1º).', 'medium'),
('56627cd8-34de-453c-97f5-db02df7b7f32', '651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b', 40, 'O advogado pode recusar-se a depor sobre fato sigiloso mesmo autorizado pelo cliente?', 'Sim. O sigilo é de ordem pública: pode recusar-se a depor mesmo autorizado ou solicitado pelo cliente.', 'medium');--> statement-breakpoint
INSERT INTO `training_topics` (`id`, `training_day_id`, `order`, `title`, `type`, `subject_id`, `content`, `estimated_minutes`)
VALUES ('ad9f0205-2a98-4d20-b2ed-f338727968f0', 'def2a7aa-c92e-4546-a38c-e6bea4aefd5a', 3, 'Flashcards: as 40 frases da véspera', 'flashcard', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '{"flashcardSetId":"651a60ab-e6d7-4d13-a8fa-2c573ddf9e8b"}', 30);--> statement-breakpoint
INSERT INTO `exercise_sets` (`id`, `title`, `apostila_id`, `subject_id`, `question_count`)
VALUES ('f150410e-8056-4488-9a4d-382e3249cffe', 'Ética — Revisão geral: as 40 questões comentadas do ebook', '68f1e99d-6665-46aa-8f63-ace8cda4efc0', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), 40);--> statement-breakpoint
INSERT INTO `exercise_questions` (`id`, `set_id`, `order`, `statement`, `alternatives`, `correct_answer`, `explanation`) VALUES
('ff55e9b9-272d-4618-a0b7-14257dc56d35', 'f150410e-8056-4488-9a4d-382e3249cffe', 1, '(46º Exame de Ordem (XLVI), questão 1) Paloma, advogada gestante, compareceu ao Fórum da Comarca de Itaporanga, PB, para participar de uma audiência. Ao tentar estacionar no local, foi impedida de acessar a garagem sob a justificativa de que não havia vagas reservadas para gestantes. Além disso, foi obrigada a passar por um detector de metais, mesmo tendo informado de sua condição de gestante. Indignada, Paloma buscou esclarecer os seus direitos. Sobre a hipótese narrada, com base no Estatuto da OAB, assinale a afirmativa correta.', '{"a":"Paloma, por ser advogada gestante, tem o direito de não ser submetida a detectores de metais, mas o estacionamento exclusivo só é garantido em Tribunais e Fóruns Federais, não nos Fóruns Estaduais.","b":"Os direitos de Paloma, como o de não ser submetida aos detectores de metais e à reserva de vagas, são aplicáveis apenas em Tribunais Superiores, e não se estendem a Fóruns de Comarcas Estaduais.","c":"Paloma, por ser advogada gestante, tem o direito de entrar em Fóruns e Tribunais sem ser submetida a detectores de metais e tem direito à reserva de vagas nas garagens dos Fóruns dos Tribunais.","d":"Paloma tem o direito de entrada no Fórum sem ser submetida a detectores de metais, mas o direito à reserva de vagas em garagens para gestantes é uma mera liberalidade do Tribunal e não é garantido por lei."}', 'c', 'O art. 7º-A, I, do Estatuto garante à advogada gestante, cumulativamente, a entrada nos tribunais sem submissão a detectores de metais e aparelhos de raio X (alínea a) e a reserva de vaga nas garagens dos fóruns dos tribunais (alínea b). A lei não restringe o direito a tribunais federais ou superiores (A e B erradas) nem trata a vaga como mera liberalidade (D errada).'),
('62173756-b7a1-479a-adad-924ce103ec7a', 'f150410e-8056-4488-9a4d-382e3249cffe', 2, '(44º Exame de Ordem (XLIV), questão 7) No âmbito de investigação sigilosa, o Magistrado competente decretou a prisão de João, amigo íntimo de Carlos. Carlos é advogado regularmente inscrito na Ordem dos Advogados do Brasil. Ao saber do cumprimento do mandado, com a consequente custódia de João, Carlos se dirigiu à delegacia e, em seguida, procurou o Magistrado plantonista para tratar do caso. Nesse contexto, assinale a afirmativa correta.', '{"a":"Carlos somente terá acesso aos autos da investigação que culminou na prisão de João se apresentar procuração para representá-lo. Nesse caso, deve lhe ser franqueado amplo acesso aos elementos de prova colhidos pela autoridade policial, não sendo possível a imposição de qualquer limitação.","b":"Carlos deverá ter acesso aos autos da investigação que culminou na prisão de João, independentemente da apresentação de procuração para representá-lo. Ademais, deve lhe ser franqueado amplo acesso aos elementos de prova colhidos pela autoridade policial, não sendo possível a imposição de qualquer limitação.","c":"Carlos somente terá acesso aos autos da investigação que culminou na prisão de João se apresentar procuração para representá-lo. Entretanto, o acesso aos elementos de prova colhidos pela autoridade policial poderá ser delimitado, desde que relacionados a diligências em andamento e ainda não documentados nos autos, desde que haja comprovado risco de comprometimento da eficiência, da eficácia ou da finalidade da investigação.","d":"Carlos deverá ter acesso aos autos da investigação que culminou na prisão de João, independentemente da apresentação de procuração para representá-lo. Entretanto, o acesso aos elementos de prova colhidos pela autoridade policial poderá ser delimitado, ainda que relacionados a diligências já encerradas e devidamente documentadas nos autos, desde que haja comprovado risco de comprometimento da eficiência, da eficácia ou da finalidade da investigação."}', 'c', 'João está preso numa investigação sigilosa. Pelo art. 7º, § 10, nos autos sujeitos a sigilo o advogado precisa apresentar procuração para exercer o direito do inciso XIV — por isso B e D estão erradas. E, pelo § 11, a autoridade pode delimitar o acesso apenas aos elementos de diligências em andamento e ainda não documentadas, quando houver risco à eficiência, eficácia ou finalidade da investigação. A alternativa A erra ao dizer que nenhuma limitação é possível; D erra ao permitir limitar diligências já encerradas.'),
('256736ca-3181-4ded-9a75-9d0167623ab7', 'f150410e-8056-4488-9a4d-382e3249cffe', 3, '(46º Exame de Ordem (XLVI), questão 6) Abelardo é contratado para representar o milionário Everardo em uma causa cível de importante vulto. Ficou combinado que, em caso de êxito, Abelardo fará jus a uma joia de elevadíssimo valor, a título de honorários. Sucede que, depois de ganhar a causa, Everardo sofreu revés na justiça criminal, quando uma decisão judicial determinou o bloqueio de todo o seu patrimônio pela suspeita de crimes financeiros. Nesse caso, à luz do Estatuto da Ordem dos Advogados do Brasil e do Código de Ética e Disciplina, assinale a afirmativa correta.', '{"a":"Abelardo poderá requerer ao Juiz Criminal o desbloqueio de até 20% dos bens de Everardo para o pagamento de seus honorários e dos demais custos com a defesa.","b":"Abelardo poderá, diante do bloqueio, participar dos bens particulares de Everardo, de forma excepcional, considerada a impossibilidade de pagamento por outro meio, ainda que tal forma de pagamento não tenha sido pactuada.","c":"A cláusula de honorários de êxito ou quota litis não é vedada, mas deve necessariamente ser expressa em pecúnia, de modo que, prevendo-se a entrega de uma joia, constata-se a nulidade que determina que Abelardo só fará jus aos honorários de sucumbência, se houver.","d":"A cláusula de honorários de êxito ou quota litis é vedada, de sorte que será necessário proceder ao arbitramento dos honorários de Abelardo, em remuneração compatível com o trabalho e o valor econômico da questão, observado obrigatoriamente o disposto no Art. 85 do Código de Processo Civil."}', 'a', 'Com o bloqueio de todo o patrimônio do cliente por decisão judicial, o art. 24-A do Estatuto garante ao advogado a liberação de até 20% dos bens bloqueados para recebimento de honorários e reembolso de gastos com a defesa (a causa não envolve a Lei de Drogas). A alternativa B é errada porque a participação em bens do cliente exige ajuste escrito (CED, art. 50, § 1º). D erra porque a quota litis não é vedada. C erra ao concluir que o advogado perderia os honorários contratados e ficaria só com a sucumbência: a lei não prevê essa consequência.'),
('44e03989-f3d6-43b3-a07e-bfbabe12970f', 'f150410e-8056-4488-9a4d-382e3249cffe', 4, '(36º Exame de Ordem (XXXVI), questão 1) Celso, advogado, foi contratado por Maria, servidora pública, para ajuizar ação com pedido de pagamento de determinada gratificação. O contrato celebrado entre eles prevê que Celso somente receberá honorários caso a demanda seja exitosa, em percentual do proveito econômico obtido por Maria. Em tal caso, é correto afirmar que', '{"a":"os honorários contratuais não poderão incidir sobre o valor das parcelas vincendas da gratificação.","b":"os honorários foram pactuados de forma correta, já que, nessa hipótese, deveriam ser necessariamente representados por pecúnia.","c":"os honorários não podem ser superiores às vantagens advindas a favor de Maria, exceto se acrescidos aos honorários de sucumbência.","d":"os honorários contratuais não poderão incidir sobre o valor das parcelas vencidas da gratificação."}', 'b', 'Na cláusula quota litis, o art. 50 do CED exige que os honorários sejam representados por pecúnia — exatamente o que ocorreu (percentual do proveito econômico). Como a causa envolve gratificação (prestações vencidas e vincendas), o § 2º permite que os honorários incidam sobre umas e outras, o que torna A e D erradas. C inverte a regra: somados à sucumbência, os honorários não podem superar as vantagens do cliente.'),
('0ad26613-8af3-4abf-816e-7ff985022583', 'f150410e-8056-4488-9a4d-382e3249cffe', 5, '(46º Exame de Ordem (XLVI), questão 5) Mateus, advogado regularmente inscrito na OAB, contratou Marcos, profissional da área de vendas, para abordar pessoas nas imediações da agência do Instituto Nacional do Seguro Social da sua cidade, visando à captação de causas previdenciárias. Foi acertado que Marcos teria participação nos honorários advocatícios das causas que conseguisse agenciar. Constatados os fatos, e após o devido processo administrativo disciplinar, o Tribunal de Ética e Disciplina do Conselho Seccional competente aplicou a pena de censura a Mateus. Considerando o enunciado e o Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Havendo circunstâncias atenuantes, será possível substituir a sanção de censura pela aplicação isolada de multa.","b":"Transitada em julgado a decisão, a sanção aplicada a Mateus deverá constar dos seus assentamentos, dando-se ampla publicidade nos meios oficiais.","c":"A gravidade da conduta infracional de Mateus não permite a conversão da pena de censura em advertência, ainda que verificada a ausência de punição disciplinar anterior.","d":"A circunstância de Mateus exercer de modo assíduo e proficiente mandato em cargo ou qualquer órgão da OAB, caso comprovada, deverá ser considerada pelo Tribunal na aplicação da sanção disciplinar."}', 'd', 'Valer-se de agenciador com participação nos honorários (art. 34, III) é punido com censura (art. 36, I). A multa só se aplica cumulada com censura ou suspensão (A errada). A censura não pode ser publicada (art. 35, parágrafo único — B errada). Presente atenuante, a censura pode ser convertida em advertência (art. 36, parágrafo único — C errada). E o exercício assíduo e proficiente de mandato na OAB é atenuante expressa (art. 40, III).'),
('013a48e4-e5ac-4780-a2b2-9bf627c536df', 'f150410e-8056-4488-9a4d-382e3249cffe', 6, '(45º Exame de Ordem (XLV), questão 5) O jovem Marcos foi contratado como auxiliar de escritório por renomada banca de advocacia. Autodidata e talentoso, Marcos aproveitava os momentos de folga para estudar os processos judiciais patrocinados pelo escritório e, apesar de nunca ter frequentado o curso de graduação em Direito, tornou-se relativamente conhecedor prático de muitos temas jurídicos. Com esse conhecimento, Marcos resolveu se inscrever no Exame da Ordem dos Advogados do Brasil, apresentando, para tanto, diploma falsificado de bacharel em Direito. Após a aprovação, Marcos se inscreveu como advogado na OAB, novamente fazendo uso do referido documento falso. Seis anos após esses fatos, uma denúncia anônima a respeito do ilícito ensejou a instauração do competente processo administrativo disciplinar. Considerando o enunciado e o Estatuto da Advocacia e da Ordem dos Advogados do Brasil, assinale a afirmativa correta.', '{"a":"A gravidade da conduta atribuída a Marcos atrai a competência do Conselho Federal da Ordem dos Advogados do Brasil para apurar e punir a infração disciplinar.","b":"Para a aplicação da sanção correspondente prevista em lei é necessária a manifestação de dois terços dos membros do Conselho Seccional competente.","c":"A sanção disciplinar prevista para a conduta de Marcos é a de suspensão, que deve perdurar até que seja apresentado documento idôneo, cumulada com a aplicação de multa.","d":"A pretensão à punibilidade da infração disciplinar encontra-se prescrita, uma vez que foi ultrapassado o prazo legal de cinco anos, contado da última data em que Marcos fez uso do documento falso."}', 'b', 'Usar diploma falso para se inscrever é fazer falsa prova de requisito de inscrição (art. 34, XXVI), punida com exclusão (art. 38, II), que exige 2/3 dos membros do Conselho Seccional (art. 38, parágrafo único). A competência é da Seccional (A errada) e a pena não é suspensão (C errada). A prescrição conta da constatação oficial do fato, e não do uso do documento (D errada).'),
('7cd38bbc-0dad-4699-8398-e7e833a59aed', 'f150410e-8056-4488-9a4d-382e3249cffe', 7, '(46º Exame de Ordem (XLVI), questão 4) Os advogados Eduardo e Diogo são sócios de uma sociedade profissional de advogados, cujos atos constitutivos foram devidamente registrados e aprovados pelo Conselho Seccional da OAB na base territorial em que está localizada a sua sede. No entanto, Eduardo foi contratado por Afonso para representá-lo em uma ação de alimentos movida por sua esposa Dalila, e Diogo foi contratado por Dalila para representá-la na mesma ação. Os advogados desejam saber se podem continuar com essas representações, tendo em vista que são sócios da mesma sociedade de advogados. Sobre o caso narrado, com base no Art. 15 do Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Eduardo e Diogo não podem representar, em juízo, clientes com interesses opostos, por serem sócios da mesma sociedade de advogados.","b":"Eduardo e Diogo podem representar Afonso e Dalila em juízo, desde que firmem compromisso por escrito de que não haverá conflito de interesse entre os dois advogados.","c":"Eduardo e Diogo podem continuar com as respectivas representações de Afonso e Dalila, desde que informem previamente ao Juiz que ambos fazem parte da mesma sociedade.","d":"Eduardo e Diogo podem continuar com as representações, desde que cada um atue de forma independente dentro da sociedade de advogados, contando com corpo auxiliar próprio."}', 'a', 'Regra literal do art. 15, § 6º, do Estatuto: os advogados sócios de uma mesma sociedade profissional não podem representar em juízo clientes de interesses opostos. Nenhuma providência — compromisso escrito, aviso ao juiz ou atuação independente — afasta a vedação.'),
('b5f5807d-7564-4cd3-855e-a160724cf2e3', 'f150410e-8056-4488-9a4d-382e3249cffe', 8, '(45º Exame de Ordem (XLV), questão 8) Pedro é advogado regularmente inscrito no Conselho Seccional da OAB do Estado Alfa e constituiu uma Sociedade Unipessoal de Advocacia registrada e ativa na mesma unidade federativa. Recentemente, ele foi convidado pelo renomado advogado Abraão para integrar uma Sociedade de Advogados, também com sede no Estado Alfa, na qualidade de sócio. Pedro considerou a proposta promissora e cogita aceitá-la, acreditando que pode participar de ambas as sociedades, desde que evite atuar nos mesmos processos ou contra os interesses de clientes de uma delas. Sobre a decisão de Pedro, com base no Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Pedro poderá integrar ambas as sociedades, desde que atue em processos distintos e jamais represente partes com interesses opostos.","b":"Pedro poderá aceitar o convite de Abraão apenas se encerrar formalmente a Sociedade Unipessoal de Advocacia que já possui no Estado Alfa.","c":"Pedro poderá participar das duas sociedades se firmar declaração formal de que manterá independência profissional e não haverá conflito de interesses.","d":"Pedro poderá manter a sua sociedade unipessoal e, ao mesmo tempo, integrar a sociedade de Abraão desde que a nova sociedade registre filial em outra área territorial, ainda que continue atuando no Estado Alfa."}', 'b', 'O art. 15, § 4º, proíbe integrar simultaneamente uma sociedade de advogados e uma sociedade unipessoal com sede ou filial na mesma área territorial do mesmo Conselho Seccional. Como as duas estão no Estado Alfa, Pedro só pode aceitar o convite se encerrar a unipessoal. Atuar em processos distintos ou declarar independência não resolve (A e C); abrir filial fora não muda o fato de ambas terem sede em Alfa (D).'),
('2ec8e379-237b-4e43-9795-6273555e99c5', 'f150410e-8056-4488-9a4d-382e3249cffe', 9, '(40º Exame de Ordem (XL), questão 2) Sebastião, advogado, celebrou contrato de mandato com o cliente Amir, para representá-lo extrajudicialmente, tendo realizado diligências em prol da resolução do imbróglio. Desde a celebração do mandato, passaram-se mais de 20 (vinte) anos, mas as atividades para as quais Amir contratou Sebastião, por sua própria natureza, se protraíram no tempo, sendo ainda necessárias a Amir. Sobre a hipótese apresentada, assinale a afirmativa correta.', '{"a":"O mandato extinguiu-se pelo decurso do tempo, salvo se previsto prazo diverso no respectivo instrumento.","b":"O mandato extinguiu-se pelo decurso do tempo, sendo vedada a previsão de prazo diverso no respectivo instrumento.","c":"O mandato não se extinguiu pelo decurso do tempo, salvo se foi consignado prazo no respectivo instrumento.","d":"O mandato não se extinguiu pelo decurso do tempo, sendo vedada a estipulação de prazo no respectivo instrumento."}', 'c', 'O art. 18 do CED dispõe que o mandato judicial ou extrajudicial não se extingue pelo decurso do tempo, salvo se o contrário for consignado no instrumento. Vinte anos, sozinhos, não extinguem o mandato de Sebastião. A e B invertem a regra; D erra ao proibir a estipulação de prazo.'),
('36751ee1-b8eb-4a2b-be85-a2781c5cdadb', 'f150410e-8056-4488-9a4d-382e3249cffe', 10, '(41º Exame de Ordem (XLI), questão 4) Ana Júlia, recentemente aprovada no Exame da Ordem dos Advogados do Brasil, aspira exercer sua nova atividade profissional de maneira comprometida com os deveres éticos e valores inerentes à elevada função pública da profissão. Nesse sentido, assinale a afirmativa que corretamente descreve a hipótese de cumprimento de dever ético por Ana Júlia.', '{"a":"Ana Júlia deverá, sempre que possível, estimular a conciliação e a mediação entre os litigantes, entendendo-se diretamente com a parte adversa, cujo eventual patrono constituído, na hipótese de haver a solução do conflito, deverá ser ulteriormente comunicado.","b":"Nos pleitos administrativos ou judiciais em que ingressar, Ana Júlia deverá atuar com destemor e independência, especialmente perante aquelas autoridades com as quais tenha vínculos negociais ou familiares.","c":"Ana Júlia deverá pugnar pela solução dos problemas da cidadania e pela efetivação dos direitos individuais, coletivos e difusos, dever que pode ser cumprido, por exemplo, com a adoção de política permanente de contratação de honorários advocatícios em valores abaixo da tabela da OAB.","d":"No exercício do seu mandato, Ana Júlia deverá atuar como patrona da parte e, portanto, imprimir à causa orientação que lhe pareça mais adequada, procurando esclarecer a estratégia traçada ao cliente, mas sem se subordinar às suas intenções contrárias."}', 'd', 'O art. 11 do CED diz que o advogado, como patrono, imprime à causa a orientação que lhe pareça mais adequada, sem se subordinar a intenções contrárias do cliente, mas procurando esclarecê-lo. A erra porque é vedado entender-se com a parte adversa que tenha patrono sem o assentimento dele (art. 2º, parágrafo único, VIII, d). B erra porque o advogado deve se abster de atuar perante autoridades com quem tenha vínculo negocial ou familiar. C erra porque contratar honorários aviltantes viola o CED.'),
('ed5f2922-3525-451b-8395-c3b53148e6d9', 'f150410e-8056-4488-9a4d-382e3249cffe', 11, '(46º Exame de Ordem (XLVI), questão 7) Frederico, advogado, após alcançar grande sucesso na advocacia, decidiu se dedicar também à construção civil, passando a atuar simultaneamente nas duas áreas. Diante da afinidade temática entre o Direito Imobiliário e o setor de construção civil, Frederico teve a ideia de unir ambas as atividades em um único escritório, oferecendo aos clientes consultoria jurídica e serviços de incorporação imobiliária. Para divulgar o seu novo empreendimento, contratou um escritório de marketing, que produziu uma campanha publicitária conjunta, ressaltando seus trabalhos como advogado e como empreendedor da construção civil. Sobre o fato narrado, com base no Estatuto da OAB, assinale a afirmativa correta.', '{"a":"É possível a divulgação conjunta, desde que respeitados o decoro e a dignidade da advocacia, cabendo ao Tribunal de Ética e Disciplina da OAB avaliar a adequação da publicidade.","b":"É permitida a divulgação conjunta apenas quando a outra atividade também for regulamentada por entidade de classe, hipótese em que a OAB poderá celebrar o convênio para a publicidade cruzada.","c":"É vedada a divulgação conjunta de advocacia com outra atividade, ainda que exercida pela mesma pessoa e que haja afinidade entre os ramos, como ocorre entre a advocacia imobiliária e a construção civil.","d":"Em regra, não é possível divulgar a advocacia em conjunto com outra atividade, mas nesse caso seria permitido, pois as atividades são exercidas por uma mesma pessoa e possuem afinidade temática, inexistindo conflito ético."}', 'c', 'O Estatuto (art. 1º, § 3º) e o CED (art. 40, IV) vedam a divulgação da advocacia em conjunto com outra atividade. A vedação vale mesmo quando as atividades são exercidas pela mesma pessoa e têm afinidade temática, como direito imobiliário e construção civil. Não há exceção por decoro (A), por regulamentação da outra atividade (B) ou por afinidade (D).'),
('0949c43e-9fb1-46a8-9a19-39fb173cd177', 'f150410e-8056-4488-9a4d-382e3249cffe', 12, '(36º Exame de Ordem (XXXVI), questão 3) A advogada Carolina e a estagiária de Direito Beatriz, que com ela atua, com o intuito de promover sua atuação profissional, valeram-se, ambas, de meios de publicidade vedados no Código de Ética e Disciplina da OAB. Após a verificação da irregularidade, indagaram sobre a possibilidade de celebração de termo de ajustamento de conduta tendo, como objeto, a adequação da publicidade. Considerando o caso narrado, assinale a afirmativa correta.', '{"a":"É admitida a celebração do termo de ajustamento de conduta apenas no âmbito do Conselho Federal da OAB, para fazer cessar a publicidade praticada pela advogada Carolina e pela estagiária Beatriz.","b":"É admitida a celebração do termo de ajustamento de conduta, no âmbito do Conselho Federal da OAB ou dos Conselhos Seccionais, para fazer cessar a publicidade praticada pela advogada Carolina, mas é vedado que o termo de ajustamento de conduta abranja a estagiária Beatriz.","c":"É vedada pelo Código de Ética e Disciplina da OAB a possibilidade de celebração de termo de ajustamento de conduta no caso narrado, uma vez que se trata de infração ética.","d":"É admitida a celebração do termo de ajustamento de conduta no âmbito do Conselho Federal da OAB ou dos Conselhos Seccionais, para fazer cessar a publicidade praticada pela advogada Carolina e também pela estagiária Beatriz."}', 'd', 'O art. 47-A do CED admite a celebração de termo de ajustamento de conduta no âmbito dos Conselhos Seccionais e do Conselho Federal para fazer cessar a publicidade irregular praticada por advogados e estagiários. Logo, o TAC pode abranger Carolina e Beatriz. A restringe o TAC ao Conselho Federal, B exclui a estagiária e C nega a possibilidade.'),
('2b5bfafe-f97c-47fd-a247-951a2c2b729b', 'f150410e-8056-4488-9a4d-382e3249cffe', 13, '(41º Exame de Ordem (XLI), questão 6) A advogada Marina prestou consultoria na área de Direito Tributário para uma sociedade empresária, analisando um tema importante para as funções da referida pessoa jurídica. Sobre a atividade da advogada, de acordo com o Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"A mencionada consultoria deve ser prestada exclusivamente de modo escrito e pressupõe formalização de contrato de honorários.","b":"Se a pessoa jurídica e a advogada assim acordarem, independentemente de mandato ou mesmo da formalização do contrato de honorários, é possível a prestação da consultoria por escrito ou verbalmente.","c":"Caso a consultoria seja prestada verbalmente, a concordância com essa forma deve ser expressa por ambas as partes em contrato escrito de prestação de serviços advocatícios.","d":"A consultoria prestada por Marina pode ser realizada de modo escrito ou verbalmente e, assim, o contrato de prestação de serviços advocatícios pode ser verbal ou escrito, mas é necessária a outorga de mandato."}', 'b', 'Desde a Lei 14.365/2022, o art. 5º, § 4º, do Estatuto prevê que a consultoria e a assessoria jurídicas podem ser exercidas de modo verbal ou por escrito, a critério do advogado e do cliente, e independem de outorga de mandato ou de formalização por contrato de honorários. As demais alternativas criam exigências que a lei não faz.'),
('abfcf821-83e5-4282-add5-63c7a4659c4f', 'f150410e-8056-4488-9a4d-382e3249cffe', 14, '(45º Exame de Ordem (XLV), questão 2) Helena concluiu seu mestrado em Administração Pública e acumulou significativo conhecimento jurídico, mas não possui formação em Direito nem inscrição nos quadros da OAB. Apesar disso, ela passou a oferecer consultoria jurídica e a atuar em audiências representando clientes. André, por sua vez, era advogado regularmente inscrito na OAB, porém foi suspenso do exercício profissional por prática de infração disciplinar. Mesmo suspenso, ele continuou a realizar atos privativos da advocacia, tais como peticionar e participar de audiências. Com base nessas situações hipotéticas, assinale a afirmativa correta.', '{"a":"Os atos praticados por André, após a sua suspensão da OAB, são nulos, pois ele está impedido de exercer a advocacia enquanto durar a suspensão.","b":"Os atos privativos da advocacia praticados por Helena, que não possui inscrição na OAB, são válidos, desde que seus clientes a autorizem expressamente, ratificando os atos por ela praticados.","c":"Os atos praticados por Helena são válidos, desde que restritos à consultoria extrajudicial e relacionados à administração pública, uma vez que ela não representa clientes em processos judiciais.","d":"Tanto os atos praticados por Helena quanto os atos praticados por André são anuláveis, porém sujeitos à convalidação, pois a atuação em audiências e a prática de consultoria jurídica, embora preferencialmente exercidas por advogados, podem, excepcionalmente, ser exercidas por pessoa com conhecimento jurídico."}', 'a', 'São nulos os atos privativos praticados por pessoa não inscrita (art. 4º, caput) e também os praticados por advogado suspenso (art. 4º, parágrafo único). Os atos de André, após a suspensão, são nulos. Os de Helena também seriam — por isso B, C e D, que falam em validade ou mera anulabilidade, estão erradas.'),
('fc4a78b6-bc39-4aa1-b1d6-0cc77d70588e', 'f150410e-8056-4488-9a4d-382e3249cffe', 15, '(41º Exame de Ordem (XLI), questão 8) Pedro Estrela, brasileiro, natural de Recife/PE, foi preso em flagrante por participar de esquema criminoso envolvendo pirâmides financeiras e por se apresentar como advogado, mesmo sem qualquer formação jurídica. Tendo obtido liberdade provisória, fugiu para o Equador, onde obteve graduação no curso de Direito, em faculdade local. Muitos anos depois, após ter extinta a punibilidade pelas infrações penais praticadas, decide voltar ao Brasil com a pretensão de exercer a advocacia. Quando da mudança para o Brasil, trouxe sua esposa equatoriana, Soraya, que já exercia a profissão de advogada no Equador. Considerando o enunciado acima, e a respeito da inscrição na Ordem dos Advogados do Brasil, assinale a afirmativa correta.', '{"a":"Pedro Estrela, desde que atendidos os demais requisitos para a inscrição como advogado, poderá exercer a advocacia no Brasil, independentemente de revalidação do seu diploma, diante do fato de ser brasileiro nato.","b":"Soraya não poderá exercer a profissão de advogada no Brasil, ainda que cumpra os demais requisitos para inscrição na Ordem, porque títulos de graduação obtidos em instituições estrangeiras não são aceitos para comprovação da aptidão por estrangeiros.","c":"O título de graduação obtido por Pedro em instituição estrangeira poderá ser aceito no Brasil, desde que devidamente revalidado, o que não lhe garantirá a inscrição na OAB, diante da necessidade de aprovação no Exame de Ordem, além do preenchimento dos demais requisitos legais, em especial a comprovação de idoneidade moral para a função.","d":"Pedro e Soraya poderão exercer livremente a função de advogado no Brasil, desde que sejam aprovados no Exame de Ordem, porque a aprovação nesse certame convalida os diplomas obtidos no exterior."}', 'c', 'O art. 8º, § 2º, do Estatuto exige de quem se graduou em instituição estrangeira — brasileiro ou estrangeiro — a revalidação do diploma, além dos demais requisitos: aprovação no Exame de Ordem e idoneidade moral, entre outros. Ser brasileiro nato não dispensa a revalidação (A); estrangeiro pode se inscrever se cumprir os requisitos (B); o Exame de Ordem não convalida diploma (D).'),
('e6c00da0-7c25-4f54-9a36-ac3a85c128f7', 'f150410e-8056-4488-9a4d-382e3249cffe', 16, '(38º Exame de Ordem (XXXVIII), questão 7) O advogado Alex encontra-se licenciado junto à OAB. Assinale a opção que, corretamente, apresenta uma causa para o licenciamento de Alex.', '{"a":"O requerimento de licenciamento, independentemente de motivação, formulado por Alex.","b":"O fato de Alex passar a sofrer de doença física incurável.","c":"O exercício por Alex, de forma definitiva, de atividade incompatível com a advocacia.","d":"O fato de Alex passar a sofrer de doença mental curável."}', 'd', 'O art. 12 do Estatuto prevê licença quando o advogado: (I) requerer, por motivo justificado; (II) passar a exercer, temporariamente, atividade incompatível; (III) sofrer doença mental curável. A erra ao dispensar a motivação; B fala em doença física, que não está na lei; C descreve hipótese de cancelamento (incompatibilidade definitiva).'),
('63d218fc-bf19-43de-83a0-a9ee6c2b6e6b', 'f150410e-8056-4488-9a4d-382e3249cffe', 17, '(40º Exame de Ordem (XL), questão 5) Formalizou-se, no Tribunal Regional Eleitoral do Estado Alfa, a vacância de um dos cargos de juiz eleitoral, reservado constitucionalmente à classe de advogados. De igual modo, no Tribunal Regional Federal da Enésima Região, sediado na capital do mesmo Estado Alfa, com jurisdição nos Estados Alfa, Beta e Gama, foi também formalizada a vacância de um cargo de juiz federal do Tribunal Regional Federal, destinado à advocacia nos termos da Constituição Federal (quinto constitucional). Nesse hipotético cenário, que demandará a produção de duas listas de membros da advocacia para o futuro preenchimento dos cargos, assinale a afirmativa que descreve corretamente as competências dos órgãos da OAB.', '{"a":"A lista para o preenchimento do cargo no TRE do Estado Alfa ficará sob a incumbência do Conselho Seccional da OAB do respectivo Estado, competindo ao Conselho Federal da OAB elaborar a lista para o preenchimento do cargo no TRF da Enésima Região.","b":"A lista para o preenchimento do cargo no TRE do Estado Alfa ficará sob a incumbência do Conselho Seccional da OAB do respectivo Estado, competindo aos Conselhos Seccionais da OAB dos Estados Alfa, Beta e Gama a elaboração conjunta da lista para o preenchimento do cargo no TRF da Enésima Região.","c":"Uma vez que tanto a Justiça Eleitoral quanto a Justiça Federal pertencem ao Poder Judiciário da União, competirá ao Conselho Federal da OAB a elaboração das duas listas.","d":"Uma vez que tanto o TRE do Estado Alfa quanto a sede do TRF da Enésima Região estão situados no Estado Alfa, competirá ao Conselho Seccional da OAB desse Estado a elaboração das duas listas."}', 'a', 'Pelo art. 58, XIV, compete ao Conselho Seccional elaborar as listas para os tribunais no âmbito de sua competência — caso do TRE do próprio Estado. Já o art. 54, XIII, dá ao Conselho Federal as listas para tribunais de âmbito nacional ou interestadual — caso do TRF com jurisdição em três Estados.'),
('4f0e532b-34c7-47ff-a880-2f2c3d6e7c86', 'f150410e-8056-4488-9a4d-382e3249cffe', 18, '(35º Exame de Ordem (XXXV), questão 6) O advogado Cauã Silva foi presidente de certo Conselho Seccional da OAB, tendo seu mandato se encerrado há mais de uma década. Desde então, embora tenha permanecido como aguerrido defensor das prerrogativas e dos direitos dos advogados, Cauã não mais concorreu a nenhum cargo na OAB. Considerando a situação hipotética narrada, assinale a afirmativa correta.', '{"a":"Cauã, quando cessado seu mandato, deixou de integrar o Conselho Seccional da OAB.","b":"Cauã permanece como membro honorário do Conselho Seccional da OAB, mas não tem direito de voto ou de voz nas sessões.","c":"Cauã é ainda membro honorário do Conselho Seccional da OAB e o será de forma vitalícia, tendo, contudo, apenas direito de voz nas sessões.","d":"Cauã permanece como membro honorário do Conselho Seccional da OAB, a quem são conferidos os direitos a voz e voto nas sessões do Conselho."}', 'c', 'O art. 56, § 1º, do Estatuto estabelece que os ex-presidentes do Conselho Seccional são membros honorários vitalícios, somente com direito a voz em suas sessões. Cauã continua integrando o Conselho nessa condição, sem voto.'),
('90baec37-b15b-4ad6-976f-51b270d1b4f7', 'f150410e-8056-4488-9a4d-382e3249cffe', 19, '(44º Exame de Ordem (XLIV), questão 8) Euclides é advogado regularmente inscrito na OAB e foi flagrado praticando assédio sexual contra diversas colaboradoras de seu escritório, conduta que foi amplamente divulgada na imprensa regional após a veiculação de imagens captadas por câmeras de segurança, nas quais o advogado aparece se insinuando de forma inapropriada. O caso causou grande repercussão regional, afetando a imagem da Advocacia. Diante disso, o Tribunal de Ética e Disciplina do Conselho Seccional determinou a suspensão preventiva de Euclides, designando sessão especial para ouvi-lo na semana seguinte à suspensão. No mesmo ato, o Tribunal estabeleceu que o processo disciplinar deveria ser concluído em prazo máximo de 180 dias. Com base no Estatuto da Advocacia e da OAB, sobre a decisão do Tribunal, assinale a afirmativa correta.', '{"a":"O procedimento adotado foi regular, pois diante da gravidade dos fatos e da ampla repercussão, o Tribunal de Ética pode suspender preventivamente o advogado e prorrogar o prazo do processo disciplinar para até 180 dias.","b":"O procedimento adotado foi válido apenas quanto à suspensão, pois o Estatuto admite a suspensão preventiva sem qualquer necessidade de notificação ou sessão de oitiva, desde que haja repercussão negativa à imagem da OAB.","c":"O procedimento foi irregular, porque a suspensão preventiva do advogado somente é válida se o representado for previamente notificado ou, depois de notificado, não comparecer, e o prazo máximo do processo, na hipótese, é de 90 dias.","d":"O procedimento adotado foi regular quanto ao prazo máximo de duração do processo disciplinar, mas irregular quanto à suspensão preventiva, pois, embora seja cabível, a oitiva do advogado deve ocorrer antes da suspensão, e não posteriormente."}', 'c', 'Pelo art. 70, § 3º, do Estatuto, a suspensão preventiva é decidida pelo TED depois de ouvir o advogado em sessão especial para a qual ele deve ser notificado (salvo se não atender à notificação), e o processo deve ser concluído em no máximo 90 dias. O TED suspendeu antes de ouvir Euclides e fixou 180 dias: duas irregularidades.'),
('2c80411b-96c4-4e40-8d39-d3e7fd2a5208', 'f150410e-8056-4488-9a4d-382e3249cffe', 20, '(44º Exame de Ordem (XLIV), questão 4) O Presidente do Conselho Seccional da Ordem dos Advogados do Brasil do Estado Alfa recebeu representação devidamente identificada, contendo narrativa fática indicativa da prática de infração disciplinar pelo advogado Paulo. O autor da representação apresentou documentos, rol de testemunhas e indicou a produção de provas. Ato contínuo, o Presidente imediatamente designou relator para a competente instrução do processo disciplinar. Considerando a legislação que rege o processo disciplinar do advogado, assinale a afirmativa correta.', '{"a":"Se a infração ético-disciplinar apontada na representação for punível com a sanção de censura, será admissível a celebração de termo de ajustamento de conduta, desde que o fato apurado não tenha gerado repercussão negativa à advocacia.","b":"A autoridade competente que proferir o despacho declaratório da instauração do processo disciplinar deverá, no mesmo ato, promover a suspensão preventiva de Paulo pelo prazo de até 90 (noventa) dias.","c":"Na hipótese de arquivamento liminar da representação pelo Presidente do Conselho Seccional, caberá recurso ao Conselho Federal da OAB.","d":"A designação imediata de relator pelo Presidente do Conselho Seccional, sem a prévia oitiva de Paulo, viola o princípio da ampla defesa."}', 'a', 'O art. 58-A do CED admite termo de ajustamento de conduta nas infrações puníveis com censura, desde que o fato não tenha gerado repercussão negativa à advocacia. A suspensão preventiva não é automática (B); contra decisão do Presidente da Seccional o recurso vai ao próprio Conselho Seccional, e não ao Conselho Federal (art. 76 — C); e a designação de relator antes da defesa não viola a ampla defesa, que é exercida depois (D).'),
('23c63380-63d8-438b-911d-f8793b7a2177', 'f150410e-8056-4488-9a4d-382e3249cffe', 21, '(46º Exame de Ordem (XLVI), questão 2) Danilo, procurador de carreira, foi nomeado Procurador-Geral de sua instituição. Antes de assumir a Procuradoria-Geral do Estado, ele patrocinava várias causas trabalhistas contra empresas privadas e causas tributárias. Agora, Danilo está em dúvida se poderá continuar advogando nessas ações. Sobre a hipótese apresentada, com base nas disposições do Estatuto da OAB sobre incompatibilidades e impedimentos, assinale a afirmativa correta.', '{"a":"Danilo está impedido de atuar em causas trabalhistas e tributárias contra a Fazenda Pública que o remunera, mas pode continuar patrocinando as causas contra empresas privadas.","b":"Danilo poderá continuar patrocinando suas causas trabalhistas e tributárias, pois o cargo de Procurador-Geral do Estado não gera incompatibilidade ou impedimento para advogar em questões privadas.","c":"Danilo poderá continuar patrocinando as causas tributárias, mas não as trabalhistas, pois apenas as causas tributárias contra a Fazenda Pública estão abrangidas pelo impedimento previsto no Estatuto da OAB.","d":"Danilo não poderá continuar patrocinando suas causas trabalhistas e tributárias, pois o cargo de Procurador-Geral do Estado obsta o exercício da advocacia desvinculado da função que exerce, durante o período da investidura."}', 'd', 'O art. 29 do Estatuto torna os Procuradores-Gerais exclusivamente legitimados para a advocacia vinculada à função que exercem, durante o período da investidura. Danilo não pode continuar com as causas particulares, trabalhistas ou tributárias. A trata a situação como mero impedimento; B e C permitem atuação privada.'),
('a9855b0e-d703-4aa8-af44-12012883dad1', 'f150410e-8056-4488-9a4d-382e3249cffe', 22, '(45º Exame de Ordem (XLV), questão 3) Tarcísio, advogado trabalhista com mais de 20 anos de experiência, prestou concurso público para a Outorga de Delegações de Serventias Notariais e Registrais e, após aprovação, assumiu um Tabelionato de Notas e Ofício de Registro Civil em uma comarca do mesmo Estado. Ele deseja saber se poderá continuar exercendo a advocacia em causa própria e, além disso, pretende patrocinar uma ação contra a empresa pública estadual responsável pelo fornecimento de água. Sobre incompatibilidades e impedimentos, com base nas disposições do Estatuto da OAB, assinale a afirmativa correta.', '{"a":"Tarcísio poderá exercer a advocacia apenas em causa própria, conforme prevê o Estatuto da OAB, mas estará impedido de advogar contra a empresa pública estadual de fornecimento de água.","b":"Tarcísio poderá advogar livremente, inclusive contra a empresa pública estadual de fornecimento de água, uma vez que o exercício da atividade notarial não gera impedimento para o exercício da advocacia.","c":"Tarcísio está em situação de incompatibilidade total com o exercício da advocacia, sendo vedada a atuação em qualquer causa, inclusive em causa própria, em razão de seu cargo como titular de serventia notarial e registral.","d":"Tarcísio poderá continuar exercendo a advocacia, desde que em causas particulares que não envolvam empresas públicas ou concessionárias de serviço público, estando livre de impedimentos em ações de interesse pessoal."}', 'c', 'Quem exerce serviços notariais e de registro está em situação de incompatibilidade (art. 28, IV), que é proibição total do exercício da advocacia, mesmo em causa própria. As alternativas que liberam a causa própria (A) ou certas causas (B e D) estão erradas.'),
('2fc3ee6b-5a2d-41de-8996-fd0e45312865', 'f150410e-8056-4488-9a4d-382e3249cffe', 23, '(46º Exame de Ordem (XLVI), questão 3) Alfredo é graduado em Direito pela Universidade Beta, mas não foi aprovado no Exame da Ordem dos Advogados do Brasil (OAB). Durante a graduação, Alfredo não teve a oportunidade de estagiar em um escritório de advocacia. Recentemente, após já estar formado, surgiu a oportunidade de estagiar em um escritório credenciado pelo Conselho Seccional da OAB. Ele deseja saber se pode participar do estágio profissional de advocacia mesmo após a conclusão de seu curso e se seria possível inscrever-se no quadro de estagiários da OAB. Sobre a hipótese, com base no disposto no Art. 9º do Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"Alfredo não pode participar de estágio de advocacia, pois o estágio só é permitido para estudantes de Direito que ainda estejam cursando os últimos anos do curso jurídico.","b":"Alfredo pode se inscrever no quadro de estagiários da OAB, mas somente se concluir o estágio profissional em uma instituição de ensino superior, e não em escritório credenciado pelo Conselho Seccional da OAB.","c":"Alfredo pode participar do estágio profissional de advocacia e inscrever-se como estagiário da OAB, mesmo após a conclusão do curso, desde que o estágio seja realizado em escritório credenciado pela OAB.","d":"Alfredo pode participar do estágio profissional, mas não poderá inscrever-se no quadro de estagiários da OAB, pois já concluiu a graduação em Direito e apenas alunos ainda cursando o ensino jurídico podem obter essa inscrição."}', 'c', 'O art. 9º, § 4º, do Estatuto permite que o estágio profissional seja cumprido por bacharel em Direito que queira se inscrever na Ordem, e o § 1º admite estágio em escritórios credenciados pela OAB. Alfredo pode estagiar e se inscrever como estagiário.'),
('71d92d98-a5c8-40e6-87c8-fa17a597890f', 'f150410e-8056-4488-9a4d-382e3249cffe', 24, '(35º Exame de Ordem (XXXV), questão 5) João é estagiário de Direito. É vedado a João praticar isoladamente – isto é, sem atuar em conjunto com o advogado ou o defensor público que o supervisiona – o seguinte ato:', '{"a":"assinar petições de juntada de documentos a processos judiciais.","b":"obter junto aos escrivães e chefes de secretarias certidões de peças de processos em curso.","c":"comparecer à prática de atos extrajudiciais, sem autorização ou substabelecimento do advogado.","d":"retirar e devolver autos em cartório, assinando a respectiva carga."}', 'c', 'O RG (art. 29, § 1º) permite ao estagiário, isoladamente: retirar e devolver autos assinando a carga (D), obter certidões (B) e assinar petições de juntada de documentos (A). Já o comparecimento a atos extrajudiciais só pode ocorrer isoladamente com autorização ou substabelecimento do advogado (§ 2º).'),
('8901761c-62ab-42d9-a874-0218af422d83', 'f150410e-8056-4488-9a4d-382e3249cffe', 25, '(45º Exame de Ordem (XLV), questão 6) Durante muitos anos, João representou Pedro, na condição de seu advogado, em diversas causas. Recentemente, após encerrados todos os vínculos contratuais existentes entre si, Pedro passou a ser investigado pelo suposto cometimento de ilícitos tributários. Sobre esse contexto, de acordo com o Estatuto da Ordem e com o Código de Ética e Disciplina da Ordem dos Advogados do Brasil, assinale a afirmativa correta.', '{"a":"João não poderá ser obrigado a depor como testemunha no curso de eventual processo judicial em face de Pedro, ainda que este expressamente o autorize ou solicite o depoimento do ex-advogado.","b":"João não poderá ser obrigado a depor como testemunha no curso de eventual processo judicial em face de Pedro, exceto se este expressamente o autorizar, ou no caso de solicitação do próprio ex-constituinte.","c":"João poderá ser obrigado a depor sobre fatos que constituam sigilo profissional caso seu depoimento seja considerado imprescindível para a instrução em processos criminais que apurem a prática de crimes dolosos contra a vida.","d":"Considerando que a investigação se iniciou após a extinção da relação profissional existente entre João e Pedro, não há qualquer prerrogativa em favor de João que o escuse da obrigação de depor como testemunha no curso de processo judicial sobre fato relacionado com pessoa de quem já foi advogado."}', 'a', 'O art. 7º, XIX, do Estatuto assegura ao advogado o direito de recusar-se a depor como testemunha sobre fato relacionado com pessoa de quem seja ou foi advogado, mesmo quando autorizado ou solicitado pelo constituinte; o art. 38 do CED reforça. O fim do vínculo não elimina a prerrogativa (D), e não há exceção para crimes dolosos contra a vida (C).'),
('66de4afb-4f49-4bce-ade7-c71d9353b0b2', 'f150410e-8056-4488-9a4d-382e3249cffe', 26, '(42º Exame de Ordem (XLII), questão 4) A advogada Nina exerce função na diretoria do Conselho Federal da OAB. Em virtude exclusivamente das funções desempenhadas na OAB, Nina toma conhecimento de certos fatos envolvendo seus colegas advogados João e Maria. Nina acaba de receber uma intimação para depor como testemunha em audiência de instrução e julgamento, referente a uma ação indenizatória, de cunho meramente patrimonial, sem envolver grave ameaça ao direito à vida e à honra, ajuizada por Maria em face de João, cujo objeto tem relação com mencionados fatos de que tomou conhecimento no exercício da citada função no Conselho Federal da OAB Considerando a situação hipotética, assinale a afirmativa correta.', '{"a":"Nina não deve depor sobre os fatos que soube, diante do sigilo profissional.","b":"Nina não poderá alegar sigilo profissional em razão da natureza das funções exercidas no Conselho Federal da OAB.","c":"Nina deverá relatar os fatos sobre os quais tomou conhecimento, pois se trata de ação indenizatória, de cunho meramente patrimonial.","d":"Nina tem o dever legal de permanecer em silêncio sobre os fatos indagados, salvo em circunstâncias excepcionais, tais como a defesa judicial de familiares e amigos íntimos."}', 'a', 'O sigilo profissional abrange os fatos que o advogado conheceu em razão de funções desempenhadas na OAB (CED, art. 35, parágrafo único), e ele não é obrigado a depor sobre fatos sigilosos (art. 38). A causa é meramente patrimonial e não envolve grave ameaça à vida ou à honra, então não há justa causa para quebrar o sigilo.'),
('42891dda-382e-4857-89ff-18bea5ecce55', 'f150410e-8056-4488-9a4d-382e3249cffe', 27, '(41º Exame de Ordem (XLI), questão 3) O empresário João Pedro, movido pelo sentimento de vingança, contrata o advogado Beraldo para propor ação de cobrança contra seu ex-sócio Marcos, apresentando frágeis documentos que comprovariam uma suposta dívida. A ação foi proposta e, concedida medida cautelar pelo juiz da causa, gerou diversos danos a Marcos, a partir da indisponibilidade de seus bens e do bloqueio de todos os seus ativos bancários initio litis. Ao final, porém, o pedido foi julgado totalmente improcedente, sendo expressamente reconhecida a lide temerária. Acerca da responsabilidade do advogado nessa hipotética situação, assinale a afirmativa correta.', '{"a":"Beraldo poderá ser responsabilizado subsidiariamente pelos prejuízos causados, caso demonstrada culpa ou dolo no exercício da profissão, o que deverá ser apurado nos próprios autos.","b":"Beraldo e João Pedro poderão ser responsabilizados solidariamente pelos prejuízos causados, desde que demonstrada a coligação entre ambos para lesar Marcos, o que deverá ser apurado em ação própria.","c":"Beraldo não poderá ser responsabilizado pelos prejuízos causados, pois o Estatuto da Advocacia e da OAB não prevê consequência jurídica para a hipótese de lide temerária.","d":"Beraldo poderá ser responsabilizado solidariamente pelos prejuízos causados, desde que seja demonstrada a coligação com João Pedro para lesar Marcos, o que deverá ser apurado nos próprios autos."}', 'b', 'O art. 32, parágrafo único, do Estatuto estabelece que, em caso de lide temerária, o advogado é solidariamente responsável com o cliente desde que coligado com ele para lesar a parte contrária, o que é apurado em ação própria. A fala em responsabilidade subsidiária; C nega a consequência prevista em lei; D manda apurar nos próprios autos.'),
('31043476-efdb-4f8f-8e0e-14827f853d03', 'f150410e-8056-4488-9a4d-382e3249cffe', 28, '(QUESTÃO INÉDITA NO ESTILO FGV) Carla é advogada empregada do departamento jurídico da sociedade empresária Beta. Anos atrás, a pedido da própria empresa, emitiu parecer concluindo pela ilegalidade de determinada cláusula contratual. Agora, a empresa pede que Carla ajuíze ação defendendo exatamente a validade dessa cláusula. Carla consulta você sobre a possibilidade de recusar o patrocínio. Assinale a afirmativa correta.', '{"a":"Carla não pode recusar o patrocínio, pois o advogado empregado deve seguir as orientações do empregador em todas as causas da empresa.","b":"Carla pode recusar o patrocínio, pois é legítima a recusa de causa que contrarie orientação que ela tenha manifestado anteriormente.","c":"Carla só pode recusar o patrocínio se renunciar ao emprego, já que a relação empregatícia retira a independência do advogado.","d":"Carla pode recusar o patrocínio apenas se a ação envolver direito que também lhe seja aplicável."}', 'b', 'O CED, art. 4º, parágrafo único, torna legítima a recusa de causa ou manifestação que contrarie orientação que o advogado tenha manifestado anteriormente — e também, em outra hipótese, a de direito que lhe seja aplicável. A relação de emprego não retira a independência (EAOAB, art. 18). D erra ao limitar a recusa a uma só das hipóteses.'),
('61802740-7095-476c-b4cf-dbf77ebf0c6f', 'f150410e-8056-4488-9a4d-382e3249cffe', 29, '(42º Exame de Ordem (XLII), questão 6) José Fabiano, advogado recém-inscrito na OAB, com dois anos e seis meses de exercício da profissão, decidiu se candidatar para o cargo de Conselheiro Seccional da Ordem. Durante o procedimento de verificação da regularidade de sua candidatura, observou-se que ele havia sido condenado pela prática da infração disciplinar de abandonar a causa sem justo motivo ou antes de decorridos dez dias da comunicação da renúncia, tendo-lhe sido imposta sanção de censura, sem que tenha ocorrido, até o momento da eleição, sua reabilitação. Com base nessa situação hipotética e considerando as eleições da OAB, assinale a afirmativa correta.', '{"a":"José Fabiano somente poderá participar da eleição caso não haja outros candidatos dispostos a concorrer para o cargo, hipótese na qual as condições de elegibilidade são flexibilizadas para que a posição não fique vaga.","b":"José Fabiano não poderá participar da eleição corrente, porque ainda não completou o prazo de três anos de efetivo exercício profissional da advocacia e por ter sido apenado com sanção disciplinar, sem que tenha sucedido reabilitação.","c":"José Fabiano poderá participar da eleição e concorrer ao cargo de Conselheiro Seccional da OAB, porque exerce a profissão de advogado há mais de um ano e foi condenado por infração disciplinar leve, para a qual está prevista apenas a pena de censura.","d":"José Fabiano não poderá participar da eleição corrente e de futuras, porque, uma vez apenado com sanção disciplinar, o advogado não mais poderá recuperar sua condição de elegibilidade, estando impedido, indefinidamente, de se candidatar a cargos na OAB."}', 'b', 'O art. 63, § 2º, exige para Conselheiro Seccional exercício efetivo da profissão há mais de 3 anos e ausência de condenação disciplinar, salvo reabilitação. José tem 2 anos e 6 meses de exercício e uma censura sem reabilitação: está inelegível. Não há flexibilização por falta de candidatos (A); a censura também conta (C); e a reabilitação devolve a elegibilidade (D).'),
('076a1a11-32d9-4d56-a7e9-81764d0bea5c', 'f150410e-8056-4488-9a4d-382e3249cffe', 30, '(QUESTÃO INÉDITA NO ESTILO FGV) Mariana, conselheira seccional eleita, foi nomeada para cargo de direção em autarquia estadual, com poder de decisão relevante sobre interesses de terceiros. Sobre o mandato de Mariana no Conselho Seccional, assinale a afirmativa correta.', '{"a":"O mandato fica suspenso enquanto Mariana exercer o cargo, retomando-se quando ela deixar a autarquia.","b":"O mandato se extingue automaticamente, pois o exercício de atividade incompatível gera o licenciamento ou o cancelamento da inscrição.","c":"O mandato só se extingue se Mariana faltar a três reuniões ordinárias consecutivas sem justificativa.","d":"O mandato continua válido, pois a incompatibilidade atinge apenas o exercício da advocacia, e não os cargos na OAB."}', 'b', 'Cargo de direção na Administração indireta com poder de decisão relevante é incompatível com a advocacia (EAOAB, art. 28, III), o que leva ao licenciamento (se temporário) ou ao cancelamento (se definitivo) da inscrição. O art. 66, I, prevê a extinção automática do mandato em qualquer hipótese de cancelamento ou licenciamento.'),
('df7270f1-83df-4f6d-bb9b-a6cc27aea1e9', 'f150410e-8056-4488-9a4d-382e3249cffe', 31, '(45º Exame de Ordem (XLV), questão 4) A advogada Jéssica foi contratada pela sociedade empresária de telefonia Alfa para trabalhar 10 horas contínuas por dia, de segunda a quinta-feira, totalizando 40 horas semanais. Além disso, o contrato escrito firmado entre Jéssica e a sociedade empresária prevê que, em situações excepcionais, ela deverá trabalhar horas extras, sendo remunerada com um adicional de 50% sobre o valor da hora normal. Jéssica questiona a validade dessas condições contratuais, especialmente em relação à duração da jornada de trabalho e à remuneração das horas extras. Com base no Art. 20 do Estatuto da Advocacia e da OAB, assinale a afirmativa correta.', '{"a":"O contrato de Jéssica é válido, pois a jornada semanal não ultrapassa 40 horas, e as horas extras podem ser remuneradas com um adicional de 50% conforme estipulado no contrato.","b":"A sociedade empresária está correta ao fixar 10 horas de trabalho por dia, desde que Jéssica cumpra apenas quatro dias de trabalho por semana, sem a necessidade de pagamento de horas extras.","c":"O contrato de Jéssica é inválido, pois a jornada diária não pode exceder 8 horas contínuas, e as horas extras devem ser remuneradas com um adicional de 100%, conforme previsto no Estatuto da OAB, independentemente do contrato firmado.","d":"A sociedade empresária está agindo corretamente, pois Jéssica pode trabalhar até 10 horas por dia desde que sua jornada semanal não ultrapasse 40 horas, mas a remuneração das horas extras deveria ser de 100% sobre o valor da hora normal, independentemente do contrato escrito."}', 'c', 'O art. 20 do Estatuto limita a jornada do advogado empregado que presta serviço para empresas a 8 horas contínuas diárias e 40 semanais, e o § 2º fixa adicional não inferior a 100% para as horas extras, mesmo havendo contrato escrito. O contrato de Jéssica viola as duas regras.'),
('26950a97-9edb-496b-b886-d8bdcece7a5c', 'f150410e-8056-4488-9a4d-382e3249cffe', 32, '(41º Exame de Ordem (XLI), questão 5) Gilson, advogado recém inscrito nos quadros da Ordem dos Advogados do Brasil, estava em dúvida entre constituir sociedade unipessoal de advocacia, o que, em seu entender, lhe traria maior autonomia e liberdade, ou aceitar a proposta recebida da sociedade empresária XYZ, para atuar como advogado empregado em regime de dedicação exclusiva. Após estudar a legislação correlata, Gilson aceitou a proposta de emprego da sociedade empresária XYZ. Acerca desse vínculo contratual, de acordo com o texto legal do Estatuto da Advocacia, assinale a afirmativa correta.', '{"a":"Nas causas em que Gilson atuar como advogado empregado da empresa XYZ, ou de pessoa por esta representada, os honorários de sucumbência lhe pertencerão.","b":"Gilson estará eticamente obrigado a prestar serviços profissionais de interesse pessoal dos diretores da sociedade empresária XYZ.","c":"A jornada de trabalho de Gilson não poderá exceder a duração diária de 4 (quatro) horas contínuas e a de 20 (vinte) horas semanais.","d":"Em virtude da dedicação exclusiva, Gilson não poderá ser remunerado pelas horas trabalhadas excedentes à jornada normal prevista na legislação."}', 'a', 'Pelo art. 21 do Estatuto, nas causas em que for parte o empregador, ou pessoa por ele representada, os honorários de sucumbência são devidos aos advogados empregados. B contraria o art. 18, § 1º; C traz a jornada antiga (4h/20h); D nega o pagamento de horas extras, que é devido.'),
('15d21d52-1a09-4044-aad3-6d1496157547', 'f150410e-8056-4488-9a4d-382e3249cffe', 33, '(36º Exame de Ordem (XXXVI), questão 6) A diretoria de certa subseção da OAB emitiu decisão no âmbito de suas atribuições. Irresignados, os interessados desejavam manejar recurso em face de tal decisão. Sobre a hipótese, assinale a afirmativa correta.', '{"a":"A competência privativa para julgar, em grau de recurso, questão decidida pela diretoria da subseção é do Conselho Federal da OAB.","b":"A competência privativa para julgar, em grau de recurso, questão decidida pela diretoria da subseção é do Presidente do Conselho Seccional respectivo da OAB.","c":"A competência privativa para julgar, em grau de recurso, questão decidida pela diretoria da subseção é do Conselho Seccional respectivo da OAB.","d":"A decisão proferida pela diretoria da subseção é irrecorrível."}', 'c', 'O art. 76 do Estatuto prevê recurso ao Conselho Seccional contra as decisões da diretoria da Subseção, e o art. 58, III, confirma que compete privativamente ao Conselho Seccional julgar esses recursos.'),
('7679327f-24ed-4203-94c5-916a928a5e69', 'f150410e-8056-4488-9a4d-382e3249cffe', 34, '(37º Exame de Ordem (XXXVII), questão 1) Foi instaurado processo disciplinar em face do advogado Nino, tendo em vista possível prática de infração disciplinar. No que se refere às notificações de Nino no mencionado feito, assinale a afirmativa correta.', '{"a":"A notificação inicial de Nino para apresentação de defesa prévia deverá ser feita pessoalmente, de forma preferencial, admitindo-se a notificação por correspondência com aviso de recebimento apenas em hipóteses excepcionais, previstas no Regulamento Geral do Estatuto da Advocacia e da OAB.","b":"Na hipótese de a notificação inicial para apresentação de defesa prévia ser realizada por edital, deve constar do edital apenas o nome completo de Nino, o seu número de inscrição e a menção de que a notificação destina-se à apresentação da defesa prévia no feito disciplinar no prazo legal.","c":"As notificações realizadas no referido processo disicplinar que forem feitas através de edital, com exceção da notificação inicial, deverão indicar o nome completo de Nino e o do advogado constituído para sua defesa, salvo na hipótese de atuação em causa própria.","d":"Há presunção de recebimento das notificações enviadas por correspondência com aviso de recebimento ao endereço residencial ou ao endereço profissional que constam no cadastro de Nino junto ao Conselho Seccional."}', 'd', 'O Regulamento Geral (art. 137-D) estabelece a presunção de recebimento das notificações enviadas por correspondência com aviso de recebimento ao endereço residencial ou profissional constante do cadastro do advogado na Seccional. As demais alternativas alteram a forma preferencial da notificação ou o conteúdo exigido do edital.'),
('8f787831-12b6-4048-88b5-d40544a6f532', 'f150410e-8056-4488-9a4d-382e3249cffe', 35, '(38º Exame de Ordem (XXXVIII), questão 3) O advogado Luís Santos, regularmente inscrito na OAB, está em início de carreira. Luís presta serviços jurídicos a determinada instituição social sem fins econômicos, consistentes em patrocinar seus interesses em demanda judicial em curso. Sobre a atuação de Luís, assinale a afirmativa correta.', '{"a":"Não poderá ser considerada advocacia pro bono a atuação gratuita de Luís como advogado das pessoas naturais, hipossuficientes econômicas, beneficiárias da instituição social.","b":"É ilícito que Luís preste gratuitamente tais serviços jurídicos, se o objetivo é valer-se de sua atuação como instrumento de publicidade da sua atividade profissional.","c":"A atuação gratuita de Luís, ainda que não seja eventual, na defesa em Juízo da mencionada instituição social, pode ser considerada advocacia pro bono.","d":"É admitida a prestação por Luís, sob a forma de advocacia pro bono voluntária, de serviços jurídicos para uma instituição social cobrando preços simbólicos, haja vista a ausência de fins econômicos."}', 'b', 'O art. 30, § 3º, do CED proíbe que a advocacia pro bono seja utilizada como instrumento de publicidade para captação de clientela. A e C erram no conceito: os assistidos da instituição podem ser atendidos (A), e a atividade deve ser eventual (C). D erra porque pro bono é gratuito.'),
('8a41cfee-d773-4185-9ac5-769cefb634be', 'f150410e-8056-4488-9a4d-382e3249cffe', 36, '(QUESTÃO INÉDITA NO ESTILO FGV) O advogado Rui, pré-candidato a vereador, pretende oferecer atendimento jurídico gratuito semanal à associação de moradores de seu bairro, entidade sem fins econômicos, divulgando a iniciativa em suas redes sociais. Sobre a situação, assinale a afirmativa correta.', '{"a":"A conduta é permitida, pois a associação não tem fins econômicos e os serviços seriam gratuitos.","b":"A conduta é vedada, pois a advocacia pro bono não pode ser utilizada para fins político-partidários ou eleitorais.","c":"A conduta é permitida, desde que Rui não cobre honorários de sucumbência nas causas patrocinadas.","d":"A conduta é vedada apenas porque a advocacia pro bono só pode beneficiar pessoas naturais."}', 'b', 'O CED, art. 30, § 3º, veda o uso da advocacia pro bono para fins político-partidários ou eleitorais e como instrumento de publicidade. Além disso, o atendimento semanal contraria o caráter eventual do § 1º. D erra porque instituições sociais sem fins econômicos podem ser beneficiadas.'),
('4e393435-bc88-44ce-bc42-993ecaf0b3ad', 'f150410e-8056-4488-9a4d-382e3249cffe', 37, '(QUESTÃO INÉDITA NO ESTILO FGV) Lúcia foi aprovada em concurso e tomou posse como procuradora do Município Alfa. Sobre sua situação perante a OAB, assinale a afirmativa correta.', '{"a":"Lúcia não precisa manter inscrição na OAB, pois sua atuação decorre do cargo público.","b":"Lúcia exerce advocacia, sujeita-se ao Estatuto da OAB e ao regime próprio do cargo, e deve manter inscrição na OAB.","c":"Lúcia fica sujeita apenas ao regime próprio do cargo, e não ao Código de Ética e Disciplina da OAB.","d":"Lúcia não poderá se candidatar a cargos nos órgãos da OAB enquanto exercer a função pública."}', 'b', 'Pelo EAOAB, art. 3º, § 1º, os integrantes das procuradorias municipais exercem atividade de advocacia e se sujeitam ao Estatuto, além do regime próprio; por isso devem estar inscritos. O STF confirmou essa obrigatoriedade no Tema 936 (2026). O RG (art. 9º, parágrafo único) diz que são elegíveis e podem integrar qualquer órgão da OAB. C erra porque o CED também os obriga (art. 8º); o STF apenas atribuiu à corregedoria do órgão o poder disciplinar sobre a atuação funcional.'),
('3a31fd40-a697-4ffa-9adb-b9f48c3b9427', 'f150410e-8056-4488-9a4d-382e3249cffe', 38, '(QUESTÃO INÉDITA NO ESTILO FGV) Pedro é defensor público estadual e nunca foi inscrito na OAB. Uma parte contrária alega nulidade dos atos por ele praticados em juízo, por ausência de inscrição. À luz da jurisprudência do Supremo Tribunal Federal, assinale a afirmativa correta.', '{"a":"Os atos são nulos, pois o Estatuto da OAB exige a inscrição de todos os integrantes da Defensoria Pública.","b":"Os atos são anuláveis e podem ser ratificados por advogado inscrito.","c":"Os atos são válidos, pois a capacidade postulatória do defensor público decorre de sua nomeação e posse no cargo.","d":"Os atos são válidos apenas se praticados em favor de pessoas hipossuficientes na Justiça do Trabalho."}', 'c', 'No julgamento da ADI 4.636, o STF deu interpretação conforme ao art. 3º, § 1º, do Estatuto para afastar a exigência de inscrição na OAB para os defensores públicos, cuja capacidade postulatória decorre da nomeação e posse no cargo.'),
('df11aed9-19dc-4145-a0d9-7c1e1bf117f4', 'f150410e-8056-4488-9a4d-382e3249cffe', 39, '(37º Exame de Ordem (XXXVII), questão 8) A advogada Maria integra a Comissão de Defesa do Consumidor de certa Seccional da OAB, promovendo debates e a qualificação profissional de colegas sobre temas específicos de Direito do Consumidor. Sobre a atuação de Maria, enquanto integrar a comissão, assinale a afirmativa correta.', '{"a":"Maria poderá firmar contrato gratuito de prestação de serviços com entidades da OAB.","b":"Maria é impedida de adquirir bens móveis fungíveis de entidades da OAB.","c":"Maria poderá alienar bens móveis infungíveis para entidades da OAB.","d":"Maria poderá adquirir bens imóveis de entidades da OAB."}', 'a', 'O art. 32 do CED veda contratos onerosos com instituições da OAB, bem como adquirir bens imóveis ou móveis infungíveis de seus órgãos ou aliená-los a eles. Contrato gratuito de prestação de serviços é permitido.'),
('be8018af-8162-42ab-98e6-b4d645c97e20', 'f150410e-8056-4488-9a4d-382e3249cffe', 40, '(QUESTÃO INÉDITA NO ESTILO FGV) Ricardo é conselheiro seccional da OAB. Um colega, representado disciplinarmente, pede que Ricardo assuma sua defesa no processo que tramita no Tribunal de Ética e Disciplina da mesma Seccional. Assinale a afirmativa correta.', '{"a":"Ricardo pode aceitar, desde que se declare impedido de votar no julgamento.","b":"Ricardo pode aceitar, pois o processo tramita no TED, órgão distinto do Conselho Seccional.","c":"Ricardo não pode aceitar, pois, salvo em causa própria, quem tem assento nos Conselhos da OAB não pode atuar em processos que tramitem perante a entidade.","d":"Ricardo pode aceitar, desde que atue gratuitamente."}', 'c', 'O CED, art. 33, proíbe o advogado que exerce cargo ou tem assento nos Conselhos da OAB de atuar em processos que tramitem perante a entidade — incluindo os disciplinares no TED — ressalvada a atuação em causa própria.');--> statement-breakpoint
