INSERT INTO `flashcards` (`id`, `front`, `back`, `subject_id`, `training_id`, `difficulty`) VALUES
('9cbb1205-bbd0-4132-a2ab-d048c48e4d5a', 'Certo ou errado? "Autos sigilosos podem ser vistos sem procuração"', 'Errado. Sigilo exige procuração.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('681a10ae-3961-4ebf-8a25-60bb8bd6644f', 'Certo ou errado? "A autoridade pode negar acesso a diligências já documentadas"', 'Errado. Só as em andamento e ainda não documentadas.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('66337b08-237f-42fa-b7da-cae34bdee0aa', 'Certo ou errado? "O desagravo depende de pedido do ofendido" ou "o ofendido pode dispensá-lo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('3029eb2f-7a4a-4738-89e9-7183ba865593', 'Certo ou errado? "Advogado preso por briga de trânsito exige representante da OAB"', 'Errado. Basta comunicar a Seccional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('babd253b-dce5-4d84-a585-c6ca4e1c3d65', 'Certo ou errado? "Sala de Estado-Maior após a condenação definitiva"', 'Errado. Só antes do trânsito em julgado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('c7e6f38e-b31f-4937-8e6d-613b340926a2', 'Certo ou errado? "Vaga em garagem só em tribunais federais/superiores"', 'Errado. Vale para os fóruns dos tribunais em geral.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('df30e367-d572-49aa-91ec-3c10721c0cd6', 'Certo ou errado? "Imunidade cobre calúnia/desacato"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('41592285-a212-4dd3-8875-dba08e922650', 'Certo ou errado? "Pode retirar-se após 30 minutos mesmo que a autoridade já tenha comparecido e o ato esteja em andamento"', 'Errado. O direito só existe se a autoridade que preside o ato ainda não compareceu a ele, com comunicação protocolada em juízo (art. 7º, XX). O juiz estar no fórum, ocupado em outra audiência, não afasta o direito.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('311632e9-a664-469f-80f8-12ad266c9f20', 'Há hierarquia entre advogado, juiz e promotor? Como ficam os advogados nas audiências?', 'Não há hierarquia. Nas audiências, os advogados das partes ficam no mesmo plano topográfico e equidistantes do juiz (EAOAB, art. 6º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('074ad26a-2c8f-49e9-8c9a-20f752643e1e', 'Autos sigilosos de investigação: o advogado precisa de procuração? O que a autoridade pode limitar?', 'Sim, só com procuração. A autoridade limita apenas diligências em andamento e ainda não documentadas (art. 7º, §§ 10 e 11).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('30f79656-9a4c-4695-8525-cc11e0e0a114', 'Quais os requisitos para a busca no escritório do advogado?', 'Decisão judicial motivada, indícios de crime do próprio advogado, mandado específico e pormenorizado e representante da OAB presente (art. 7º, § 6º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('38441ff2-a363-46e0-9be7-c4535115fc3f', 'O advogado pode fazer colaboração premiada contra cliente ou ex-cliente?', 'Não. A violação gera processo disciplinar e a pena pode chegar à exclusão (art. 7º, § 6º-I).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('a0f4519b-9a24-42b1-84f7-a08e6770d277', 'Prisão do advogado: o que se exige quando o motivo é ligado à profissão? E quando não é?', 'Ligado à profissão: só flagrante de crime inafiançável e com representante da OAB. Sem relação com a profissão: basta comunicar a Seccional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('bb49c81a-ba31-4518-a739-19c8b35ded98', 'Até quando o advogado tem direito à sala de Estado-Maior? E se não houver?', 'Só antes do trânsito em julgado. Na falta da sala, prisão domiciliar.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('04edcb2a-9818-4bc0-9f93-1c037fad06fc', 'Quais direitos têm a advogada gestante e a adotante ou que deu à luz?', 'Gestante: entra sem detector de metais e tem vaga na garagem. Adotante ou que deu à luz, sendo a única patrona: prazos processuais suspensos (art. 7º-A).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('4b914c34-75b8-449a-bd99-7f2f3165c4a8', 'Quem pode provocar o desagravo público? O ofendido pode dispensá-lo?', 'É promovido de ofício ou a pedido de qualquer pessoa. O ofendido não pode dispensá-lo.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('9e2a8d06-4787-4b8c-9fe7-b611729cfe3f', 'A imunidade profissional do advogado alcança quais crimes?', 'Injúria e difamação — nunca calúnia ou desacato.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('01a79c3d-2b54-47cb-aa59-9d994ab14456', 'Certo ou errado? "Sem estipulação, metade no início e metade no fim"', 'Errado. São terços.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('70a3958f-c730-4bfc-b647-b468d1aca595', 'Certo ou errado? "Prescrição em 3 anos" ou "contada da data do contrato"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('ac5c444f-5d14-49c9-8bda-675566c6b6c2', 'Certo ou errado? "Pode protestar duplicata de honorários"', 'Errado. Só cheque ou promissória.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('006b0c7b-b311-474d-be13-45970120583f', 'Certo ou errado? "Quota litis é proibida"', 'Errado. É permitida, em dinheiro e com limite.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('e4f3b69b-2bea-4bed-991e-71dc891030ce', 'Certo ou errado? "Liberação de até 20% também nos crimes da Lei de Drogas"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('847ed0f4-e9fe-43c5-be21-8a853e24f2ac', 'Certo ou errado? "Substabelecido com reserva sempre precisa da intervenção do substabelecente"', 'Atenção à exceção do contrato próprio com o cliente.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('11b9f946-f5be-4362-beb2-aed13fb9be42', 'Sem estipulação sobre a forma de pagamento, como são pagos os honorários?', '1/3 no início, 1/3 até a decisão de primeira instância e 1/3 no final (art. 22, § 3º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('4fba45b0-c5f8-4152-9000-d2efe7b19668', 'Em quanto tempo prescreve a cobrança de honorários? E a prestação de contas contra o advogado?', 'Ambas em 5 anos (arts. 25 e 25-A).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('88045c75-240c-4f79-be56-3ae138dc864a', 'Bloqueio universal de bens do cliente: quanto o advogado pode liberar para honorários? Há exceção?', 'Até 20% dos bens, salvo nas causas da Lei de Drogas (art. 24-A).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('492138e8-9bbb-46d8-8a37-58b9fdff6d9b', 'Quais os limites da cláusula quota litis?', 'Honorários em dinheiro; somados à sucumbência, não podem superar a vantagem do cliente (CED, art. 50).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('e9f9295d-32a7-469e-8dbe-abfd12ddfd40', 'O advogado pode sacar duplicata para cobrar honorários?', 'Não. Pode emitir fatura e aceitar cartão de crédito (CED, arts. 52 e 53).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('71dc2160-681b-4125-bc05-e4acf97425a1', 'O que o advogado deve fazer antes de cobrar honorários em juízo do próprio cliente?', 'Renunciar antes ao mandato (CED, art. 54).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('527a0f30-4800-4b43-8008-e9b43ac25c3b', 'Certo ou errado? "A censura será publicada"', 'Errado. Não pode ser divulgada.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('a7df7189-048c-4c67-b1ef-53a82b6f6d3a', 'Certo ou errado? "Multa aplicada isoladamente"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('8e24cda7-6421-40b4-a5f1-12df0abcd070', 'Certo ou errado? "Exclusão por maioria absoluta"', 'Errado. 2/3 do Conselho Seccional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('8c3f7dab-5c07-4d0e-ba82-77d5884a056c', 'Certo ou errado? "Suspensão de 12 a 30 meses"', 'Errado. 30 dias a 12 meses.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('0bf21d4e-017f-4f82-aa8f-a4b7fca02c30', 'Certo ou errado? "Suspensão por não pagar anuidade"', 'Não vale mais (STF).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('4520e359-2ea6-4064-934a-d19df6f068e7', 'Certo ou errado? "Reabilitação a qualquer tempo"', 'Errado. 1 ano após cumprir a pena.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('26b46fc9-2ef7-48c2-829b-58740495facd', 'A censura é publicada? Pode ser convertida?', 'Não é publicada e pode virar advertência, em ofício reservado, se houver atenuante.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('63663bc2-793b-4030-8a1a-54c94dcbbb69', 'Qual a duração e a abrangência da suspensão?', 'De 30 dias a 12 meses, em todo o território nacional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('2a793cad-ac04-4cdd-905a-539cf34b4475', 'Quando cabe a exclusão e qual o quórum?', 'Três suspensões, falsa prova de requisito de inscrição, inidoneidade moral ou crime infamante; quórum de 2/3 do Conselho Seccional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('30cbc735-b30c-47e1-a830-2e2264cf904d', 'A multa pode ser aplicada isoladamente?', 'Não. A multa nunca é aplicada sozinha.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('9a95c4aa-43fe-4756-ae55-edb801673f7f', 'Qual o prazo da prescrição disciplinar? E a prescrição intercorrente?', '5 anos da constatação oficial do fato; o processo parado por mais de 3 anos gera prescrição intercorrente (art. 43).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('779af8b7-2f7b-4c01-8c56-d8822c4a37f1', 'Quando o advogado punido pode pedir reabilitação?', '1 ano após cumprir a sanção; se a infração resultou de crime, depende também da reabilitação criminal (art. 41).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('2973aeb4-608b-478e-a51f-2bb4a34ed4f8', 'A anuidade em atraso pode gerar suspensão do advogado?', 'Não. O STF declarou inconstitucional a suspensão por anuidade em atraso.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('686edcbc-52e2-4db6-badc-da8f04cff10b', 'Certo ou errado? "Registro na Junta Comercial"', 'Errado. Só no Conselho Seccional da OAB.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('341fe56d-4a24-410d-b6cb-f8250d692f7e', 'Certo ou errado? "Pode integrar duas sociedades na mesma Seccional se atuar em causas diferentes"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('73ea6d43-0fd8-44ce-a9d7-f1d153b79638', 'Certo ou errado? "Sócios em lados opostos podem atuar se avisarem o juiz ou firmarem termo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('cd3b9859-64af-4175-9372-cc5c3c28b557', 'Certo ou errado? "Responsabilidade solidária e limitada"', 'Errado. Subsidiária e ilimitada.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('fdec84ce-d0b7-4e35-8a53-20469a42e216', 'Certo ou errado? "Sócio eleito prefeito é excluído da sociedade"', 'Errado. Incompatibilidade temporária é averbada, e ele permanece.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('f3e2c397-602b-4f2f-8237-5bf393a84c3d', 'Certo ou errado? "Contrato de associação pode prever que só a sociedade assume os riscos"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('d843ba7d-cd18-4d1e-a396-dce581b86ebf', 'Onde se registra a sociedade de advogados?', 'Só no Conselho Seccional da OAB da sede — nunca na Junta Comercial.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('d33c8fea-1423-4bca-9c45-2b56500dde55', 'Sócios da mesma sociedade podem atuar em lados opostos da mesma causa?', 'Não (art. 15, § 6º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium');--> statement-breakpoint
INSERT INTO `flashcards` (`id`, `front`, `back`, `subject_id`, `training_id`, `difficulty`) VALUES
('2f7fbe2b-1562-47bb-afce-e9f5fb87f123', 'O advogado pode integrar duas sociedades (ou sociedade + unipessoal) na mesma Seccional?', 'Não (art. 15, § 4º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('d43d7f98-44a8-4cc4-8ec0-b631fd7eb02a', 'Como o sócio responde pelos danos causados aos clientes?', 'De forma subsidiária e ilimitada (art. 17).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('1e53d988-5e3d-4d8f-9d1c-481c2af98555', 'Certo ou errado? "O advogado deve seguir a orientação do cliente sobre a estratégia"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('81c7e000-00d2-4e48-bba1-aa0bb0830f0a', 'Certo ou errado? "Renúncia deve declarar o motivo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('7c29d6f6-26c9-4d1e-a35c-836228c6e27b', 'Certo ou errado? "Mandato se extingue após X anos"', 'Errado. , salvo prazo no instrumento.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('eede0491-fc23-4343-ad2e-db3896938daf', 'Certo ou errado? "Substabelecimento com reserva exige ciência do cliente"', 'Errado. Essa exigência é do sem reserva.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('6a0bfc7e-5cc5-4248-b838-6730878c4636', 'Certo ou errado? "Em conflito entre clientes, deve renunciar a todos"', 'Errado. Opta por um.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('ab439a73-cc9a-4e1e-a18d-7d82b8a6095e', 'O mandato se extingue pelo decurso do tempo?', 'Não, salvo se o instrumento fixar prazo (CED, art. 18).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('10f290b1-5c68-44ef-9717-ca50397f02b3', 'Como funciona a renúncia ao mandato?', 'Omite o motivo; notifica-se o cliente, preferencialmente por carta com AR, e o advogado continua representando por 10 dias, salvo substituição antes.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('567676d2-a84d-4912-8c00-cea7fee26bb7', 'O advogado pode aceitar procuração de quem já tem advogado constituído?', 'Só com prévio conhecimento do colega, salvo motivo plenamente justificável ou medidas urgentes e inadiáveis (CED, art. 14).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('347a3564-0ebc-44e0-a3df-b9ab3c0f3582', 'Certo ou errado? "Divulgação conjunta é permitida se as atividades tiverem afinidade ou forem da mesma pessoa"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('0e3a23f6-d66b-4045-90a6-3cf201136204', 'Certo ou errado? "Placa luminosa na fachada é proibida"', 'Errado. Para identificar o escritório, pode.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('84b5725e-c755-43b1-a785-bb2093d01e2c', 'Certo ou errado? "Pode indicar telefone em coluna de jornal"', 'Errado. E-mail pode.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('c6d5680e-b888-4bed-9336-66285e8ead84', 'Certo ou errado? "Cartão pode mencionar que foi juiz ou promotor"', 'Errado. Só professor universitário.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('f981177a-c480-48ed-8bdc-5b2f85ebf25c', 'Certo ou errado? "Fotografia do escritório no cartão é vedada"', 'Errado. Foto do escritório pode; foto pessoal não.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('c6e23233-e016-4987-8787-e8e87f6118eb', 'Certo ou errado? "TAC só para advogado, nunca para estagiário"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('d287f055-ac8c-45c2-a8fa-85671fe9f3b5', 'A advocacia pode ser divulgada em conjunto com outra atividade?', 'Não. A divulgação conjunta é sempre vedada (EAOAB, art. 1º, § 3º; CED, art. 40, IV).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('098cf195-71a0-4fa4-b20d-4fca45a21280', 'O que pode e o que não pode constar no cartão de visita do advogado?', 'Foto do escritório pode; foto pessoal não; cargo ocupado não, salvo o de professor universitário.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('1965fe04-de77-4ba3-b783-34aaf1b56222', 'Certo ou errado? "Atos de não inscrito são anuláveis e podem ser ratificados pelo cliente"', 'Errado. São nulos.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('176f0b4b-c6eb-4131-b8a3-a014be5c3f6b', 'Certo ou errado? "Habeas corpus é privativo de advogado"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('c97b604a-daa3-43ac-803d-19d34cba1b18', 'Certo ou errado? "Consultoria exige contrato escrito ou procuração"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('b71bff7e-5f86-4b90-bb39-a60b45295743', 'Certo ou errado? "Procuração em 15 dias, improrrogáveis"', 'Errado. Prorrogáveis por igual período.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('7f7f42c5-56e5-4093-bda1-fb4df4690262', 'Certo ou errado? "Mandado de segurança pode ser impetrado por qualquer pessoa"', 'Errado. É privativo.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('ccb0e4b4-15db-4049-b703-0e8445384ba2', 'Qual a consequência dos atos privativos praticados por não inscrito ou por advogado suspenso? O habeas corpus é privativo?', 'São nulos. O habeas corpus não é privativo de advogado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('faaaa83f-b288-4682-b440-00db3139403b', 'A consultoria jurídica exige mandato ou contrato?', 'Não. Pode ser verbal, sem mandato e sem contrato (art. 5º, § 4º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('229d8d66-cd00-4032-b210-169bb8dc4e4b', 'Certo ou errado? "Doença mental incurável gera licença"', 'Errado. Gera cancelamento. Curável gera licença.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('0227890a-56b7-458d-bfbb-ac6e4ea849f3', 'Certo ou errado? "Aprovação no Exame de Ordem convalida diploma estrangeiro"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('5e5d9f81-9afa-4239-b9c4-073ba9cbbb43', 'Certo ou errado? "Inidoneidade declarada por maioria simples"', 'Errado. 2/3 de todos os membros.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('86a0ceef-2aec-4e36-872f-44a03f00934a', 'Certo ou errado? "Compromisso pode ser prestado por procurador"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('46521c5a-14ea-4fd0-b824-f5bc6d3c0b68', 'Certo ou errado? "Nova inscrição recupera o número anterior"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('c543e5c0-80ff-4040-87a1-8209f4fb946e', 'Doença mental: quando gera licença e quando gera cancelamento da inscrição?', 'Curável gera licença; incurável gera cancelamento.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('9d063bd9-de4c-4d42-bd95-4d4821ca0480', 'A carteira da OAB vale como identidade?', 'Sim, vale como documento de identidade civil.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('ab8713eb-4445-44fe-9722-d947b8d421c2', 'Certo ou errado? "Ex-presidente tem voz e voto"', 'Errado. Só voz.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('9bcb01a0-a950-43cc-940b-a0145a90a8e4', 'Certo ou errado? "Subseção tem personalidade jurídica própria"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('0ea4027d-adab-4b0b-a8e6-4bc7ddac2f42', 'Certo ou errado? "Intervenção na Caixa é feita pelo Conselho Federal"', 'Errado. Pela Seccional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('12d6a6cd-d2a0-4bdb-a698-b87c01646d7b', 'Certo ou errado? "Caixa não recebe parte das anuidades"', 'Errado. Recebe metade.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('7a4926d0-745a-421b-837d-49d9dcdbc0e6', 'Certo ou errado? "Lista do TRF interestadual é feita pela Seccional da sede"', 'Errado. Conselho Federal.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('d071716e-f09b-485a-a177-3ee5f01e248b', 'Certo ou errado? "Competente é a Seccional da inscrição do advogado"', 'Errado. (para punir); vale o local da infração. Para a suspensão preventiva, porém, é o TED da inscrição principal.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('f53fa625-776e-4aeb-b38d-6868bef6a2c3', 'Certo ou errado? "Suspensão preventiva sem ouvir o advogado"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('b77a59e8-b83d-445a-b829-22968acc8282', 'Certo ou errado? "Processo disciplinar é público"', 'Errado. É sigiloso até o fim.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('818b9485-ef77-4d64-9cd0-1a7f483773ea', 'Certo ou errado? "Denúncia anônima instaura processo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('b605b02c-3231-4284-ad13-1a83674251cf', 'Certo ou errado? "TAC para qualquer infração"', 'Errado. Só puníveis com censura e sem repercussão negativa.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('7cb45d13-a6f8-4530-8680-5299bd414f12', 'Quem tem competência para punir o advogado? E para a suspensão preventiva?', 'Pune a Seccional do local da infração. A suspensão preventiva é do TED da inscrição principal, com oitiva prévia, por até 90 dias.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('09c23922-e5ed-4ad1-a8ef-d4e51021c0da', 'Denúncia anônima instaura processo disciplinar? O processo é público?', 'Não instaura. O processo disciplinar é sigiloso.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('5a1f2771-ad24-40d6-96af-c7f87ec704bb', 'Certo ou errado? "Incompatível pode advogar em causa própria"', 'Errado. A incompatibilidade vale mesmo em causa própria. A exceção criada em 2022 para policiais e militares foi derrubada pelo STF (ADI 7.227).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('58dd6944-b3eb-4a1e-a57a-ecda41fb6324', 'Certo ou errado? "Magistrado licenciado pode advogar"', 'Errado. A incompatibilidade permanece.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('92ad2253-5648-458c-a129-87413bf656be', 'Certo ou errado? "Vereador é incompatível"', 'Errado. É impedido; só o membro da Mesa é incompatível.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('f1dd0135-3c8f-4f74-a012-ee5e6605e710', 'Certo ou errado? "Procurador-Geral pode advogar contra particulares"', 'Errado. Art. 29.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('e0c57476-0f56-484c-8132-a04c57c58818', 'Certo ou errado? "Professor de Direito servidor é impedido contra a Fazenda"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('8edab6ab-4c00-4ece-a8d1-6807cb0842d2', 'Certo ou errado? "Tabelião pode advogar em causa própria"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium');--> statement-breakpoint
INSERT INTO `flashcards` (`id`, `front`, `back`, `subject_id`, `training_id`, `difficulty`) VALUES
('86940161-88e5-4b77-8a81-4e17cf47e9fe', 'Qual a diferença entre incompatibilidade e impedimento?', 'Incompatibilidade é proibição total e vale mesmo em causa própria; impedimento é proibição parcial.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('b8e68318-9e71-40fc-a959-531b14ac07a4', 'Certo ou errado? "Estagiário pode despachar sozinho com o juiz"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('0e7d15f1-4bb3-4887-94bf-a96d95b56ec2', 'Certo ou errado? "Estagiário pode ir a ato extrajudicial sozinho sem autorização"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('6d9b38c4-8700-4e16-8791-218835caf95e', 'Certo ou errado? "Aluno com atividade incompatível não pode estagiar"', 'Errado. Pode estagiar na faculdade, só não pode se inscrever.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('a24fb508-0242-427c-98bf-eaca7771c5ed', 'Certo ou errado? "Bacharel não pode ser estagiário"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('e3f498f4-c728-49ac-a129-57d7fad3dc86', 'Certo ou errado? "Inscrição de estagiário na Seccional do domicílio"', 'Errado. Do curso.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('2649b55d-e0ab-4bd9-96f3-800394c1bb46', 'Que atos o estagiário pode praticar sozinho?', 'Retirar e devolver autos (carga), obter certidões e assinar petição de juntada de documentos (RG, art. 29, § 1º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('bec074b2-5964-4d96-a7ae-11c24a65e198', 'Certo ou errado? "Com autorização do cliente, é obrigado a depor"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('dd97bdd6-2775-4140-b3ca-5d4737935647', 'Certo ou errado? "Encerrado o contrato, acaba o sigilo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('22e283c7-b2e8-4662-a97a-7c922ec2cf90', 'Certo ou errado? "Em crimes graves, o juiz pode obrigá-lo a depor sobre fatos sigilosos"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('3c93294a-8266-49e3-9d3d-1ea101670f02', 'Certo ou errado? "Fatos conhecidos como conselheiro da OAB não são sigilosos"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('aa718c66-d874-4c01-9ecb-9f2f8e8225c4', 'O advogado pode recusar-se a depor sobre fato sigiloso mesmo autorizado pelo cliente?', 'Sim. O sigilo é de ordem pública: pode recusar-se a depor mesmo autorizado ou solicitado pelo cliente.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('a0077f4f-0690-43fd-99c1-f2080841ed9c', 'Certo ou errado? "Responsabilidade subsidiária na lide temerária"', 'Errado. Solidária.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('20147b36-3b90-4ed4-b079-d585207f0bbe', 'Certo ou errado? "Apurada nos próprios autos"', 'Errado. Em ação própria.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('ecd3da01-a8ce-4e18-977b-583ba31fd8f0', 'Certo ou errado? "Responde sempre que a lide for temerária"', 'Errado. Exige coligação para lesar a parte contrária.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('47b35791-0804-452f-b969-4f67a033fd87', 'Certo ou errado? "Advogado empregado não pode recusar causa do empregador"', 'Errado. Nas hipóteses do art. 4º, parágrafo único.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('e682283e-af04-493a-84e8-af25f4372385', 'Certo ou errado? "5 anos para Conselheiro Seccional"', 'Errado. Desde 2019: 3 anos.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('b92292c7-ce58-409a-96fc-41ed72dc51c9', 'Certo ou errado? "Condenado nunca mais pode se candidatar"', 'Errado. Com reabilitação, pode.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('3899fb60-05f7-4e74-b1f6-bcfc560b5c77', 'Certo ou errado? "Só a suspensão extingue o mandato"', 'Errado. Qualquer condenação disciplinar.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('98bddecb-ad4f-47c3-947d-6e715b4374fb', 'Certo ou errado? "Voto facultativo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('77df8504-58da-4eda-bc08-1745c0616e7d', 'Certo ou errado? "Hora extra com adicional de 50%, se o contrato prever"', 'Errado. Mínimo de 100%, mesmo com contrato.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('96eb6f2f-2245-4718-82bf-4aa4629577db', 'Certo ou errado? "Jornada de 10 horas em 4 dias, somando 40 semanais"', 'Errado. O limite diário de 8 horas também vale.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('3f02f658-a804-4a13-b6ad-5f4b88b3e808', 'Certo ou errado? "Sucumbência pertence ao empregador"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('2e6052a0-3f69-4de7-8509-24d1c6acbfe7', 'Certo ou errado? "Noturno das 22h às 5h, com 20%"', 'Errado. 20h às 5h, 25%.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('ca56f850-e9f9-41da-8be5-c94202ad799f', 'Certo ou errado? "Recurso contra decisão da Subseção vai ao Conselho Federal"', 'Errado. Vai ao Conselho Seccional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('42d6ad3b-c53e-4da6-a5dc-e0cef91bea94', 'Certo ou errado? "Decisão unânime da Seccional nunca é recorrível"', 'Errado. Cabe recurso se a decisão unânime contrariar o Estatuto, decisão do Conselho Federal ou de outro Conselho Seccional, o Regulamento Geral, o CED ou os Provimentos (art. 75).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('b76c7f3c-2373-4ea1-8bbf-0dfe4073f752', 'Certo ou errado? "Recurso contra suspensão preventiva tem efeito suspensivo"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('cdbd2f90-13b4-4b7c-a6c8-2d35c19f5cb3', 'Certo ou errado? "Prazo de 10 dias"', 'Errado. 15.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('1e093a1a-f3e4-4208-9962-dc786c87743d', 'Certo ou errado? "Pro bono habitual ou permanente"', 'Errado. É eventual.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('736b56c6-cb29-4bc1-b3b3-cc9b973aba04', 'Certo ou errado? "Pode cobrar preço simbólico"', 'Errado. É gratuita.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('f2a8ec23-441e-4b7d-a3e0-9982b2b600cf', 'Certo ou errado? "Pode ser usada para divulgar o escritório"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('69c0f153-5d05-4b43-9e9c-deafdfed717d', 'Quem exerce advocacia pública e se sujeita ao Estatuto (art. 3º, § 1º)?', 'Os integrantes da AGU, da Procuradoria da Fazenda Nacional e das Procuradorias e Consultorias Jurídicas dos Estados, DF, Municípios e respectivas entidades da Administração indireta e fundacional.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('c2f39ba8-9712-432b-9430-95566ada71db', 'O advogado público precisa de inscrição na OAB? Pode integrar órgãos da Ordem?', 'Sim, a inscrição é obrigatória (STF, Tema 936). É elegível e pode integrar qualquer órgão da OAB (RG, art. 9º).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('019fe1c1-4458-4fdd-8622-bc01ecd5c9ac', 'Quem julga disciplinarmente o advogado público pela sua atuação funcional?', 'A corregedoria do próprio órgão, e não o TED da OAB (STF, RE 609.517, Tema 936, 2026).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('70d5952b-0556-482b-998e-011b409bb588', 'O defensor público precisa de inscrição na OAB?', 'Não. Pelo STF (ADI 4.636), sua capacidade postulatória decorre da nomeação e posse no cargo.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('3dea86df-d0e7-443f-a42f-e49af069c519', 'Advogados públicos podem receber honorários de sucumbência?', 'Sim, são constitucionais, respeitado o teto remuneratório (STF, ADI 6.053).', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('e6ea1fdc-49b0-496c-a23b-aa5f79ce62be', 'Certo ou errado? "Integrante de comissão pode vender imóvel à Seccional por preço de mercado"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('3a24705f-9260-4de6-9002-837811693f7e', 'Certo ou errado? "Conselheiro pode defender colega em processo disciplinar"', 'Errado. , salvo causa própria.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium'),
('12b41fbc-510e-4b1d-8c31-24194cd7b723', 'Certo ou errado? "Contrato gratuito também é vedado"', 'Errado.', (SELECT `id` FROM `subjects` WHERE `name` = 'Estatuto da Advocacia e Ética Profissional' LIMIT 1), '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74', 'medium');--> statement-breakpoint
UPDATE `training_days` d
SET d.`estimated_hours` = ROUND((SELECT SUM(t.`estimated_minutes`) FROM `training_topics` t WHERE t.`training_day_id` = d.`id`) / 60, 1)
WHERE d.`training_id` = '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74';--> statement-breakpoint
UPDATE `trainings`
SET `hours_per_day` = GREATEST(1, (SELECT ROUND(AVG(d.`estimated_hours`), 1) FROM `training_days` d WHERE d.`training_id` = '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74'))
WHERE `id` = '51eacdc1-6ecc-4404-afd8-cf7b1ea56b74';
